//! Runs a Java mod's entrypoint on an embedded JVM, against a façade jar
//! generated by `horizon-port-pack facade` (`docs/java-mod-compat.md`,
//! phase 1's first slice).
//!
//! ```sh
//! horizon-jvm [--entry dev.example.MyMod] [--mixin-config demo.mixins.json] \
//!     [--fabric-development] --stubs facade.jar --loader fabric-loader.jar \
//!     --libs ~/.minecraft/libraries mod.jar [more jars...]
//! ```
//!
//! The supplied jars also go to Fabric Loader through its documented
//! `fabric.addMods` developer property, so the loader itself registers their
//! mixin configs and entrypoints instead of only this runner's own scans.
//!
//! The façade's methods throw `UnsupportedOperationException` naming
//! themselves, so the first one the mod reaches is the next thing the game
//! must implement. That is this binary's job today: prove the attach path and
//! get the exact failure.
use jni::{
    InitArgsBuilder, JNIEnv, JNIVersion, JavaVM,
    objects::{JClass, JObject, JObjectArray, JValue, JValueOwned},
};
use std::{
    ffi::OsString,
    fs::{self, File},
    io::Read,
    net::TcpListener,
    path::{Path, PathBuf},
    process::{Command, ExitCode, Stdio},
    time::{SystemTime, UNIX_EPOCH},
};

/// Owns extracted Fabric nested jars for the duration of the JVM.
struct NestedJars {
    root: PathBuf,
}

#[cfg(test)]
mod remap_tests {
    use super::*;

    #[test]
    fn parses_synthetic_tiny_v2_intermediary_tree() {
        let fixture = "tiny\t2\t0\tofficial\tintermediary\tnamed\nc\tnet/minecraft/Server\ta\tServer\n\tm\t()V\tstart\tb\tstartServer\n";
        let tree = parse_mappings(fixture).expect("synthetic mappings should parse");
        assert_eq!(tree.source, "intermediary");
        assert_eq!(tree.target, "official");
        assert_eq!(tree.classes, 1);
        assert_eq!(tree.members, 1);
        assert!(remap_report_line(&Ok(tree)).starts_with("remap: ok 1 entries"));
    }
}

impl NestedJars {
    fn new() -> Result<Self, String> {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|e| format!("clock: {e}"))?
            .as_nanos();
        let root = std::env::temp_dir().join(format!("horizon-jvm-{}-{stamp}", std::process::id()));
        fs::create_dir_all(&root).map_err(|e| format!("{}: {e}", root.display()))?;
        Ok(Self { root })
    }
}

impl Drop for NestedJars {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

/// Second gate for `--launch-game`: without `1` the flag only reports a skip.
const HORIZON_REAL_LAUNCH_ENV: &str = "HORIZON_REAL_LAUNCH";
/// What `--launch-game` reports when the second gate is missing.
const LAUNCH_GAME_GATE_SKIPPED: &str = "skipped (HORIZON_REAL_LAUNCH is not 1)";
/// Wall-clock bound for the gated launch child.
const LAUNCH_GAME_TIMEOUT_SECS: u64 = 180;
/// Override for [`LAUNCH_GAME_TIMEOUT_SECS`]; the gated test sets it so a run
/// that does not stop on its own cannot hold the suite for three minutes.
const LAUNCH_GAME_TIMEOUT_ENV: &str = "HORIZON_LAUNCH_TIMEOUT_SECS";
/// Bytes of a child stream kept for the status line; the rest is drained.
const LAUNCH_CAPTURE_BYTES: usize = 64 * 1024;
/// Characters of that output echoed to stderr when the launch did not exit 0.
const LAUNCH_OUTPUT_ECHO_CHARS: usize = 4000;
const LAUNCH_SERVER_PORT_ENV: &str = "HORIZON_SERVER_PORT";

/// The second `--launch-game` gate.
fn real_launch_enabled() -> bool {
    std::env::var(HORIZON_REAL_LAUNCH_ENV).is_ok_and(|value| value.trim() == "1")
}

const LOADER_BRIDGE_SOURCE: &str = r#"
import java.io.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;

/** Small reflection-only bridge used by the embedded Fabric probe. */
@SuppressWarnings({"unchecked", "rawtypes"})
public final class HorizonLoaderBridge {
  private HorizonLoaderBridge() {}
  private static boolean testLaunchCalled;

  // ---- Optional Knot classpath unlock -----------------------------------
  //
  // Fabric's own launch registers the game jars and every discovered mod's
  // code sources on Knot's class loader: `GameProvider.unlockClassPath(...)`
  // for the game (`MinecraftGameProvider` adds its `gameJars`,
  // `realmsJar` and `miscGameLibraries`) and `FabricLoaderImpl.freeze()` ->
  // `finishModLoading()` for the mods. Both funnel into
  // `Knot.addToClassPath(Path, String...)`, which is
  // `KnotClassLoaderInterface.setAllowedPrefixes(path, ...)` followed by
  // `KnotClassLoaderInterface.addCodeSource(path)`. This probe is not Knot,
  // so it builds that same `KnotClassLoaderInterface` through
  // `KnotClassLoaderInterface.create(useParentClassLoader, isDevelopment,
  // envType, provider)` and routes the launcher's `addToClassPath` /
  // `setAllowedPrefixes` into it. `ok` is only reported after a real class is
  // read back out of a registered jar through the Knot loader, so it means
  // the classpath resolves classes rather than that a method returned.
  private static boolean classPathUnlock;
  private static Object classPath;
  private static Class<?> classPathType;
  private static final List<String> classPathJars = new ArrayList<>();
  private static final List<Path> initialClassPath = new ArrayList<>();
  private static String classPathFailure;
  private static String knotInitOutcome;
  private static String knotMixinOutcome;
  private static String launchGameOutcome;

  /**
   * The bundled Minecraft jar carries its own Log4j classes.  A probe also
   * has loader libraries on the system class path; letting the provider's
   * Log4j handler see both copies makes Log4j's `UpperLookup` fail its
   * cross-class-loader cast.  Real game launches use Fabric's public console
   * handler for the loader phase, so exactly one handler owns the log stream.
   */
  private static void installPlainLogHandler() throws Exception {
    Class<?> log = Class.forName("net.fabricmc.loader.impl.util.log.Log");
    Class<?> handler = Class.forName("net.fabricmc.loader.impl.util.log.LogHandler");
    Object console = Class.forName("net.fabricmc.loader.impl.util.log.ConsoleLogHandler")
        .getConstructor().newInstance();
    log.getMethod("init", handler).invoke(null, console);
  }

  // ---- Optional Knot loader hand-off and transform-chain probe -----------
  //
  // `--knot-launch` uses the loader `KnotClassLoaderInterface.create` built:
  // `getClassLoader()` is the class loader `Knot.init` returns to a real
  // launch, so it becomes the launcher's target (see `targetLoader`), and a
  // class read through it proves `KnotClassDelegate.loadClass` really routes
  // through `getPostMixinClassByteArray` -> `IMixinTransformer`.
  private static boolean knotLaunch;
  private static ClassLoader knotLoader;
  private static String knotLaunchOutcome;
  private static String knotTransformedClass;
  private static final String PROBE_MARKER = "KNOT-RAW";
  private static final String PROBE_REPLACEMENT = "KNOT-OK!";

  public static boolean testLaunchCalled() { return testLaunchCalled; }

  /** Reset the unlock state; called once at the start of a production run. */
  private static void resetClassPathState(boolean unlock, boolean launch) {
    classPathUnlock = unlock;
    knotLaunch = launch;
    knotLoader = null;
    knotLaunchOutcome = null;
    knotTransformedClass = null;
    classPath = null;
    classPathType = null;
    classPathJars.clear();
    initialClassPath.clear();
    classPathFailure = null;
    knotInitOutcome = null;
    knotMixinOutcome = null;
    launchGameOutcome = null;
  }

  /** Build the Knot class loader/registry `unlockClassPath` writes into. */
  private static synchronized void initClassPath(Object provider, Class<?> providerClass,
      boolean client, boolean development) {
    try {
      Class<?> type = Class.forName("net.fabricmc.loader.impl.launch.knot.KnotClassLoaderInterface");
      Class<?> envType = Class.forName("net.fabricmc.api.EnvType");
      Object side = Enum.valueOf((Class) envType, client ? "CLIENT" : "SERVER");
      // Knot's own choice: `provider.requiresUrlClassLoader()` or the
      // compatibility-class-loader property.
      boolean compatibility = System.getProperty("fabric.loader.useCompatibilityClassLoader") != null
          || Boolean.TRUE.equals(providerClass.getMethod("requiresUrlClassLoader").invoke(provider));
      Method create = type.getDeclaredMethod("create", boolean.class, boolean.class, envType,
          Class.forName("net.fabricmc.loader.impl.game.GameProvider"));
      create.setAccessible(true);
      classPath = create.invoke(null, compatibility, development, side, provider);
      classPathType = type;
      // `Knot.init` creates its loader from `java.class.path` and keeps those
      // entries as the parent-visible classpath (loader, libraries, stubs).
      // They are not code sources of this loader, so the provider's
      // `setValidParentClassPath` must allow them explicitly.
      initialClassPath.clear();
      String systemPath = System.getProperty("java.class.path", "");
      for (String entry : systemPath.split(File.pathSeparator)) {
        if (entry.isEmpty()) continue;
        Path path = Paths.get(entry);
        if (Files.exists(path) && !initialClassPath.contains(path)) initialClassPath.add(path);
      }
      registerValidParentClassPath(initialClassPath);
      if (knotLaunch) {
        // Capture the loader now; the context loader switches after provider
        // initialization so Log4j setup sees only the parent copy.
        Method getLoader = type.getDeclaredMethod("getClassLoader");
        getLoader.setAccessible(true);
        Object loader = getLoader.invoke(classPath);
        if (loader instanceof ClassLoader) {
          knotLoader = (ClassLoader) loader;
        }
      }
    } catch (Throwable failure) {
      classPathFailure = "Knot class loader unavailable: " + summarize(failure);
    }
  }

  /**
   * `FabricLauncher.setValidParentClassPath`, which
   * `MinecraftGameProvider.initialize` calls with the classifier's system
   * libraries. The probe's initial classpath entries (loader, libraries,
   * stubs) join that set so the game can still read them through the parent
   * class loader; the game's own jars stay code sources.
   */
  private static synchronized void registerValidParentClassPath(Collection<?> paths) {
    if (!classPathUnlock || classPath == null) return;
    try {
      Set<Path> allowed = new LinkedHashSet<>(initialClassPath);
      if (paths != null) {
        for (Object path : paths) {
          if (path instanceof Path) allowed.add((Path) path);
        }
      }
      Method set = classPathType.getDeclaredMethod("setValidParentClassPath", Collection.class);
      set.setAccessible(true);
      set.invoke(classPath, allowed);
    } catch (Throwable failure) {
      if (classPathFailure == null) classPathFailure = "setValidParentClassPath: " + summarize(failure);
    }
  }

  /**
   * What `FabricLauncher.addToClassPath`/`setAllowedPrefixes` do with the flag
   * on. `allowedPrefixes` is the first half of `Knot.addToClassPath`; the code
   * source is the half that makes the jar loadable.
   */
  private static synchronized void addClassPathEntry(Object path, String[] prefixes, boolean codeSource) {
    if (!classPathUnlock || path == null) return;
    if (classPath == null) {
      if (classPathFailure == null) classPathFailure = "Knot class loader was not created";
      return;
    }
    try {
      Path entry = Paths.get(String.valueOf(path));
      Method setPrefixes = classPathType.getDeclaredMethod("setAllowedPrefixes", Path.class, String[].class);
      setPrefixes.setAccessible(true);
      setPrefixes.invoke(classPath, entry, prefixes == null ? new String[0] : prefixes);
      if (!codeSource) return;
      // Minecraft's bundler supplies Log4j jars through a separate capture
      // loader. Keep them parent-visible only; registering them as Knot code
      // sources beside the loader's copy recreates Log4j's UpperLookup cast.
      if (knotLaunch && isLoggingJar(entry)) return;
      Method add = classPathType.getDeclaredMethod("addCodeSource", Path.class);
      add.setAccessible(true);
      add.invoke(classPath, entry);
      String name = entry.toAbsolutePath().normalize().toString();
      if (!classPathJars.contains(name)) classPathJars.add(name);
    } catch (Throwable failure) {
      if (classPathFailure == null) classPathFailure = summarize(failure);
    }
  }

  private static boolean isLoggingJar(Path path) {
    String name = path.getFileName().toString().toLowerCase(Locale.ROOT);
    return name.startsWith("log4j-") || name.startsWith("slf4j-");
  }

  /** `ok <n> jars`, or `failed <reason>`; never more than 400 characters. */
  private static synchronized String classPathOutcome() {
    if (classPathFailure != null) return bound("failed " + classPathFailure);
    if (classPath == null) return "failed Knot class loader was not created";
    String probe = verifyClassPath();
    if (probe != null) return bound("failed " + probe);
    return "ok " + classPathJars.size() + " jars";
  }

  /** Initialize Fabric's Mixin transformer through Knot's loader API. */
  private static synchronized String initializeKnotTransformers() {
    if (classPath == null) return "failed Knot class loader was not created";
    try {
      Method initialize = classPathType.getDeclaredMethod("initializeTransformers");
      initialize.setAccessible(true);
      initialize.invoke(classPath);
      // KnotClassDelegate installs one IMixinTransformer; the API is void, so
      // this is the number of transformers that this initialization call owns.
      return "ok 1 transformers";
    } catch (Throwable failure) {
      return bound("failed " + summarize(failure));
    }
  }

  /**
   * `FabricLauncher.getClassByteArray(name, runTransformers)`, which
   * `Knot.getClassByteArray` answers with
   * `KnotClassDelegate.getPostMixinClassByteArray` (public interface method in
   * newer loaders, private on the delegate in 0.20.x). Without this, the
   * launcher read raw system-loader resources and the game's first transformed
   * class would bypass Mixin.
   */
  private static byte[] classBytes(String name, boolean runTransformers) {
    if (classPath == null) return null;
    try {
      String internal = name.replace('.', '/');
      if (!runTransformers) {
        Method raw = classPathType.getDeclaredMethod("getRawClassBytes", String.class);
        raw.setAccessible(true);
        return (byte[]) raw.invoke(classPath, internal);
      }
      Method post;
      try {
        post = classPathType.getDeclaredMethod("getPostMixinClassByteArray", String.class, boolean.class);
      } catch (NoSuchMethodException older) {
        // 0.20.x keeps the post-mixin read private on the delegate.
        post = classPath.getClass().getDeclaredMethod("getPostMixinClassByteArray", String.class, boolean.class);
      }
      post.setAccessible(true);
      return (byte[]) post.invoke(classPath, name, Boolean.TRUE);
    } catch (Throwable failure) {
      if (classPathFailure == null) classPathFailure = "getClassByteArray: " + summarize(failure);
      return null;
    }
  }

  /** `FabricLauncher.isClassLoaded`, through KnotClassLoaderInterface. */
  private static boolean classLoaded(String name) {
    if (classPath == null) return false;
    try {
      Method loaded = classPathType.getDeclaredMethod("isClassLoaded", String.class);
      loaded.setAccessible(true);
      return Boolean.TRUE.equals(loaded.invoke(classPath, name));
    } catch (Throwable failure) {
      return false;
    }
  }

  /**
   * Load a class through Knot and read a static method back, proving a real
   * Mixin config applied to it. The spec is `class#method=expected`; the probe
   * only runs when the caller supplied one (and needs no game).
   */
  private static synchronized String probeMixinApplication(String spec) {
    if (spec == null || spec.isEmpty()) return null;
    if (classPath == null) return "failed Knot class loader was not created";
    int hash = spec.indexOf('#');
    int equals = hash < 0 ? -1 : spec.indexOf('=', hash + 1);
    if (hash <= 0 || equals <= hash + 1) return "failed malformed mixin probe '" + spec + "'";
    String className = spec.substring(0, hash);
    String method = spec.substring(hash + 1, equals);
    String expected = spec.substring(equals + 1);
    try {
      Method load = classPathType.getDeclaredMethod("loadIntoTarget", String.class);
      load.setAccessible(true);
      Class<?> loaded = (Class<?>) load.invoke(classPath, className);
      Object value = loaded.getMethod(method).invoke(null);
      if (!expected.equals(String.valueOf(value))) {
        return bound("failed " + className + "." + method + " returned " + value);
      }
      return "ok applied=" + className + '#' + method;
    } catch (Throwable failure) {
      return bound("failed " + summarize(failure));
    }
  }

  /**
   * The `preLaunch` entrypoints `Knot.init` invokes after unlocking the
   * classpath and before `provider.launch`. Returns null on success.
   */
  private static String invokePreLaunch(Object loader, Class<?> impl) {
    try {
      Class<?> type = Class.forName("net.fabricmc.loader.api.entrypoint.PreLaunchEntrypoint");
      List<?> containers = (List<?>) impl
          .getMethod("getEntrypointContainers", String.class, Class.class)
          .invoke(loader, "preLaunch", type);
      Method entrypoint = Class.forName("net.fabricmc.loader.api.entrypoint.EntrypointContainer")
          .getMethod("getEntrypoint");
      Method onPreLaunch = type.getMethod("onPreLaunch");
      for (Object container : containers) {
        try {
          onPreLaunch.invoke(entrypoint.invoke(container));
        } catch (Throwable failure) {
          // A preLaunch callback is mod code. One client-only callback (for
          // example MagicLib's nested platform probe) must not prevent the
          // server and the remaining callbacks from starting.
          System.err.println("fabric-loader: preLaunch callback skipped: " + summarize(failure));
        }
      }
      return null;
    } catch (Throwable failure) {
      return summarize(failure);
    }
  }

  /**
   * `provider.launch(knotLoader)`: the same hand-off `Knot.launch` makes after
   * `Knot.init` returns its loader. The caller has already loaded, frozen,
   * bootstrapped Mixin, initialized transformers and unlocked the classpath,
   * so this is where the real game starts. The embedded JVM is the caller's
   * process: a game that calls `System.exit` ends it, and a game whose
   * `main` returns ends up here with `exit 0`.
   */
  private static String launchTheGame(Object provider, Class<?> providerIface) {
    try {
      if (knotLoader == null) return "failed Knot class loader was not created";
      System.out.println("launch-game: started");
      System.out.flush();
      providerIface.getMethod("launch", ClassLoader.class).invoke(provider, knotLoader);
      // Fabric's provider starts the server on its own non-daemon thread and
      // returns from this reflective hand-off. Keep the embedded JVM alive
      // until those game threads finish so the Rust supervisor can observe
      // the real process exit (or enforce its timeout).
      waitForGameThreads();
      return "exit 0";
    } catch (Throwable failure) {
      return bound("failed " + summarize(failure));
    }
  }

  private static void waitForGameThreads() throws InterruptedException {
    Thread current = Thread.currentThread();
    for (;;) {
      boolean live = false;
      for (Thread thread : Thread.getAllStackTraces().keySet()) {
        if (thread == current || !thread.isAlive() || thread.isDaemon()) continue;
        live = true;
        thread.join(250L);
      }
      if (!live) return;
    }
  }

  /**
   * The Mixin steps `Knot.init` runs between `freeze` and the delegate's
   * `initializeTransformers`: `FabricLoaderImpl.loadClassTweakers`,
   * `FabricMixinBootstrap.init(envType, loader)` (which points Mixin at
   * `MixinServiceKnot` and calls `MixinBootstrap.init`) and
   * `FabricLauncherBase.finishMixinBootstrapping` (Mixin to DEFAULT phase).
   * Without them `MixinServiceKnot.getTransformer()` stays null and the
   * delegate's reflective fallback cannot construct mixin 0.8.7's
   * `MixinTransformer`: it has no no-arg constructor, so the delegate reports
   * "mixin transformer unavailable?".
   */
  private static String initializeMixinBootstrap(Object loader, Class<?> impl, boolean client) {
    try {
      impl.getMethod("loadClassTweakers").invoke(loader);
      Object side = Enum.valueOf((Class) Class.forName("net.fabricmc.api.EnvType"),
          client ? "CLIENT" : "SERVER");
      Class<?> bootstrap = Class.forName("net.fabricmc.loader.impl.launch.FabricMixinBootstrap");
      bootstrap.getMethod("init", Class.forName("net.fabricmc.api.EnvType"), impl)
          .invoke(null, side, loader);
      Method finish = Class.forName("net.fabricmc.loader.impl.launch.FabricLauncherBase")
          .getDeclaredMethod("finishMixinBootstrapping");
      finish.setAccessible(true);
      finish.invoke(null);
      return null;
    } catch (Throwable failure) {
      return summarize(failure);
    }
  }

  /**
   * Hand the Knot loader to the launcher and prove its transformer chain runs.
   *
   * Fabric has no `setTargetClassLoader`: `FabricLauncher.getTargetClassLoader`
   * is the only hand-off a provider/entrypoint uses, and the real
   * `Knot.init(String[])` returns `KnotClassLoaderInterface.getClassLoader()` as
   * the game's loader. This probe owns the launcher, so it stores that loader
   * and answers every target read with it (`targetLoader`).
   *
   * The chain itself is proven the way `KnotClassDelegate.loadClass` exercises
   * it. The installed `IMixinTransformer` (the delegate's `mixinTransformer`
   * field) is wrapped by a probe transformer that rewrites one marker constant
   * in any class carrying it, then a class from a registered mod jar is loaded
   * through the loader (`loadIntoTarget` -> `tryLoadClass` ->
   * `getPostMixinClassByteArray` -> `transformClassBytes`). The loaded class's
   * `message()` returning the rewritten value means the bytes the JVM defined
   * were not the raw jar bytes; the raw bytes on disk still carry the marker.
   * Mixin's own `getTransformers()` cannot stand in for this proof: Fabric's
   * `MixinServiceKnot.getTransformers()` returns `Collections.emptyList()`.
   */
  private static synchronized String probeTransformChain() {
    if (classPath == null) return "failed Knot class loader was not created";
    try {
      Method getLoader = classPathType.getDeclaredMethod("getClassLoader");
      getLoader.setAccessible(true);
      Object loader = getLoader.invoke(classPath);
      if (!(loader instanceof ClassLoader)) return "failed Knot loader is unavailable";
      knotLoader = (ClassLoader) loader;
      // `Knot.init` also makes its loader the thread's context class loader;
      // the hand-off is the same one a real launch makes.
      Thread.currentThread().setContextClassLoader(knotLoader);

      Field transformerField = classPath.getClass().getDeclaredField("mixinTransformer");
      transformerField.setAccessible(true);
      Object transformer = transformerField.get(classPath);
      if (transformer == null) return "failed Knot installed no mixin transformer";
      Class<?> transformerType =
          Class.forName("org.spongepowered.asm.mixin.transformer.IMixinTransformer");
      if (!transformerType.isInstance(transformer)) {
        return "failed Knot transformer is not an IMixinTransformer";
      }
      Object probe = Proxy.newProxyInstance(transformerType.getClassLoader(),
          new Class<?>[]{transformerType}, (p, m, a) -> invokeTransformProbe(transformer, m, a));
      transformerField.set(classPath, probe);

      String className = findMarkerClass();
      if (className == null) {
        return "failed no class carrying " + PROBE_MARKER + " in the unlocked jars";
      }
      Method load = classPathType.getDeclaredMethod("loadIntoTarget", String.class);
      load.setAccessible(true);
      // `loadIntoTarget` takes a binary (dot) name; the transformer reports the
      // internal (slash) one.
      Class<?> loaded = (Class<?>) load.invoke(classPath, className.replace('/', '.'));
      Object value = loaded.getMethod("message").invoke(null);
      if (!PROBE_REPLACEMENT.equals(value)) {
        return "failed the loaded class returned " + value;
      }
      if (knotTransformedClass == null) {
        return "failed the transformer never saw " + className.replace('/', '.');
      }
      return "ok 1 transformers, transformed=" + knotTransformedClass.replace('/', '.');
    } catch (Throwable failure) {
      return bound("failed " + summarize(failure));
    }
  }

  /** The probe transformer: rewrite the marker, delegate everything else. */
  private static Object invokeTransformProbe(Object transformer, Method method, Object[] args)
      throws Throwable {
    if ("transformClassBytes".equals(method.getName()) && args != null && args.length == 3
        && args[2] instanceof byte[]) {
      byte[] rewritten = rewriteMarker((byte[]) args[2]);
      if (rewritten != null) {
        knotTransformedClass = String.valueOf(args[0]);
        return rewritten;
      }
    }
    try {
      return method.invoke(transformer, args);
    } catch (java.lang.reflect.InvocationTargetException failure) {
      throw failure.getCause();
    }
  }

  /** Replace the marker constant in place, or null when the class has none. */
  private static byte[] rewriteMarker(byte[] classBytes) {
    byte[] marker = PROBE_MARKER.getBytes(java.nio.charset.StandardCharsets.US_ASCII);
    byte[] replacement =
        PROBE_REPLACEMENT.getBytes(java.nio.charset.StandardCharsets.US_ASCII);
    for (int at = 0; at <= classBytes.length - marker.length; at++) {
      boolean match = true;
      for (int i = 0; i < marker.length; i++) {
        if (classBytes[at + i] != marker[i]) {
          match = false;
          break;
        }
      }
      if (!match) continue;
      // Equal-length constants keep the class file valid: only the UTF8 bytes
      // the string constant points at change.
      byte[] out = classBytes.clone();
      System.arraycopy(replacement, 0, out, at, replacement.length);
      return out;
    }
    return null;
  }

  /** The first registered class whose bytes carry the probe marker. */
  private static String findMarkerClass() {
    for (String jar : classPathJars) {
      Path path = Paths.get(jar);
      if (!Files.isRegularFile(path)) continue;
      try (java.util.zip.ZipFile zip = new java.util.zip.ZipFile(path.toFile())) {
        Enumeration<? extends java.util.zip.ZipEntry> entries = zip.entries();
        while (entries.hasMoreElements()) {
          java.util.zip.ZipEntry entry = entries.nextElement();
          String name = entry.getName();
          if (name.startsWith("META-INF/") || !name.endsWith(".class")) continue;
          try (InputStream in = zip.getInputStream(entry)) {
            if (rewriteMarker(in.readAllBytes()) != null) {
              return name.substring(0, name.length() - 6);
            }
          } catch (Throwable ignored) {
            // An entry the probe cannot read simply is not the fixture.
          }
        }
      } catch (Throwable ignored) {
        // A jar the probe cannot open simply does not carry the fixture.
      }
    }
    return null;
  }

  private static String bound(String text) {
    if (text.length() <= 400) return text;
    return text.substring(0, 400);
  }

  /**
   * Read one class back through the Knot loader: proof the registered code
   * source is loadable, not merely recorded. Reads bytes only; no class is
   * initialized and the game never starts.
   */
  private static String verifyClassPath() {
    int checked = 0;
    for (String name : classPathJars) {
      Path path = Paths.get(name);
      String className = firstClassName(path);
      if (className == null) continue;
      checked++;
      try {
        Method raw = classPathType.getDeclaredMethod("getRawClassBytes", String.class);
        raw.setAccessible(true);
        byte[] bytes = (byte[]) raw.invoke(classPath, className);
        if (bytes != null && bytes.length > 0) return null;
      } catch (Throwable failure) {
        return "classpath probe: " + summarize(failure);
      }
    }
    return checked == 0 ? null : "registered jars did not resolve their own classes";
  }

  /** The first ordinary class entry in a jar, as an internal name. */
  private static String firstClassName(Path path) {
    if (!Files.isRegularFile(path)) return null;
    try (java.util.zip.ZipFile zip = new java.util.zip.ZipFile(path.toFile())) {
      Enumeration<? extends java.util.zip.ZipEntry> entries = zip.entries();
      while (entries.hasMoreElements()) {
        String entry = entries.nextElement().getName();
        if (entry.startsWith("META-INF/") || !entry.endsWith(".class")) continue;
        if (entry.equals("module-info.class") || entry.endsWith("/module-info.class")) continue;
        if (entry.endsWith("/package-info.class") || entry.equals("package-info.class")) continue;
        return entry.substring(0, entry.length() - 6);
      }
    } catch (Throwable ignored) {
      // A jar the probe cannot open simply does not verify; the next one can.
    }
    return null;
  }

  public static void seed(String id, String version) throws Exception {
    Class<?> impl = Class.forName("net.fabricmc.loader.impl.FabricLoaderImpl");
    Object loader = impl.getField("INSTANCE").get(null);
    Class<?> modContainer = Class.forName("net.fabricmc.loader.api.ModContainer");
    Class<?> metadata = Class.forName("net.fabricmc.loader.api.metadata.ModMetadata");
    Class<?> ver = Class.forName("net.fabricmc.loader.api.Version");
    Object versionObject = Proxy.newProxyInstance(ver.getClassLoader(), new Class<?>[]{ver}, (p, m, a) -> {
      if (m.getName().equals("getFriendlyString") || m.getName().equals("toString")) return version;
      if (m.getName().equals("compareTo")) return 0;
      if (m.getReturnType() == boolean.class) return false;
      if (m.getReturnType().isPrimitive()) return 0;
      return null;
    });
    Object metadataObject = Proxy.newProxyInstance(metadata.getClassLoader(), new Class<?>[]{metadata}, (p, m, a) -> {
      switch (m.getName()) {
        case "getId": case "getName": return id;
        case "getVersion": return versionObject;
        case "getType": return "normal";
        case "getDescription": return "";
        case "getEnvironment":
          return Enum.valueOf((Class) Class.forName("net.fabricmc.loader.api.metadata.ModEnvironment"), "UNIVERSAL");
        case "getProvides": case "getLicense": case "getAuthors": case "getContributors":
        case "getDependencies": case "getDepends": case "getRecommends": case "getSuggests":
        case "getConflicts": case "getBreaks": return Collections.emptyList();
        case "getCustomValues": return Collections.emptyMap();
        case "containsCustomValue": case "containsCustomElement": return false;
        case "getIconPath": return Optional.empty();
        case "getCustomValue": case "getContact": return null;
        default:
          if (m.getReturnType() == boolean.class) return false;
          if (m.getReturnType().isPrimitive()) return 0;
          return null;
      }
    });
    Object container = Proxy.newProxyInstance(modContainer.getClassLoader(), new Class<?>[]{modContainer}, (p, m, a) -> {
      switch (m.getName()) {
        case "getMetadata": return metadataObject;
        case "getRootPaths": case "getContainedMods": return Collections.emptyList();
        case "getContainingMod": return Optional.empty();
        case "getOrigin": case "getRootPath": case "getPath": return null;
        default:
          if (m.getReturnType() == boolean.class) return false;
          if (m.getReturnType().isPrimitive()) return 0;
          return null;
      }
    });
    Field mapField = impl.getDeclaredField("modMap");
    mapField.setAccessible(true);
    Object previous = ((Map) mapField.get(loader)).putIfAbsent(id, container);
    if (previous != null) return;
    Field modsField = impl.getDeclaredField("mods");
    modsField.setAccessible(true);
    ((List) modsField.get(loader)).add(container);
  }

  /** Drive the real Fabric loader with the bounded test provider. */
  public static int bootstrap() throws Exception {
    installLauncher(makeLauncher(ClassLoader.getSystemClassLoader(), false, new String[0], "26.3", true, false));
    return finishBootstrap(testProvider());
  }

  /**
   * Enter Fabric's real Minecraft game provider against user-supplied game
   * jars. Returns "minecraft<TAB><mods>" on success and
   * "test<TAB><mods><TAB><reason>" after falling back to the test provider, so
   * the caller always reports a bounded outcome instead of a stack trace.
   */
  public static String bootstrapProduction(String[] gameJars, String gameVersion, String side) throws Exception {
    return bootstrapProduction(gameJars, gameVersion, side, false, false, false, false);
  }

  public static String bootstrapProduction(String[] gameJars, String gameVersion, String side,
      boolean development, boolean realLaunch, boolean discovery) throws Exception {
    return bootstrapProduction(gameJars, gameVersion, side, development, realLaunch, discovery, false, false);
  }

  public static String bootstrapProduction(String[] gameJars, String gameVersion, String side,
      boolean development, boolean realLaunch, boolean discovery, boolean classpathUnlock) throws Exception {
    return bootstrapProduction(gameJars, gameVersion, side, development, realLaunch, discovery,
        classpathUnlock, false);
  }

  public static String bootstrapProduction(String[] gameJars, String gameVersion, String side,
      boolean development, boolean realLaunch, boolean discovery, boolean classpathUnlock,
      boolean knotLaunchFlag) throws Exception {
    return bootstrapProduction(gameJars, gameVersion, side, development, realLaunch, discovery,
        classpathUnlock, knotLaunchFlag, false);
  }

  public static String bootstrapProduction(String[] gameJars, String gameVersion, String side,
      boolean development, boolean realLaunch, boolean discovery, boolean classpathUnlock,
      boolean knotLaunchFlag, boolean launchGame) throws Exception {
    resetClassPathState(classpathUnlock, knotLaunchFlag);
    if (gameJars == null || gameJars.length == 0) return "test\t0\tno game jar supplied";
    boolean client = "client".equals(side);
    try {
      System.setProperty("fabric.gameVersion", gameVersion);
      System.setProperty("fabric.gameJarPath", gameJars[0]);
      System.setProperty(client ? "fabric.gameJarPath.client" : "fabric.gameJarPath.server", gameJars[0]);
      Class<?> launcherIface = Class.forName("net.fabricmc.loader.impl.launch.FabricLauncher");
      // The game jars are already on the JVM classpath (see `run`), so the
      // system loader sees both the loader and the game; a child URL loader
      // would only hide loader classes from the provider.
      Object launcher = makeLauncher(ClassLoader.getSystemClassLoader(), client, gameJars, gameVersion, development, realLaunch);
      installLauncher(launcher);
      Class<?> providerClass = Class.forName("net.fabricmc.loader.impl.game.minecraft.MinecraftGameProvider");
      Object provider = providerClass.getConstructor().newInstance();
      if (!(Boolean) providerClass.getMethod("isEnabled").invoke(provider)) {
        throw new IllegalStateException("fabric.skipMcProvider disabled the Minecraft game provider");
      }
      Object located = providerClass.getMethod("locateGame", launcherIface, String[].class)
          .invoke(provider, launcher, new String[0]);
      if (!(Boolean) located) {
        throw new IllegalStateException("MinecraftGameProvider.locateGame returned false");
      }
      // Knot's order: create the class loader (and make it the context
      // loader), then set the provider, initialize it, load, freeze, tweak
      // classes, bootstrap Mixin and initialize transformers, and only then
      // unlock the classpath.
      if (classpathUnlock) initClassPath(provider, providerClass, client, development);
      Class<?> providerIface = Class.forName("net.fabricmc.loader.impl.game.GameProvider");
      Class<?> impl = Class.forName("net.fabricmc.loader.impl.FabricLoaderImpl");
      Object loader = impl.getField("INSTANCE").get(null);
      impl.getMethod("setGameProvider", providerIface).invoke(loader, provider);
      if (launchGame) installPlainLogHandler();
      providerClass.getMethod("initialize", launcherIface).invoke(provider, launcher);
      if (knotLoader != null) Thread.currentThread().setContextClassLoader(knotLoader);
      impl.getMethod("load").invoke(loader);
      String freezeReason = "";
      try {
        impl.getMethod("freeze").invoke(loader);
      } catch (Throwable failure) {
        freezeReason = summarize(failure);
      }
      String unlock = "";
      if (classpathUnlock) {
        // `Knot.init`: freeze -> loadClassTweakers -> FabricMixinBootstrap.init
        // -> finishMixinBootstrapping -> initializeTransformers ->
        // unlockClassPath.
        String mixinFailure = initializeMixinBootstrap(loader, impl, client);
        if (mixinFailure != null) {
          knotInitOutcome = bound("failed mixin bootstrap: " + mixinFailure);
        } else {
          knotInitOutcome = initializeKnotTransformers();
        }
        try {
          providerIface.getMethod("unlockClassPath", launcherIface).invoke(provider, launcher);
        } catch (Throwable failure) {
          if (classPathFailure == null) classPathFailure = "unlockClassPath: " + summarize(failure);
        }
        unlock = classPathOutcome();
        if (knotLaunch) knotLaunchOutcome = probeTransformChain();
        knotMixinOutcome = probeMixinApplication(System.getProperty("horizon.mixin.probe"));
      }
      Collection<?> allMods = (Collection<?>) impl.getMethod("getAllMods").invoke(loader);
      List<String> ids = new ArrayList<>();
      if (discovery) {
        // Reflect through the API interfaces: some containers are package
        // private, so `mod.getClass().getMethod(...)` is not accessible.
        Method getMetadata = Class.forName("net.fabricmc.loader.api.ModContainer")
            .getMethod("getMetadata");
        Method getId = Class.forName("net.fabricmc.loader.api.metadata.ModMetadata")
            .getMethod("getId");
        for (Object mod : allMods) {
          try {
            ids.add(String.valueOf(getId.invoke(getMetadata.invoke(mod))));
          } catch (Throwable ignored) { }
        }
        Collections.sort(ids);
        if (ids.size() > 64) ids = new ArrayList<>(ids.subList(0, 64));
      }
      if (launchGame) {
        List<String> listing = new ArrayList<>();
        Method getMetadata = Class.forName("net.fabricmc.loader.api.ModContainer")
            .getMethod("getMetadata");
        Method getId = Class.forName("net.fabricmc.loader.api.metadata.ModMetadata")
            .getMethod("getId");
        for (Object mod : allMods) {
          try { listing.add(String.valueOf(getId.invoke(getMetadata.invoke(mod)))); }
          catch (Throwable ignored) { }
        }
        Collections.sort(listing);
        System.out.println("fabric-loader: Loading " + allMods.size() + " mods (" + String.join(",", listing) + ")");
        System.out.flush();
      }
      if (realLaunch) {
        // The launcher below names StubEntrypoint as the entrypoint, which is
        // the hand-off a real Knot launch would take. This probe never runs the
        // game's own entrypoint — a requested classpath unlock only extends the
        // loader's registry — so invoke the stub directly: the real game never
        // starts.
        String[] launchArgs = new String[0];
        try {
          Object args = providerClass.getMethod("getLaunchArguments", boolean.class).invoke(provider, false);
          if (args instanceof String[]) launchArgs = (String[]) args;
        } catch (Throwable ignored) { }
        StubEntrypoint.main(launchArgs);
      }
      if (launchGame) {
        // Knot's last step before `launch`: `preLaunch` entrypoints run once
        // the classpath is unlocked. Then `Knot.launch` hands the same loader
        // to `provider.launch`, which is the real game's entrypoint.
        String preLaunchFailure = invokePreLaunch(loader, impl);
        launchGameOutcome = preLaunchFailure != null
            ? bound("failed preLaunch: " + preLaunchFailure)
            : launchTheGame(provider, providerIface);
        System.out.println("launch-game: " + launchGameOutcome);
        System.out.flush();
      }
      return "minecraft\t" + allMods.size() + "\t" + freezeReason + "\t" + development + "\t"
          + String.join(",", ids) + "\t" + unlock + "\t" + (knotInitOutcome == null ? "" : knotInitOutcome)
          + "\t" + (knotLaunchOutcome == null ? "" : knotLaunchOutcome)
          + "\t" + (launchGameOutcome == null ? "" : launchGameOutcome)
          + "\t" + (knotMixinOutcome == null ? "" : knotMixinOutcome);
    } catch (Throwable failure) {
      String reason = summarize(failure);
      try {
        resetLauncher();
        return "test\t" + bootstrap() + "\t" + reason;
      } catch (Throwable fallbackFailure) {
        throw new RuntimeException("production provider failed: " + reason
            + "; test provider failed: " + summarize(fallbackFailure));
      }
    }
  }

  /** Clear the launcher Fabric's `setLauncher` refuses to replace. */
  private static void resetLauncher() throws Exception {
    Class<?> base = Class.forName("net.fabricmc.loader.impl.launch.FabricLauncherBase");
    Field field = base.getDeclaredField("launcher");
    field.setAccessible(true);
    field.set(null, null);
  }

  /** The launcher Fabric's provider sees: the supplied classpath plus game jars. */
  private static Object makeLauncher(ClassLoader target, boolean client, String[] gameJars,
      String gameVersion, boolean development, boolean realLaunch) throws Exception {
    Class<?> launcherIface = Class.forName("net.fabricmc.loader.impl.launch.FabricLauncher");
    return Proxy.newProxyInstance(launcherIface.getClassLoader(), new Class<?>[]{launcherIface}, (p, m, a) -> {
      switch (m.getName()) {
        case "getClassPath": {
          List<Path> paths = Arrays.stream(System.getProperty("java.class.path").split(File.pathSeparator))
              .map(Paths::get).collect(Collectors.toList());
          for (String jar : gameJars) paths.add(Paths.get(jar));
          if (classPathUnlock) {
            for (String jar : classPathJars) {
              Path path = Paths.get(jar);
              if (!paths.contains(path)) paths.add(path);
            }
          }
          return paths;
        }
        case "addToClassPath": {
          String[] prefixes = a.length > 1 && a[1] instanceof String[] ? (String[]) a[1] : new String[0];
          addClassPathEntry(a[0], prefixes, true);
          return null;
        }
        case "setAllowedPrefixes": {
          String[] prefixes = a.length > 1 && a[1] instanceof String[] ? (String[]) a[1] : new String[0];
          addClassPathEntry(a[0], prefixes, false);
          return null;
        }
        case "setValidParentClassPath": {
          registerValidParentClassPath(a.length > 0 && a[0] instanceof Collection
              ? (Collection<?>) a[0] : null);
          return null;
        }
        case "getTargetClassLoader": return targetLoader(target);
        case "getResourceAsStream": return targetLoader(target).getResourceAsStream((String) a[0]);
        case "getClassByteArray": {
          String name = (String) a[0];
          boolean runTransformers = a.length > 1 && Boolean.TRUE.equals(a[1]);
          if (classPath != null) {
            byte[] bytes = classBytes(name, runTransformers);
            if (bytes == null) throw new IOException(name);
            return bytes;
          }
          try (InputStream in = targetLoader(target).getResourceAsStream(name.replace('.', '/') + ".class")) {
            if (in == null) throw new IOException(name);
            return in.readAllBytes();
          }
        }
        case "getEnvironmentType":
          return Enum.valueOf((Class) Class.forName("net.fabricmc.api.EnvType"), client ? "CLIENT" : "SERVER");
        case "isDevelopment": return development;
        case "getEntrypoint":
          return realLaunch ? "HorizonLoaderBridge$StubEntrypoint"
              : (client ? "net.fabricmc.loader.impl.launch.knot.KnotClient"
              : "net.fabricmc.loader.impl.launch.knot.KnotServer");
        case "getManifest": return null;
        case "getMappingConfiguration": return mappingConfiguration(gameVersion);
        case "isClassLoaded": return classLoaded((String) a[0]);
        case "loadIntoTarget": return Class.forName((String) a[0], false, targetLoader(target));
        default: return defaultValue(m.getReturnType());
      }
    });
  }

  /**
   * The loader the launcher hands to the game. Fabric's `FabricLauncher` API is
   * getter-only (`getTargetClassLoader`; there is no `setTargetClassLoader`),
   * and a real `Knot.init(String[])` returns
   * `KnotClassLoaderInterface.getClassLoader()` as the game's loader, so
   * `--knot-launch` stores that loader here and every launcher target read
   * answers with it. Without the flag this is the system loader, exactly as
   * before.
   */
  private static ClassLoader targetLoader(ClassLoader fallback) {
    return knotLoader != null ? knotLoader : fallback;
  }

  public static final class StubEntrypoint {
    private static boolean launched;

    public static void main(String[] args) {
      // Provider launch and the direct fallback may both reach the stub.
      if (launched) return;
      launched = true;
      System.out.println("real-launch: stub-entrypoint-ok " + (args == null ? 0 : args.length));
    }
  }

  /** The bounded reflection provider this probe has always used. */
  private static Object testProvider() throws Exception {
    Class<?> providerIface = Class.forName("net.fabricmc.loader.impl.game.GameProvider");
    return Proxy.newProxyInstance(providerIface.getClassLoader(), new Class<?>[]{providerIface}, (p, m, a) -> {
      switch (m.getName()) {
        case "getGameId": return "minecraft";
        case "getGameName": return "Horizon";
        case "getRawGameVersion": case "getNormalizedGameVersion": return "26.3";
        case "getBuiltinMods": return Collections.emptyList();
        case "getEntrypoint": return "net.fabricmc.loader.impl.launch.knot.KnotClient";
        case "getLaunchDirectory": return Paths.get(".");
        case "requiresUrlClassLoader": case "isEnabled": case "locateGame":
        case "hasAwtSupport": case "canOpenErrorGui": return true;
        case "getBuiltinTransforms": return Collections.emptySet();
        case "initialize": case "unlockClassPath": return null;
        case "launch": testLaunchCalled = true; return null;
        case "getEntrypointTransformer": return null;
        case "getArguments":
          return Class.forName("net.fabricmc.loader.impl.util.Arguments").getConstructor().newInstance();
        case "getLaunchArguments": return new String[0];
        default: return defaultValue(m.getReturnType());
      }
    });
  }

  private static void installLauncher(Object launcher) throws Exception {
    Class<?> base = Class.forName("net.fabricmc.loader.impl.launch.FabricLauncherBase");
    Class<?> launcherIface = Class.forName("net.fabricmc.loader.impl.launch.FabricLauncher");
    base.getMethod("setLauncher", launcherIface).invoke(null, launcher);
    Field properties = base.getDeclaredField("properties");
    properties.setAccessible(true);
    properties.set(null, new HashMap<String, Object>());
  }

  private static int finishBootstrap(Object provider) throws Exception {
    Class<?> providerIface = Class.forName("net.fabricmc.loader.impl.game.GameProvider");
    Class<?> impl = Class.forName("net.fabricmc.loader.impl.FabricLoaderImpl");
    Object loader = impl.getField("INSTANCE").get(null);
    impl.getMethod("setGameProvider", providerIface).invoke(loader, provider);
    impl.getMethod("load").invoke(loader);
    try {
      impl.getMethod("freeze").invoke(loader);
    } catch (Throwable ignored) {
      // A loader without freeze still exposes the containers.
    }
    return ((Collection<?>) impl.getMethod("getAllMods").invoke(loader)).size();
  }

  /** One bounded line naming the failure chain, without a stack trace. */
  private static String summarize(Throwable failure) {
    StringBuilder out = new StringBuilder();
    Throwable current = failure;
    for (int depth = 0; current != null && depth < 4; depth++) {
      if (out.length() > 0) out.append(" <- ");
      out.append(current.getClass().getName());
      String message = current.getMessage();
      if (message != null && !message.isEmpty()) {
        message = message.replaceAll("\\s+", " ");
        if (message.length() > 200) message = message.substring(0, 200);
        out.append(": ").append(message);
      }
      current = current.getCause();
    }
    String text = out.length() == 0 ? failure.getClass().getName() : out.toString();
    return text.length() > 300 ? text.substring(0, 300) : text;
  }

  /** Invoke the loader's entrypoint containers for one lifecycle kind. */
  public static int run(String kind) throws Exception {
    Class<?> impl = Class.forName("net.fabricmc.loader.impl.FabricLoaderImpl");
    Object loader = impl.getField("INSTANCE").get(null);
    String iface = switch (kind) {
      case "client" -> "net.fabricmc.api.ClientModInitializer";
      case "server" -> "net.fabricmc.api.DedicatedServerModInitializer";
      default -> "net.fabricmc.api.ModInitializer";
    };
    String method = switch (kind) {
      case "client" -> "onInitializeClient";
      case "server" -> "onInitializeServer";
      default -> "onInitialize";
    };
    Class<?> type = Class.forName(iface);
    List<?> containers = (List<?>) impl
        .getMethod("getEntrypointContainers", String.class, Class.class)
        .invoke(loader, kind, type);
    for (Object container : containers) {
      Object entrypoint = container.getClass().getMethod("getEntrypoint").invoke(container);
      entrypoint.getClass().getMethod(method).invoke(entrypoint);
    }
    return containers.size();
  }

  private static Object mappingConfiguration(String gameVersion) throws Exception {
    Class<?> type = Class.forName("net.fabricmc.loader.impl.launch.MappingConfiguration");
    Object config = type.getConstructor().newInstance();
    setField(type, config, "namespace", "named");
    setField(type, config, "gameId", "minecraft");
    setField(type, config, "gameVersion", gameVersion);
    String mappingPath = System.getProperty("horizon.mapping.path");
    setField(type, config, "mappingName", mappingPath == null ? "none" : "horizon");
    setField(type, config, "namespaces", Arrays.asList("official", "intermediary", "named"));
    setField(type, config, "initializedMetadata", true);
    setField(type, config, "initializedMappings", true);
    Class<?> tree = Class.forName("net.fabricmc.loader.impl.lib.mappingio.tree.MemoryMappingTree");
    Object mappings = tree.getConstructor().newInstance();
    if (mappingPath != null && !mappingPath.isBlank()) {
      Class<?> reader = Class.forName("net.fabricmc.loader.impl.lib.mappingio.MappingReader");
      Class<?> visitor = Class.forName("net.fabricmc.loader.impl.lib.mappingio.MappingVisitor");
      reader.getMethod("read", Path.class, visitor).invoke(null, Paths.get(mappingPath), mappings);
    } else {
      // The provider dereferences the mapping tree unconditionally when no
      // installation supplied a real tree, so retain the historical empty tree.
      tree.getMethod("visitNamespaces", String.class, java.util.List.class)
          .invoke(mappings, "named", Arrays.asList("official"));
    }
    setField(type, config, "mappings", mappings);
    return config;
  }

  private static void setField(Class<?> type, Object target, String name, Object value) throws Exception {
    Field field = type.getDeclaredField(name);
    field.setAccessible(true);
    field.set(target, value);
  }

  private static Object defaultValue(Class<?> type) {
    if (!type.isPrimitive()) return null;
    if (type == boolean.class) return false;
    if (type == char.class) return (char) 0;
    if (type == byte.class) return (byte) 0;
    if (type == short.class) return (short) 0;
    if (type == int.class) return 0;
    if (type == long.class) return 0L;
    if (type == float.class) return 0f;
    return 0d;
  }
}
"#;

impl NestedJars {
    /// Compile the reflection-only Fabric metadata bridge without requiring
    /// loader classes on javac's classpath. The probe already requires a JDK
    /// for façade generation; if javac is unavailable, the rest of the probe
    /// still works and simply skips metadata seeding.
    fn compile_loader_bridge(&self) -> Option<PathBuf> {
        let source = self.root.join("HorizonLoaderBridge.java");
        let classes = self.root.join("loader-bridge");
        if fs::create_dir_all(&classes).is_err()
            || fs::write(&source, LOADER_BRIDGE_SOURCE).is_err()
        {
            return None;
        }
        let javac = std::env::var_os("JAVA_HOME")
            .map(PathBuf::from)
            .map(|home| home.join("bin").join("javac"))
            .unwrap_or_else(|| PathBuf::from("javac"));
        let Ok(status) = Command::new(javac)
            .arg("-Xlint:none")
            .arg("-nowarn")
            .arg("-d")
            .arg(&classes)
            .arg(&source)
            .status()
        else {
            return None;
        };
        status.success().then_some(classes)
    }
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

/// The usage line, kept as data so a test can check the kinds it names.
const USAGE: &str = "usage: horizon-jvm [--entry <class>] [--entry-kind <main|client|server|preLaunch|neoforge|datagen>] [--real-loader] [--real-launch] [--fabric-discovery] [--classpath-unlock] [--knot-launch] [--launch-game] [--accept-eula] [--mixin-apply-probe <class#method=value>] [--game-jar <jar>]... [--game-version <v>] [--provider-report] [--datagen-output <dir>] [--list-entrypoints] [--list-mixin-configs] [--list-fml-mods] [--fml-report] [--json] [--mixin-config <path>]... [--fabric-development] [--stubs <jar>] [--loader <jar>] [--libs <dir>] [--measure [--measure-timeout <secs>] [--measure-sample-ms <ms>] [--measure-repeat <n>]] <jar>...";

/// The FML listing/report flags, removed from the jar list before anything is
/// resolved. `--fml-list` is the short spelling of `--list-fml-mods`.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct FmlFlags {
    list: bool,
    report: bool,
    json: bool,
}

fn take_fml_flags(args: &mut Vec<String>) -> FmlFlags {
    let list = take_flag(args, &["--list-fml-mods", "--fml-list"]);
    let report = take_flag(args, &["--fml-report"]);
    let json = take_flag(args, &["--json"]);
    FmlFlags { list, report, json }
}

fn take_flag(args: &mut Vec<String>, names: &[&str]) -> bool {
    let before = args.len();
    args.retain(|arg| !names.contains(&arg.as_str()));
    args.len() != before
}

fn run() -> Result<(), String> {
    let mut args: Vec<String> = std::env::args().skip(1).collect();
    // A measured child is sent the recursive spelling instead of `--measure`.
    // Stripping it here makes the child take the normal path, exactly as the
    // measuring process would have.
    take_recursive_flag(&mut args);
    let list_entrypoints_only = args.iter().any(|arg| arg == "--list-entrypoints");
    args.retain(|arg| arg != "--list-entrypoints");
    let list_mixin_configs_only = args.iter().any(|arg| arg == "--list-mixin-configs");
    args.retain(|arg| arg != "--list-mixin-configs");
    // Fabric's loader-development mode is opt-in: a plain probe keeps the
    // production default, and the flag never reaches the jar list.
    let fabric_development = args.iter().any(|arg| arg == "--fabric-development");
    args.retain(|arg| arg != "--fabric-development");
    let real_launch = args.iter().any(|arg| arg == "--real-launch");
    args.retain(|arg| arg != "--real-launch");
    let fabric_discovery = args.iter().any(|arg| arg == "--fabric-discovery");
    args.retain(|arg| arg != "--fabric-discovery");
    // `--launch-game` is the real game launch. It is a two-part gate: the flag
    // and `HORIZON_REAL_LAUNCH=1`. `--launch-game-child` is the internal marker
    // the parent adds when it re-runs this binary in a bounded child process.
    let launch_game_child = args.iter().any(|arg| arg == "--launch-game-child");
    let launch_game_flag = launch_game_child || args.iter().any(|arg| arg == "--launch-game");
    args.retain(|arg| arg != "--launch-game" && arg != "--launch-game-child");
    // This opt-in is deliberately meaningful only for the bounded child. The
    // child changes into `LaunchHomes::game`, so writing here cannot touch a
    // user's real game directory or EULA file.
    let accept_eula = take_flag(&mut args, &["--accept-eula"]);
    if accept_eula && !launch_game_flag {
        return Err("--accept-eula requires --launch-game".to_owned());
    }
    let launch_this_process = launch_game_flag && real_launch_enabled();
    // A mixin-application probe loads a class through Knot after the loader is
    // initialized, so it needs the same unlocked classpath `--knot-launch`
    // proves.
    let mixin_apply_probe = take(&mut args, "--mixin-apply-probe");
    // Opt-in: extend the Knot classpath with the resolved game jars and the
    // loader's mod code sources. Without it the run is byte-identical.
    // `--knot-launch` builds on it: it hands that loader to the launcher and
    // proves the transformer chain, which needs an unlocked classpath, so it
    // implies the unlock.
    let knot_launch = args.iter().any(|arg| arg == "--knot-launch")
        || launch_game_flag
        || mixin_apply_probe.is_some();
    args.retain(|arg| arg != "--knot-launch");
    let classpath_unlock = args.iter().any(|arg| arg == "--classpath-unlock") || knot_launch;
    args.retain(|arg| arg != "--classpath-unlock");
    // Run the real Fabric or NeoForge loader instead of this probe's own scan.
    // A supplied Minecraft jar opts into the production provider, which only
    // the real-loader path can run; a report-only invocation still only reports
    // the selection, so it does not start a JVM for it.
    let real_loader_flag = args.iter().any(|arg| arg == "--real-loader");
    args.retain(|arg| arg != "--real-loader");
    let game_provider = take_game_provider_args(&mut args)?;
    let provider_report = take_flag(&mut args, &["--provider-report"]);
    // A measurement runs the probe's own discovery first (so the fixture must
    // be discoverable here too) and then times that same argv in a child.
    let measure = take_measure_args(&mut args)?;
    let fml_flags = take_fml_flags(&mut args);
    let mixin_config_args = take_all(&mut args, "--mixin-config");
    let entry = take(&mut args, "--entry");
    let entry_kind = take(&mut args, "--entry-kind").unwrap_or_else(|| "main".to_owned());
    let datagen_output = take(&mut args, "--datagen-output").map(PathBuf::from);
    let stubs = take(&mut args, "--stubs").map(PathBuf::from);
    let loader = take(&mut args, "--loader").map(PathBuf::from);
    let libs = take(&mut args, "--libs").map(PathBuf::from);
    let loader_libs = libs.as_deref().and_then(asm_readiness);
    if let Some(line) = &loader_libs {
        println!("{line}");
    }
    // Read-only probes: a client home and mapping files are inspected, never
    // started, and neither moves the launch gate.
    let client_home = take(&mut args, "--client-home").map(PathBuf::from);
    let mappings = take_all(&mut args, "--mappings")
        .into_iter()
        .map(PathBuf::from)
        .collect::<Vec<_>>();
    let remap_report = args.iter().any(|arg| arg == "--remap-report");
    args.retain(|arg| arg != "--remap-report");
    let remap_line = remap_report.then(|| remap_report_line(&resolve_remap_tree(&mappings)));
    // A client run reports what its install still lacks before anything else:
    // the assets, client jar and natives live outside the classpath, so a
    // missing one is a readiness fact, not a load failure.
    let client_launch_line = if client_side(&entry_kind) {
        let home = client_home
            .clone()
            .or_else(|| std::env::var_os(CLIENT_HOME_ENV).map(PathBuf::from));
        let line =
            ClientReadiness::detect(home.as_deref(), &game_provider.version, &game_provider.jars)
                .line();
        println!("{line}");
        Some(line)
    } else {
        None
    };
    // `--remap-report` builds the tree the loader's mapping configuration needs
    // and says whether it is real; a run without the flag prints nothing here.
    if remap_report {
        println!(
            "{}",
            remap_line.as_deref().unwrap_or("remap: failed unknown")
        );
    }
    let heap = take(&mut args, "--heap").unwrap_or_else(|| "-Xmx1g".to_owned());
    let real_loader = real_loader_flag || (!game_provider.jars.is_empty() && !args.is_empty());
    // A report with no run behind it is still useful: it names the provider
    // the flags select and says that nothing was attempted.
    if provider_report && args.is_empty() && !real_loader && !fml_flags.list && !fml_flags.report {
        print_provider_report(
            &ProviderReport::not_run(
                &game_provider.jars,
                &game_provider.version,
                ProviderSide::for_entry_kind(&entry_kind),
            )
            .with_remap(remap_line.clone())
            .with_client_launch(client_launch_line.clone())
            .with_loader_libs(loader_libs.clone()),
            fml_flags.json,
        );
        return Ok(());
    }
    // Listing mixin configs is meaningful with only `--mixin-config` values,
    // so it runs before the classpath requirement.
    if list_mixin_configs_only {
        list_mixin_configs(&args, &mixin_config_args)?;
        if provider_report {
            print_provider_report(
                &ProviderReport::not_run(
                    &game_provider.jars,
                    &game_provider.version,
                    ProviderSide::for_entry_kind(&entry_kind),
                )
                .with_remap(remap_line.clone())
                .with_client_launch(client_launch_line.clone())
                .with_loader_libs(loader_libs.clone()),
                fml_flags.json,
            );
        }
        return Ok(());
    }
    if args.is_empty() && !fml_flags.list && !fml_flags.report {
        // `--remap-report` alone is a complete request: the line above is the
        // whole answer, and an empty jar list is not an error for it.
        if remap_report {
            return Ok(());
        }
        return Err(USAGE.to_owned());
    }
    if list_entrypoints_only {
        list_entrypoints(&args)?;
        if provider_report {
            print_provider_report(
                &ProviderReport::not_run(
                    &game_provider.jars,
                    &game_provider.version,
                    ProviderSide::for_entry_kind(&entry_kind),
                )
                .with_remap(remap_line.clone())
                .with_client_launch(client_launch_line.clone())
                .with_loader_libs(loader_libs.clone()),
                fml_flags.json,
            );
        }
        return Ok(());
    }
    // A gated real launch runs in a child process of this binary: the wall
    // clock, the process group and the captured output are bounded here, so an
    // embedded JVM that starts the game cannot outlive them. Both the flag and
    // `HORIZON_REAL_LAUNCH=1` are required; without them the run is exactly
    // what it was before the flag existed, and the game never starts.
    if launch_game_flag && !launch_game_child {
        let status = if launch_this_process {
            run_launch_game_child(accept_eula)?
        } else {
            LAUNCH_GAME_GATE_SKIPPED.to_owned()
        };
        println!("{}", launch_game_line(&status));
        if provider_report {
            print_provider_report(
                &ProviderReport::not_run(
                    &game_provider.jars,
                    &game_provider.version,
                    ProviderSide::for_entry_kind(&entry_kind),
                )
                .with_remap(remap_line.clone())
                .with_client_launch(client_launch_line.clone())
                .with_loader_libs(loader_libs.clone())
                .with_launch_game(Some(status)),
                fml_flags.json,
            );
        }
        return Ok(());
    }
    // The FML path starts its own Java process with the loader's exact
    // classpath; an embedded JVM changes how FML's in-dev locator sees it.
    // `--list-fml-mods`/`--fml-report` use that same child probe without an
    // entrypoint, so they select this path even without `--real-loader`.
    if fml_flags.list || fml_flags.report || (real_loader && entry_kind == "neoforge") {
        let Some(libs) = libs.as_ref() else {
            return Err("the FML probe needs --libs <installed server>/libraries".to_owned());
        };
        let mods: Vec<PathBuf> = args.iter().map(PathBuf::from).collect();
        let mode = if fml_flags.list {
            FmlMode::List
        } else if fml_flags.report {
            FmlMode::Report
        } else {
            FmlMode::Run
        };
        return run_real_neoforge(libs, &mods, mode, fml_flags.json);
    }
    let (entry_specs, pre_launch) = if real_loader {
        (Vec::new(), Vec::new())
    } else {
        match entry {
            Some(entry) => (vec![entry], Vec::new()),
            None => {
                let jar = Path::new(&args[0]);
                let metadata = metadata_path(jar)?;
                let entries = discover_entries(jar, &entry_kind)?;
                if entries.is_empty() {
                    let declared = declared_entrypoint_kinds(jar)?;
                    return Err(missing_entry_message(
                        &args[0],
                        &entry_kind,
                        metadata,
                        &declared,
                    ));
                }
                if metadata.is_none() {
                    report_neoforge_metadata(jar);
                }
                // Datagen is a build step of its own: loader-level `preLaunch`
                // callbacks do not run, so neither does any other lifecycle group.
                let pre_launch = if is_datagen_kind(&entry_kind) {
                    Vec::new()
                } else {
                    pre_launch_entries(jar, &entry_kind, metadata)?
                };
                (entries, pre_launch)
            }
        }
    };
    let datagen_mod = is_datagen_kind(&entry_kind)
        .then(|| fabric_metadata(Path::new(&args[0])))
        .flatten();

    let mut classpath: Vec<PathBuf> = Vec::new();
    if let Some(stubs) = stubs {
        classpath.push(stubs);
    }
    if let Some(loader) = loader {
        classpath.push(loader);
    }
    if let Some(libs) = libs {
        let (dependencies, skipped_game_jars) = jars(&libs)?;
        classpath.extend(dependencies);
        if skipped_game_jars != 0 {
            eprintln!(
                "horizon-jvm: skipped {skipped_game_jars} Minecraft runtime jar(s); the generated façade owns net.minecraft classes"
            );
        }
    }
    // User-supplied game jars are the production provider's input, never
    // copied or discovered from the machine. They join the classpath so the
    // mods the loader instantiates can resolve the game they were built for.
    for jar in &game_provider.jars {
        classpath.push(jar.clone());
    }
    for arg in &args {
        classpath.push(PathBuf::from(arg));
    }
    if classpath.is_empty() {
        return Err("no classpath".to_owned());
    }
    // A measurement is a report about a child process, so it cannot run after
    // this process owns an embedded JVM. The probe's own discovery above has
    // already run (a jar it cannot discover is not measured either); the child
    // times this same argv with only the measurement flag removed, and takes
    // the normal path because this branch then sees no flag.
    if let Some(measure) = measure {
        let plan = measure_plan(
            measure,
            std::env::args_os().skip(1).collect(),
            &entry_label(&entry_specs, &entry_kind),
        );
        return report_measure(&plan);
    }
    let nested = expand_nested_jars(&mut classpath, launch_game_flag)?;
    if let Some(bridge) = nested.compile_loader_bridge() {
        classpath.insert(0, bridge);
    }
    // Datagen runs only the `fabric-datagen` callback: no client/server/main
    // initializer and no Mixin phase, so it branches before both are planned.
    if is_datagen_kind(&entry_kind) {
        return run_datagen(
            &classpath,
            &entry_specs,
            datagen_output.as_deref(),
            &heap,
            &nested,
            datagen_mod.as_ref(),
        );
    }
    // The selected environment filters the hand-off: a `client` config never
    // reaches a server run, and `main`/`preLaunch`/`neoforge` keep both sides.
    let mixin_environment = MixinEnvironment::selected(&entry_kind);
    let discovered = discover_mixin_configs(&classpath, &mixin_config_args);
    let mixin_skipped = skipped_mixin_configs(&discovered, mixin_environment);
    let mixin_configs = select_mixin_configs(discovered, mixin_environment);
    let mixin_report = report_mixin_configs(&mixin_configs);
    // Only configs a supplied jar (or an explicit `--mixin-config`) actually
    // carries reach the property; a path a jar declares but does not ship is
    // named in the report and left out so Mixin never chases it.
    let mixin_property = mixin_config_property(&mixin_configs);
    let mixin_registered = mixin_registered_count(mixin_property.as_deref());
    // Registration walks the same list the property carries, so the two
    // hand-offs can never name different configs or a different order.
    let mixin_names = mixin_config_names(mixin_property.as_deref());
    // Fabric's own mod discovery only sees jars the loader is told about. The
    // classpath above stays as it is; this property names the supplied jars as
    // mods, the documented developer hand-off for classpath mods.
    let supplied_jars: Vec<PathBuf> = args.iter().map(PathBuf::from).collect();
    let fabric_mods = fabric_add_mods(&supplied_jars);
    let skip_mc_provider = skip_mc_provider_requested(&fabric_environment_options());
    let paths = std::env::join_paths(&classpath).map_err(|e| e.to_string())?;
    let paths = paths.to_string_lossy().into_owned();

    let mut init = InitArgsBuilder::new()
        .version(JNIVersion::V8)
        .option(format!("-Djava.class.path={paths}"))
        .option(&heap)
        .option("-Djava.awt.headless=true")
        .option("-XX:+StartAttachListener");
    // Mixin reads its config list at launch time, so the property has to be in
    // the JVM options rather than set after `JavaVM::new`.
    for option in mixin_jvm_options(mixin_property.as_deref()) {
        init = init.option(option);
    }
    // Same for Fabric's developer properties: the loader reads them while it
    // discovers mods, which happens on the first loader class that loads.
    for option in fabric_jvm_options(fabric_mods.as_deref(), fabric_development, skip_mc_provider) {
        init = init.option(option);
    }
    // The real game provider reads these before `locateGame`, so they belong in
    // the JVM options rather than being set after `JavaVM::new`.
    for option in game_provider_jvm_options(
        &game_provider.jars,
        &game_provider.version,
        client_side(&entry_kind),
    ) {
        init = init.option(option);
    }
    if let Some(path) = mapping_loader_path(&mappings) {
        init = init.option(format!("-D{MAPPING_PATH_PROPERTY}={}", path.display()));
    }
    // A mixin-application probe is read by the bridge after the loader has
    // registered its configs, so the spec travels as a system property.
    if let Some(spec) = &mixin_apply_probe {
        init = init.option(format!("-Dhorizon.mixin.probe={spec}"));
    }
    let init = init.build().map_err(|e| format!("JVM options: {e}"))?;
    let jvm = JavaVM::new(init)
        .map_err(|e| format!("could not start a JVM ({e}); set JAVA_HOME to a JDK with libjvm"))?;
    let mut guard = jvm
        .attach_current_thread()
        .map_err(|e| format!("attach: {e}"))?;
    let env = &mut *guard;

    if real_loader {
        let bridge = match env.find_class("HorizonLoaderBridge") {
            Ok(class) => class,
            Err(_) => {
                let _ = env.exception_clear();
                return Err(
                    "real Fabric loader requested but HorizonLoaderBridge did not compile".into(),
                );
            }
        };
        let outcome = if game_provider.jars.is_empty() {
            let mods = env
                .call_static_method(&bridge, "bootstrap", "()I", &[])
                .and_then(|value| value.i())
                .map_err(|error| format!("Fabric loader bootstrap: {error}"))?;
            let mods = usize::try_from(mods).unwrap_or(0);
            ProviderOutcome::Test { mods }
        } else {
            let jar_paths: Vec<String> = game_provider
                .jars
                .iter()
                .map(|jar| jar.to_string_lossy().into_owned())
                .collect();
            let jars = java_string_array(env, &jar_paths)?;
            let version = env
                .new_string(&game_provider.version)
                .map_err(|error| format!("game version: {error}"))?;
            let side = env
                .new_string(if client_side(&entry_kind) {
                    "client"
                } else {
                    "server"
                })
                .map_err(|error| format!("game side: {error}"))?;
            let result = env
                .call_static_method(
                    &bridge,
                    "bootstrapProduction",
                    "([Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;ZZZZZZ)Ljava/lang/String;",
                    &[
                        JValue::Object(&jars),
                        JValue::Object(&JObject::from(version)),
                        JValue::Object(&JObject::from(side)),
                        JValue::Bool(fabric_development as u8),
                        JValue::Bool(real_launch as u8),
                        JValue::Bool(fabric_discovery as u8),
                        JValue::Bool(classpath_unlock as u8),
                        JValue::Bool(knot_launch as u8),
                        JValue::Bool(launch_this_process as u8),
                    ],
                )
                .and_then(|value| value.l())
                .map_err(|error| format!("Fabric production provider: {error}"))?;
            let text = java_string_value(env, &result)?;
            parse_provider_outcome(&text)?
        };
        let mods = outcome.mods();
        // A launching child never invokes the loader's entrypoints itself: the
        // game's own entrypoint runs them through Fabric, exactly as a real
        // Knot launch does. Before the launch the bridge has already run
        // `preLaunch`.
        let entrypoints = if launch_this_process {
            0
        } else {
            let kind = entry_kind.clone();
            let kind = env
                .new_string(kind)
                .map_err(|error| format!("loader kind: {error}"))?;
            env.call_static_method(
                &bridge,
                "run",
                "(Ljava/lang/String;)I",
                &[JValue::Object(&JObject::from(kind))],
            )
            .and_then(|value| value.i())
            .map_err(|error| format!("Fabric loader entrypoints: {error}"))?
        };
        if launch_this_process {
            println!("real loader: {mods} mod(s), game launch requested");
        } else {
            println!("real loader: {mods} mod(s), {entrypoints} {entry_kind} entrypoint(s)");
        }
        match &outcome {
            ProviderOutcome::Production {
                freeze_reason,
                development,
                discovered_ids,
                ..
            } => {
                println!("real loader: entered production game provider");
                println!("real loader: isDevelopment={development}");
                if let Some(reason) = freeze_reason {
                    println!("real loader: freeze failed ({reason})");
                }
                if fabric_discovery {
                    let declared = declared_mod_ids(&supplied_jars);
                    println!("{}", discovery_line(&declared, discovered_ids));
                }
            }
            ProviderOutcome::Fallback { reason, .. } => {
                println!(
                    "real loader: production game provider unavailable ({reason}); using test provider"
                );
            }
            ProviderOutcome::Test { .. } => {}
        }
        // One bounded line when the flag was passed; nothing otherwise, so an
        // unflagged run's output is unchanged.
        let unlock = classpath_unlock_value(classpath_unlock, &outcome);
        if let Some(value) = &unlock {
            println!("{}", classpath_unlock_line(value));
        }
        let knot_init = knot_init_value(classpath_unlock, &outcome);
        if let Some(value) = &knot_init {
            println!("{}", knot_init_line(value));
        }
        let knot_launch = knot_launch_value(knot_launch, &outcome);
        if let Some(value) = &knot_launch {
            println!("{}", knot_launch_line(value));
        }
        let mixin_apply = mixin_apply_value(mixin_apply_probe.is_some(), &outcome);
        if let Some(value) = &mixin_apply {
            println!("{}", mixin_apply_line(value));
        }
        let launch = launch_game_value(launch_this_process, &outcome);
        if let Some(value) = &launch {
            println!("{}", launch_game_line(value));
        }
        if provider_report {
            let report = ProviderReport::from_outcome(
                &outcome,
                game_provider.jars.len(),
                &game_provider.version,
                ProviderSide::for_entry_kind(&entry_kind),
            )
            .with_remap(remap_line.clone())
            .with_client_launch(client_launch_line.clone())
            .with_classpath_unlock(unlock)
            .with_knot_init(knot_init)
            .with_knot_launch(knot_launch)
            .with_mixin_apply(mixin_apply)
            .with_launch_game(launch)
            .with_loader_libs(loader_libs.clone());
            print_provider_report(&report, fml_flags.json);
        }
        return Ok(());
    }

    prepare_fabric_loader(env, &nested.root)?;
    // The reflective seed registers each jar's metadata itself. Discovery mode
    // leaves that to the loader's own `-Dfabric.addMods` hand-off instead.
    if !fabric_discovery {
        seed_fabric_metadata(env, &classpath)?;
    }

    println!(
        "jvm up: {} jars on the classpath, {} {} entrypoint(s)",
        classpath.len(),
        entry_kind,
        entry_specs.len()
    );
    // Read the hand-off back: it proves the loader will see those jars as mods
    // (or that the run supplied none), without guessing from the option list.
    println!("{}", report_fabric_add_mods(env));
    if !pre_launch.is_empty() {
        println!("{} preLaunch entrypoint(s)", pre_launch.len());
    }
    for line in &mixin_report {
        println!("{line}");
    }
    // One line per config this side leaves out, so a client/server split is
    // visible instead of a config silently disappearing.
    for line in &mixin_skipped {
        println!("{line}");
    }
    println!("{}", mixin_configs_line(mixin_registered));
    // Mixin's hand-off follows the config report in Fabric's order: the static
    // bootstrap, then one `Mixins.addConfiguration` per config. A run with no
    // config has no stage, reports that, and loads no Mixin class at all.
    let stages = mixin_stages(mixin_registered);
    if stages.is_empty() {
        println!("mixin bootstrap: no configs");
    }
    let mut bootstrap = None;
    for stage in stages {
        match stage {
            MixinStage::Bootstrap => {
                let outcome = mixin_bootstrap_label(env);
                println!("mixin bootstrap: {}", mixin_bootstrap_line(&outcome));
                bootstrap = Some(outcome);
            }
            MixinStage::Registration => {
                let mut registrar = JniMixinRegistrar::new(&mut *env);
                for line in register_mixin_configs(bootstrap.as_ref(), &mixin_names, &mut registrar)
                {
                    println!("{line}");
                }
            }
        }
    }
    // The loading phase ends here, before the first entrypoint: real launches
    // finish loading and select the environment's side once the loader has
    // registered its configs. A run with no stage never reached Mixin, so it
    // must not load a Mixin class for the phase either.
    if !stages.is_empty() {
        let side = MixinSide::selected(&entry_kind);
        let mut driver = JniMixinPhase { env: &mut *env };
        for line in run_mixin_phase(bootstrap.as_ref(), side, &mut driver) {
            println!("{line}");
        }
    }
    // The `String` a NeoForge entrypoint constructor receives is the jar's
    // `modId`; read it once from the metadata the run already reports.
    let neoforge_mod_id = constructor_only_entry_kind(&entry_kind)
        .then(|| neoforge_metadata(Path::new(&args[0])).ok())
        .flatten()
        .and_then(|metadata| metadata.mod_ids.into_iter().next());
    // Fabric runs loader-level `preLaunch` callbacks before the selected
    // environment's entrypoints; NeoForge has none and stays constructor-only.
    let mut work: Vec<(&str, &str)> = pre_launch
        .iter()
        .map(|spec| ("preLaunch", spec.as_str()))
        .collect();
    work.extend(
        entry_specs
            .iter()
            .map(|spec| (entry_kind.as_str(), spec.as_str())),
    );
    for (entry_kind, entry_spec) in work {
        let (entry, explicit_initializer) = split_entrypoint(entry_spec);
        let has_explicit_initializer = explicit_initializer.is_some();
        let (initializer, initializer_label) = if let Some(method) = explicit_initializer {
            (method.to_owned(), method.to_owned())
        } else if constructor_only_entry_kind(entry_kind) {
            (String::new(), "constructor".to_owned())
        } else {
            let (method, label) = initializer_for_kind(entry_kind)?;
            (method.to_owned(), label.to_owned())
        };
        let class = match env.find_class(entry.replace('.', "/")) {
            Ok(class) => class,
            Err(e) => return describe(env, "find_class", entry, e),
        };
        if constructor_only_entry_kind(entry_kind) && !has_explicit_initializer {
            let object = invoke_neoforge_constructor(
                env,
                &class,
                &classpath,
                entry,
                neoforge_mod_id.as_deref(),
                neoforge_dist(entry_kind),
            )?;
            call_mixin_on_load(env, &class, &object, entry)?;
            println!("{entry} constructor returned");
            continue;
        }
        // Fabric invokes a mod's common initializer before a `Class::method`
        // client/server entrypoint when both are declared on the same class. A
        // number of real mods use that method to publish their singleton state.
        // `preLaunch` is a loader-level callback, so it skips that bootstrap.
        if has_explicit_initializer && initializer != "onInitialize" && entry_kind != "preLaunch" {
            if env.get_method_id(&class, "onInitialize", "()V").is_ok() {
                let common = match env.new_object(&class, "()V", &[]) {
                    Ok(object) => object,
                    Err(e) => return describe(env, "new", entry, e),
                };
                call_mixin_on_load(env, &class, &common, entry)?;
                if let Err(e) = env.call_method(&common, "onInitialize", "()V", &[]) {
                    return describe(env, "onInitialize", entry, e);
                }
            } else {
                let _ = env.exception_clear();
            }
        }
        if has_explicit_initializer
            && env
                .get_static_method_id(&class, &initializer, "()V")
                .is_ok()
        {
            match env.call_static_method(&class, &initializer, "()V", &[]) {
                Ok(_) => {
                    println!("{initializer_label} returned");
                }
                Err(e) => return describe(env, &initializer_label, entry, e),
            }
            continue;
        }
        let _ = env.exception_clear();
        let object = match env.new_object(&class, "()V", &[]) {
            Ok(object) => object,
            Err(e) => return describe(env, "new", entry, e),
        };
        call_mixin_on_load(env, &class, &object, entry)?;
        if env.get_method_id(&class, &initializer, "()V").is_err() {
            let _ = env.exception_clear();
            if entry_kind == "main" && !has_explicit_initializer {
                println!("{entry} constructor returned (no {initializer} method)");
                continue;
            }
            return Err(format!(
                "{entry} has no {initializer}()V initializer for --entry-kind {entry_kind}"
            ));
        }
        match env.call_method(&object, &initializer, "()V", &[]) {
            Ok(_) => println!("{initializer_label} returned"),
            Err(e) => return describe(env, &initializer_label, entry, e),
        }
    }
    Ok(())
}

/// The fresh homes a gated launch gets: the Java game and anything it spawns
/// must never see real player data (`AGENTS.md`).
struct LaunchHomes {
    game: PathBuf,
    home: PathBuf,
    launcher: PathBuf,
    data: PathBuf,
    config: PathBuf,
    trash: PathBuf,
    clipboard: PathBuf,
    desktop: PathBuf,
}

impl LaunchHomes {
    fn new() -> Result<Self, String> {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|error| format!("clock: {error}"))?
            .as_nanos();
        let root =
            std::env::temp_dir().join(format!("horizon-launch-{}-{stamp}", std::process::id()));
        let homes = Self {
            game: root.join("game"),
            home: root.join("home"),
            launcher: root.join("launcher"),
            data: root.join("data"),
            config: root.join("config"),
            trash: root.join("trash"),
            clipboard: root.join("clipboard"),
            desktop: root.join("desktop"),
        };
        for dir in [
            &homes.game,
            &homes.home,
            &homes.launcher,
            &homes.data,
            &homes.config,
            &homes.trash,
            &homes.clipboard,
            &homes.desktop,
        ] {
            fs::create_dir_all(dir).map_err(|error| format!("{}: {error}", dir.display()))?;
        }
        Ok(homes)
    }
}

/// Bounded capture of one child stream, shared with the reading thread.
#[derive(Default)]
struct LaunchCapture {
    text: std::sync::Mutex<Vec<u8>>,
    started: std::sync::atomic::AtomicBool,
}

impl LaunchCapture {
    fn push(&self, chunk: &[u8]) {
        let Ok(mut text) = self.text.lock() else {
            return;
        };
        // The status and failure lines are at the end of a noisy stream, so the
        // bound keeps a rolling tail instead of the first bytes.
        text.extend_from_slice(chunk);
        if text.len() > LAUNCH_CAPTURE_BYTES {
            let excess = text.len() - LAUNCH_CAPTURE_BYTES;
            text.drain(..excess);
        }
        // The start marker is detected over everything read, even if the tail
        // has already moved past it.
        const MARKER: &[u8] = b"launch-game: started";
        if !self.started.load(std::sync::atomic::Ordering::Relaxed) {
            let start = text.len().saturating_sub(chunk.len() + MARKER.len());
            if text[start..]
                .windows(MARKER.len())
                .any(|window| window == MARKER)
            {
                self.started
                    .store(true, std::sync::atomic::Ordering::Relaxed);
            }
        }
    }

    fn text(&self) -> String {
        self.text
            .lock()
            .map(|text| String::from_utf8_lossy(&text).into_owned())
            .unwrap_or_default()
    }
}

/// Drain a child pipe; only the last [`LAUNCH_CAPTURE_BYTES`] are kept.
fn read_launch_pipe(mut reader: impl Read, capture: std::sync::Arc<LaunchCapture>) {
    let mut buffer = [0u8; 8192];
    loop {
        match reader.read(&mut buffer) {
            Ok(0) | Err(_) => break,
            Ok(read) => capture.push(&buffer[..read]),
        }
    }
}

/// Kill the child's whole process group, not just the child: the game may have
/// spawned helpers, and its JVM threads must not survive the deadline.
fn kill_launch_process_group(child: &mut std::process::Child) {
    #[cfg(unix)]
    {
        // `process_group(0)` made the child its own group leader.
        let pgid = child.id() as libc::pid_t;
        // SAFETY: `kill` only reads integers; a group that is already gone
        // yields `ESRCH`, which is exactly what a late timeout wants.
        unsafe {
            libc::kill(-pgid, libc::SIGKILL);
        }
    }
    let _ = child.kill();
}

fn launch_timeout() -> std::time::Duration {
    let secs = std::env::var(LAUNCH_GAME_TIMEOUT_ENV)
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|secs| *secs > 0)
        .unwrap_or(LAUNCH_GAME_TIMEOUT_SECS);
    std::time::Duration::from_secs(secs)
}

/// The reason a launch that never printed `started` failed: this binary's own
/// `error:` line, the bridge's `launch-game: failed`, the provider fallback
/// message, or the last non-empty line.
fn launch_failure_reason(output: &str) -> String {
    if let Some(line) = output.lines().find_map(|line| line.strip_prefix("error: ")) {
        return bounded_classpath_unlock(line.trim());
    }
    if let Some(line) = output
        .lines()
        .rev()
        .find_map(|line| line.strip_prefix("launch-game: failed "))
    {
        return bounded_classpath_unlock(line.trim());
    }
    const FALLBACK: &str = "production game provider unavailable (";
    for line in output.lines().rev() {
        if let Some(start) = line.find(FALLBACK) {
            let rest = &line[start + FALLBACK.len()..];
            let reason = rest
                .rfind("); using test provider")
                .map_or(rest, |end| &rest[..end]);
            return bounded_classpath_unlock(reason.trim());
        }
    }
    match output.lines().rev().find(|line| !line.trim().is_empty()) {
        Some(line) => bounded_classpath_unlock(line.trim()),
        None => "unknown".to_owned(),
    }
}

/// The child's own `launch-game:` line, last one first.
fn launch_status_line(output: &str) -> Option<String> {
    output
        .lines()
        .rev()
        .find_map(|line| line.strip_prefix("launch-game: "))
        .map(|value| value.trim().to_owned())
}

/// Report the ASM line used by the real loader without relying on a fixed
/// installation path. Fabric 26.3 needs ASM 9.8; 9.7 cannot parse its class
/// files and 9.10+ trips tinyremapper's final-method clash.
fn asm_readiness(libs: &Path) -> Option<String> {
    fn visit(root: &Path, versions: &mut Vec<(u32, u32)>) {
        let Ok(entries) = fs::read_dir(root) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                visit(&path, versions);
                continue;
            }
            let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                continue;
            };
            if !name.ends_with(".jar") || !path.to_string_lossy().contains("org/ow2/asm") {
                continue;
            }
            let stem = name.strip_suffix(".jar").unwrap_or(name);
            let Some(version) = stem.rsplit_once('-').map(|(_, version)| version) else {
                continue;
            };
            let mut numbers = version.split('.');
            let (Some(major), Some(minor)) = (numbers.next(), numbers.next()) else {
                continue;
            };
            let (Ok(major), Ok(minor)) = (major.parse(), minor.parse()) else {
                continue;
            };
            versions.push((major, minor));
        }
    }
    let mut versions = Vec::new();
    visit(libs, &mut versions);
    versions.sort_unstable();
    versions.dedup();
    let &(major, minor) = versions.last()?;
    if major == 9 && minor == 8 {
        Some("loader-libs: ok 9.8".to_owned())
    } else if major == 9 && minor <= 7 {
        Some(format!(
            "loader-libs: warning ASM {major}.{minor} too old for 26.3 class files"
        ))
    } else if major > 9 || (major == 9 && minor >= 10) {
        Some(format!(
            "loader-libs: warning ASM {major}.{minor} triggers tinyremapper final-method clash"
        ))
    } else {
        Some(format!(
            "loader-libs: warning unsupported ASM {major}.{minor}"
        ))
    }
}

/// The port the scratch server.properties names (the readiness probe connects to it).
fn launch_server_port(game: &Path) -> u16 {
    fs::read_to_string(game.join("server.properties"))
        .ok()
        .and_then(|text| {
            text.lines().find_map(|line| {
                line.strip_prefix("server-port=")
                    .and_then(|value| value.trim().parse::<u16>().ok())
            })
        })
        .unwrap_or(25565)
}

fn seed_launch_game_files(game: &Path, accept_eula: bool) -> Result<(), String> {
    let properties = game.join("server.properties");
    if !properties.exists() {
        let port = std::env::var(LAUNCH_SERVER_PORT_ENV)
            .ok()
            .and_then(|value| value.parse::<u16>().ok())
            .unwrap_or_else(|| {
                TcpListener::bind(("127.0.0.1", 0))
                    .ok()
                    .and_then(|listener| listener.local_addr().ok().map(|addr| addr.port()))
                    .unwrap_or(25565)
            });
        let contents = format!(
            "server-port={port}\nonline-mode=false\nlevel-type=minecraft:flat\nmax-players=4\nspawn-protection=0\nview-distance=4\n"
        );
        fs::write(&properties, contents)
            .map_err(|error| format!("write scratch server.properties: {error}"))?;
    }
    if accept_eula {
        let eula = game.join("eula.txt");
        if !eula.exists() {
            fs::write(eula, "eula=true\n")
                .map_err(|error| format!("write scratch eula.txt: {error}"))?;
        }
    }
    Ok(())
}

/// Flags whose next argument is a path, so the child can be given absolute
/// values before it changes into its fresh game directory.
const LAUNCH_PATH_ARG_FLAGS: [&str; 6] = [
    "--loader",
    "--libs",
    "--game-jar",
    "--stubs",
    "--mixin-config",
    "--datagen-output",
];
/// Flags whose next argument is not a path (`--entry-kind server` must stay a
/// value, not become an absolute path).
const LAUNCH_VALUE_ARG_FLAGS: [&str; 8] = [
    "--entry",
    "--entry-kind",
    "--game-version",
    "--heap",
    "--measure-timeout",
    "--measure-sample-ms",
    "--measure-repeat",
    "--mixin-apply-probe",
];

/// Resolve every relative path argument against `cwd`, because the launch child
/// runs in a fresh game directory. Flags that take a non-path value are left
/// alone.
fn absolutize_launch_args(args: Vec<OsString>, cwd: &Path) -> Vec<OsString> {
    let absolutize = |arg: OsString| -> OsString {
        let path = Path::new(&arg);
        if path.is_absolute() {
            arg
        } else {
            cwd.join(path).into_os_string()
        }
    };
    let mut out = Vec::with_capacity(args.len());
    let mut path_next = false;
    let mut value_next = false;
    for arg in args {
        if path_next {
            out.push(absolutize(arg));
            path_next = false;
            continue;
        }
        if value_next {
            out.push(arg);
            value_next = false;
            continue;
        }
        if let Some(text) = arg.to_str() {
            if LAUNCH_PATH_ARG_FLAGS.contains(&text) {
                path_next = true;
                out.push(arg);
                continue;
            }
            if LAUNCH_VALUE_ARG_FLAGS.contains(&text) {
                value_next = true;
                out.push(arg);
                continue;
            }
            if text.starts_with('-') {
                out.push(arg);
                continue;
            }
        }
        out.push(absolutize(arg));
    }
    out
}

/// Run the gated launch in a child of this binary and return the one status
/// value. The parent never starts a JVM itself, so a game that ignores every
/// shutdown path still dies with the process group at the deadline.
fn run_launch_game_child(accept_eula: bool) -> Result<String, String> {
    let homes = LaunchHomes::new()?;
    seed_launch_game_files(&homes.game, accept_eula)?;
    let exe = std::env::current_exe().map_err(|error| format!("launch child: {error}"))?;
    let cwd = std::env::current_dir().map_err(|error| format!("launch child: {error}"))?;
    let mut command = Command::new(exe);
    command.args(absolutize_launch_args(
        std::env::args_os().skip(1).collect(),
        &cwd,
    ));
    command.arg("--launch-game-child");
    command.current_dir(&homes.game);
    command.env(HORIZON_REAL_LAUNCH_ENV, "1");
    command.env("HORIZON_NO_AUDIO", "1");
    command.env("HORIZON_LAUNCHER_NO_SELF_UPDATE", "1");
    command.env("HORIZON_HOME", &homes.home);
    command.env("HORIZON_LAUNCHER_HOME", &homes.launcher);
    command.env("XDG_DATA_HOME", &homes.data);
    command.env("XDG_CONFIG_HOME", &homes.config);
    command.env("HORIZON_LAUNCHER_TRASH", &homes.trash);
    command.env("HORIZON_LAUNCHER_CLIPBOARD", &homes.clipboard);
    command.env("HORIZON_LAUNCHER_DESKTOP", &homes.desktop);
    command.stdout(Stdio::piped()).stderr(Stdio::piped());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        command.process_group(0);
    }
    let mut child = command
        .spawn()
        .map_err(|error| format!("launch child: {error}"))?;
    let stdout_capture = std::sync::Arc::new(LaunchCapture::default());
    let stderr_capture = std::sync::Arc::new(LaunchCapture::default());
    let mut readers = Vec::new();
    if let Some(stdout) = child.stdout.take() {
        let capture = std::sync::Arc::clone(&stdout_capture);
        readers.push(std::thread::spawn(move || {
            read_launch_pipe(stdout, capture)
        }));
    }
    if let Some(stderr) = child.stderr.take() {
        let capture = std::sync::Arc::clone(&stderr_capture);
        readers.push(std::thread::spawn(move || {
            read_launch_pipe(stderr, capture)
        }));
    }
    let timeout = launch_timeout();
    let deadline = std::time::Instant::now() + timeout;
    // A server that is up never exits on its own; a caller that only needs the
    // readiness line (the corpus ledgers, CI) stops the child at "Done (".
    // The game logs it to its own latest.log, not the parent's stdout.
    let stop_at_done = std::env::var("HORIZON_LAUNCH_STOP_AT_DONE").as_deref() == Ok("1");
    let ready_port = launch_server_port(&homes.game);
    let ready_addr = std::net::SocketAddr::from(([127, 0, 0, 1], ready_port));
    let done_log = homes.game.join("logs").join("latest.log");
    let mut done_log_len = 0u64;
    let mut stopped_at_done = false;
    let mut timed_out = false;
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break Some(status),
            Ok(None) => {}
            Err(error) => {
                kill_launch_process_group(&mut child);
                let _ = child.wait();
                for reader in readers {
                    let _ = reader.join();
                }
                return Err(format!("launch child: {error}"));
            }
        }
        if stop_at_done {
            // The one signal that cannot lie: the server accepts connections.
            // "Done" may only reach the game's own log, and that log is not
            // written in every configuration.
            let mut done = std::net::TcpStream::connect_timeout(
                &ready_addr,
                std::time::Duration::from_millis(50),
            )
            .is_ok();
            if !done {
                done = stdout_capture.text().contains("Done (");
            }
            if !done {
                if let Ok(meta) = std::fs::metadata(&done_log) {
                    if meta.len() != done_log_len {
                        done_log_len = meta.len();
                        done = log_tail_contains(&done_log, "Done (");
                    }
                }
            }
            if done {
                stopped_at_done = true;
                kill_launch_process_group(&mut child);
                break child.wait().ok();
            }
        }
        if std::time::Instant::now() >= deadline {
            timed_out = true;
            kill_launch_process_group(&mut child);
            break child.wait().ok();
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    };
    for reader in readers {
        let _ = reader.join();
    }
    let stdout = stdout_capture.text();
    let stderr = stderr_capture.text();
    // The bridge and this binary print their status on stdout; stderr carries
    // log noise and failed-bootstrap reasons.
    let started = stdout_capture
        .started
        .load(std::sync::atomic::Ordering::Relaxed)
        || stderr_capture
            .started
            .load(std::sync::atomic::Ordering::Relaxed);
    let explicit = launch_status_line(&stdout).or_else(|| launch_status_line(&stderr));
    let status = match explicit {
        Some(value) if value != "started" && !stopped_at_done => value,
        _ if stopped_at_done => "exit 0".to_owned(),
        _ if timed_out => format!("failed timed out after {}s", timeout.as_secs()),
        _ if started => exit_status_value(status.as_ref()),
        _ => {
            let reason = launch_failure_reason(&stdout);
            let reason = if reason == "unknown" {
                launch_failure_reason(&stderr)
            } else {
                reason
            };
            format!("failed {reason}")
        }
    };
    if !status.starts_with("exit 0") {
        let tail: String = format!("{stdout}\n{stderr}")
            .chars()
            .rev()
            .take(LAUNCH_OUTPUT_ECHO_CHARS)
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .collect();
        if !tail.trim().is_empty() {
            eprintln!("launch-game output:\n{tail}");
        }
    }
    Ok(bounded_classpath_unlock(&status))
}

/// Whether the last part of a log file contains `needle` (the game's readiness
/// line is written to its own log, not necessarily the parent's stdout).
fn log_tail_contains(path: &std::path::Path, needle: &str) -> bool {
    use std::io::{Read, Seek, SeekFrom};
    let Ok(meta) = std::fs::metadata(path) else {
        return false;
    };
    let start = meta.len().saturating_sub(256 * 1024);
    let Ok(mut file) = std::fs::File::open(path) else {
        return false;
    };
    if file.seek(SeekFrom::Start(start)).is_err() {
        return false;
    }
    let mut bytes = Vec::new();
    if file.take(256 * 1024).read_to_end(&mut bytes).is_err() {
        return false;
    }
    String::from_utf8_lossy(&bytes).contains(needle)
}

/// `exit <code>` / `failed <signal>` for a child that did start.
fn exit_status_value(status: Option<&std::process::ExitStatus>) -> String {
    let Some(status) = status else {
        return "failed no exit status".to_owned();
    };
    if let Some(code) = status.code() {
        return format!("exit {code}");
    }
    #[cfg(unix)]
    {
        use std::os::unix::process::ExitStatusExt;
        if let Some(signal) = status.signal() {
            return format!("failed signal {signal}");
        }
    }
    "failed no exit status".to_owned()
}

/// Entrypoint kinds that select Fabric's data-generation callback.
fn is_datagen_kind(kind: &str) -> bool {
    matches!(kind, "datagen" | "fabric-datagen" | "data")
}

/// The `entrypoints.<kind>` groups a datagen run accepts: Fabric's spelling and
/// the hand-written/Quilt one.
const DATAGEN_ENTRYPOINT_KINDS: [&str; 2] = ["fabric-datagen", "datagen"];
const FABRIC_DATAGEN_OUTPUT: &str = "fabric.datagen.output";

/// `-Dfabric.datagen.output=<dir>`, or nothing when the flag was not passed.
fn datagen_jvm_options(output: Option<&Path>) -> Vec<String> {
    output
        .map(|dir| vec![format!("-D{}={}", FABRIC_DATAGEN_OUTPUT, dir.display())])
        .unwrap_or_default()
}

const DATAGEN_GENERATOR_CLASS: &str = "net/fabricmc/fabric/api/datagen/v1/FabricDataGenerator";
const DATAGEN_OUTPUT_CLASS: &str = "net/fabricmc/fabric/api/datagen/v1/FabricDataOutput";
const MOD_CONTAINER_CLASS: &str = "net/fabricmc/loader/api/ModContainer";
const DATAGEN_INIT_SIG: &str = "(Lnet/fabricmc/fabric/api/datagen/v1/FabricDataGenerator;)V";
const DATAGEN_OUTPUT_CTOR: &str = "(Lnet/fabricmc/loader/api/ModContainer;Ljava/nio/file/Path;Z)V";
const DATAGEN_GENERATOR_CTOR: &str = "(Lnet/fabricmc/fabric/api/datagen/v1/FabricDataOutput;Lnet/fabricmc/loader/api/ModContainer;)V";
const MOD_CONTAINER_HORIZON_SIG: &str =
    "(Ljava/lang/String;Ljava/lang/String;)Lnet/fabricmc/loader/api/ModContainer;";
const DATAGEN_PROVIDERS: &str = "horizonProviders";
const DATAGEN_PROVIDERS_SIG: &str = "()Ljava/util/List;";
const MAX_DATAGEN_PROVIDERS: usize = 256;

/// The error a run without the façade's datagen slice reports; `main` turns it
/// into `error: ...` and a non-zero exit.
fn datagen_shim_unavailable(class: &str) -> String {
    format!("datagen: shim unavailable ({class} is not on the classpath)")
}

fn datagen_providers_line(count: usize) -> String {
    format!("datagen providers: {count}")
}

/// One `datagen provider N: pack/id (kind)` line, in registration order.
fn datagen_provider_line(index: usize, pack: &str, id: &str, kind: &str) -> String {
    format!("datagen provider {}: {pack}/{id} ({kind})", index + 1)
}

/// A class the shim slice must carry, cleared of a pending lookup failure.
fn datagen_class<'local>(env: &mut JNIEnv<'local>, name: &str) -> Result<JClass<'local>, String> {
    match env.find_class(name) {
        Ok(class) => Ok(class),
        Err(_) => {
            let _ = env.exception_clear();
            Err(datagen_shim_unavailable(name))
        }
    }
}

/// Datagen runs the `fabric-datagen` callback only. The JVM is started here so
/// no client/server/main initializer or Mixin phase can run: those are planned
/// after this branch in [`run`].
fn run_datagen(
    classpath: &[PathBuf],
    entries: &[String],
    output: Option<&Path>,
    heap: &str,
    nested: &NestedJars,
    metadata: Option<&(String, String)>,
) -> Result<(), String> {
    let output_dir = output.map_or_else(
        || std::env::temp_dir().join("horizon-datagen"),
        Path::to_path_buf,
    );
    let paths = std::env::join_paths(classpath).map_err(|e| e.to_string())?;
    let mut init = InitArgsBuilder::new()
        .version(JNIVersion::V8)
        .option(format!("-Djava.class.path={}", paths.to_string_lossy()))
        .option(heap)
        .option("-Djava.awt.headless=true")
        .option("-XX:+StartAttachListener");
    for option in datagen_jvm_options(output) {
        init = init.option(option);
    }
    let init = init.build().map_err(|e| format!("JVM options: {e}"))?;
    let jvm = JavaVM::new(init)
        .map_err(|e| format!("could not start a JVM ({e}); set JAVA_HOME to a JDK with libjvm"))?;
    let mut guard = jvm
        .attach_current_thread()
        .map_err(|e| format!("attach: {e}"))?;
    let env = &mut *guard;
    prepare_fabric_loader(env, &nested.root)?;
    seed_fabric_metadata(env, classpath)?;
    let generator = new_datagen_generator(env, &output_dir, metadata)?;
    println!("datagen output: {}", output_dir.display());
    for entry in entries {
        invoke_datagen_entry(env, &generator, entry)?;
    }
    for line in report_datagen_providers(env, &generator)? {
        println!("{line}");
    }
    Ok(())
}

/// Build the façade's `FabricDataGenerator` from `FabricDataOutput` and the
/// loader slice's `ModContainer.horizon(id, version)`. A classpath without the
/// shim fails with [`datagen_shim_unavailable`] before any entrypoint runs.
fn new_datagen_generator<'local>(
    env: &mut JNIEnv<'local>,
    output: &Path,
    metadata: Option<&(String, String)>,
) -> Result<JObject<'local>, String> {
    let generator = datagen_class(env, DATAGEN_GENERATOR_CLASS)?;
    let output_class = datagen_class(env, DATAGEN_OUTPUT_CLASS)?;
    let container_class = datagen_class(env, MOD_CONTAINER_CLASS)?;
    if env
        .get_static_method_id(&container_class, "horizon", MOD_CONTAINER_HORIZON_SIG)
        .is_err()
    {
        let _ = env.exception_clear();
        return Err(datagen_shim_unavailable(&format!(
            "{MOD_CONTAINER_CLASS}.horizon"
        )));
    }
    let (id, version) = metadata.map_or(("minecraft", "26.3"), |(id, version)| {
        (id.as_str(), version.as_str())
    });
    let id = env
        .new_string(id)
        .map_err(|e| format!("datagen mod id: {e}"))?;
    let version = env
        .new_string(version)
        .map_err(|e| format!("datagen mod version: {e}"))?;
    let container = env
        .call_static_method(
            &container_class,
            "horizon",
            MOD_CONTAINER_HORIZON_SIG,
            &[
                JValue::Object(&JObject::from(id)),
                JValue::Object(&JObject::from(version)),
            ],
        )
        .map_err(|e| format!("datagen ModContainer: {e}"))?
        .l()
        .map_err(|e| format!("datagen ModContainer: {e}"))?;
    let paths = datagen_class(env, "java/nio/file/Paths")?;
    let output_text = env
        .new_string(output.to_string_lossy())
        .map_err(|e| format!("datagen output path: {e}"))?;
    let empty = env
        .new_object_array(0, "java/lang/String", JObject::null())
        .map_err(|e| format!("datagen output path: {e}"))?;
    let path = env
        .call_static_method(
            &paths,
            "get",
            "(Ljava/lang/String;[Ljava/lang/String;)Ljava/nio/file/Path;",
            &[
                JValue::Object(&JObject::from(output_text)),
                JValue::Object(&empty),
            ],
        )
        .map_err(|e| format!("datagen output path: {e}"))?
        .l()
        .map_err(|e| format!("datagen output path: {e}"))?;
    let output = env
        .new_object(
            &output_class,
            DATAGEN_OUTPUT_CTOR,
            &[
                JValue::Object(&container),
                JValue::Object(&path),
                JValue::Bool(0),
            ],
        )
        .map_err(|e| format!("datagen FabricDataOutput: {e}"))?;
    env.new_object(
        &generator,
        DATAGEN_GENERATOR_CTOR,
        &[JValue::Object(&output), JValue::Object(&container)],
    )
    .map_err(|e| format!("datagen FabricDataGenerator: {e}"))
}

/// One datagen entrypoint: a class implementing `DataGeneratorEntrypoint`, which
/// Fabric instantiates and hands the generator.
fn invoke_datagen_entry(
    env: &mut JNIEnv,
    generator: &JObject,
    entry_spec: &str,
) -> Result<(), String> {
    let (entry, method) = split_entrypoint(entry_spec);
    if method.is_some() {
        return Err(format!(
            "datagen entrypoint {entry_spec} names a method; pass --entry <class>"
        ));
    }
    let class = match env.find_class(entry.replace('.', "/")) {
        Ok(class) => class,
        Err(e) => return describe(env, "find_class", entry, e),
    };
    let object = match env.new_object(&class, "()V", &[]) {
        Ok(object) => object,
        Err(e) => return describe(env, "new", entry, e),
    };
    match env.call_method(
        &object,
        "onInitializeDataGenerator",
        DATAGEN_INIT_SIG,
        &[JValue::Object(generator)],
    ) {
        Ok(_) => println!("datagen: onInitializeDataGenerator returned"),
        Err(e) => return describe(env, "onInitializeDataGenerator", entry, e),
    }
    Ok(())
}

/// Read the shim's `horizonProviders()` ledger after the entrypoint returned:
/// one row per `addProvider`, in call order. A shim without the accessor (an
/// older façade) reports nothing instead of failing.
fn report_datagen_providers(env: &mut JNIEnv, generator: &JObject) -> Result<Vec<String>, String> {
    let class = env
        .get_object_class(generator)
        .map_err(|e| format!("datagen providers: {e}"))?;
    if env
        .get_method_id(&class, DATAGEN_PROVIDERS, DATAGEN_PROVIDERS_SIG)
        .is_err()
    {
        let _ = env.exception_clear();
        return Ok(Vec::new());
    }
    let list = env
        .call_method(generator, DATAGEN_PROVIDERS, DATAGEN_PROVIDERS_SIG, &[])
        .and_then(|value| value.l())
        .map_err(|e| format!("datagen providers: {e}"))?;
    let count = env
        .call_method(&list, "size", "()I", &[])
        .and_then(|value| value.i())
        .map_err(|e| format!("datagen providers: {e}"))?;
    let count = usize::try_from(count).unwrap_or(0);
    let mut lines = vec![datagen_providers_line(count)];
    for index in 0..count.min(MAX_DATAGEN_PROVIDERS) {
        let row = env
            .call_method(
                &list,
                "get",
                "(I)Ljava/lang/Object;",
                &[JValue::Int(index as i32)],
            )
            .and_then(|value| value.l())
            .map_err(|e| format!("datagen provider {index}: {e}"))?;
        let row = JObjectArray::from(row);
        if env.get_array_length(&row).unwrap_or(0) >= 3 {
            let pack = provider_text(env, &row, 0)?;
            let id = provider_text(env, &row, 1)?;
            let kind = provider_text(env, &row, 2)?;
            lines.push(datagen_provider_line(index, &pack, &id, &kind));
        }
    }
    if count > MAX_DATAGEN_PROVIDERS {
        lines.push(format!(
            "datagen providers: capped at {MAX_DATAGEN_PROVIDERS} of {count}"
        ));
    }
    Ok(lines)
}

/// One `{pack, id, kind, provider}` column as text; a null column (a shim that
/// retained no id) reads as `null` instead of failing the report.
fn provider_text(env: &mut JNIEnv, row: &JObjectArray, column: i32) -> Result<String, String> {
    let value = env
        .get_object_array_element(row, column)
        .map_err(|e| format!("datagen provider value: {e}"))?;
    if value.is_null() {
        return Ok("null".to_owned());
    }
    let text = env
        .get_string((&value).into())
        .map_err(|e| format!("datagen provider value: {e}"))?;
    Ok(text.to_string_lossy().into_owned())
}

fn split_entrypoint(spec: &str) -> (&str, Option<&str>) {
    spec.split_once("::")
        .map_or((spec, None), |(class, method)| (class, Some(method)))
}

fn constructor_only_entry_kind(kind: &str) -> bool {
    kind == "neoforge"
}

/// The parameter types a NeoForge entrypoint constructor may take. NeoForge
/// injects exactly these, so a constructor taking anything else cannot run here.
const NEOFORGE_DIST_TYPE: &str = "Lnet/neoforged/api/distmarker/Dist;";
const NEOFORGE_MOD_ID_TYPE: &str = "Ljava/lang/String;";
/// Loader objects the probe can name but not build: passed as `null`, which
/// makes a mod's first call on one the exact failure this probe exists to find.
const NEOFORGE_NULL_TYPES: [&str; 4] = [
    "Lnet/neoforged/bus/api/IEventBus;",
    "Lnet/neoforged/fml/ModContainer;",
    "Lnet/neoforged/fml/javafmlmod/FMLModContainer;",
    "Lnet/neoforged/fml/ModList;",
];
const NEOFORGE_DIST_CLASS: &str = "net/neoforged/api/distmarker/Dist";
const NO_ARG_CONSTRUCTOR: &str = "()V";

/// One NeoForge entrypoint constructor parameter.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NeoforgeArg {
    /// The `Dist` constant for `--entry-kind`: `CLIENT`, or the dedicated side.
    Dist,
    /// The jar's `modId`.
    ModId,
    /// A loader object the runner cannot build yet, passed as `null`.
    Null,
}

/// The `Dist` constant an entrypoint constructor receives. `--entry-kind`
/// selects the side the same way it does for Mixin; the loader-lifecycle kinds
/// (`neoforge`, `main`) run as the client this probe models.
fn neoforge_dist(entry_kind: &str) -> MixinSide {
    MixinSide::selected(entry_kind).unwrap_or(MixinSide::Client)
}

/// What one constructor parameter receives, or `None` when the runner cannot
/// supply it (which disqualifies that constructor).
fn neoforge_arg(param: &str) -> Option<NeoforgeArg> {
    if param == NEOFORGE_DIST_TYPE {
        Some(NeoforgeArg::Dist)
    } else if param == NEOFORGE_MOD_ID_TYPE {
        Some(NeoforgeArg::ModId)
    } else if NEOFORGE_NULL_TYPES.contains(&param) {
        Some(NeoforgeArg::Null)
    } else {
        None
    }
}

/// The arguments `descriptor` takes, or `None` when a parameter is not one the
/// runner can supply.
fn neoforge_constructor_args(descriptor: &str) -> Option<Vec<NeoforgeArg>> {
    descriptor_params(descriptor)?
        .iter()
        .map(|param| neoforge_arg(param))
        .collect()
}

/// The widest constructor whose parameters are all injectable, ties broken by
/// descriptor text so class-file order never decides; `None` leaves the no-arg
/// one.
fn neoforge_constructor_descriptor(constructors: &[String]) -> Option<&str> {
    constructors
        .iter()
        .filter_map(|descriptor| {
            let args = neoforge_constructor_args(descriptor)?;
            Some((args.len(), descriptor.as_str()))
        })
        .max_by(|a, b| a.0.cmp(&b.0).then_with(|| b.1.cmp(a.1)))
        .map(|(_, descriptor)| descriptor)
}

/// The entrypoint constructor for `class`: the widest supported one, else
/// `()V`. An unreadable class file (not on the classpath, malformed, above
/// [`MAX_CLASS_FILE_BYTES`]) also lands on `()V`, so this never fails a run
/// that has a no-arg constructor.
fn neoforge_constructor(classpath: &[PathBuf], class: &str) -> String {
    class_file_bytes(classpath, class)
        .and_then(|bytes| parse_constructors(&bytes))
        .and_then(|constructors| neoforge_constructor_descriptor(&constructors).map(str::to_owned))
        .unwrap_or_else(|| NO_ARG_CONSTRUCTOR.to_owned())
}

/// `neoforge ctor: <descriptor>`, naming the constructor that ran.
fn neoforge_ctor_line(descriptor: &str) -> String {
    format!("neoforge ctor: {descriptor}")
}

/// The single line a link failure reports before the no-arg retry.
fn neoforge_ctor_fallback_line(descriptor: &str) -> String {
    format!("neoforge ctor: {descriptor} unavailable, retrying {NO_ARG_CONSTRUCTOR}")
}

/// Link failures that mean the JVM could not link the constructor the class
/// file named, which is what a façade without the loader classes reports.
fn link_failure(class: &str) -> bool {
    matches!(
        class,
        "java.lang.NoSuchMethodError" | "java.lang.AbstractMethodError"
    )
}

/// Whether a failed constructor attempt retries `()V`: only a link failure of a
/// non-no-arg descriptor does, so a run with a no-arg constructor never fails.
fn should_retry_no_arg(descriptor: &str, failure: Option<&str>) -> bool {
    descriptor != NO_ARG_CONSTRUCTOR && failure.is_some_and(link_failure)
}

/// Upper bound on one class file the scan reads: no unbounded allocation.
const MAX_CLASS_FILE_BYTES: u64 = 4 << 20;

/// The JVM's own array-dimension limit, so the splitter cannot loop on garbage.
const MAX_ARRAY_DIMENSIONS: usize = 255;

/// The class file bytes for a binary class name, in classpath order like the
/// JVM. Only the first match is read, and only up to [`MAX_CLASS_FILE_BYTES`];
/// anything else is `None`, which leaves the no-arg constructor.
fn class_file_bytes(classpath: &[PathBuf], class: &str) -> Option<Vec<u8>> {
    let entry = format!("{}.class", class.replace('.', "/"));
    for path in classpath {
        if path.is_dir() {
            let file = path.join(&entry);
            let Ok(metadata) = fs::metadata(&file) else {
                continue;
            };
            if !metadata.is_file() || metadata.len() > MAX_CLASS_FILE_BYTES {
                continue;
            }
            if let Ok(bytes) = fs::read(&file) {
                return Some(bytes);
            }
            continue;
        }
        let Ok(file) = File::open(path) else {
            continue;
        };
        let Ok(mut archive) = zip::ZipArchive::new(file) else {
            continue;
        };
        let Ok(mut member) = archive.by_name(&entry) else {
            continue;
        };
        if member.size() > MAX_CLASS_FILE_BYTES {
            continue;
        }
        let mut bytes = Vec::new();
        if std::io::Read::read_to_end(&mut member, &mut bytes).is_ok() {
            return Some(bytes);
        }
    }
    None
}

/// A bounded class-file cursor: every read checks the remaining bytes, so a
/// truncated or hostile file fails instead of panicking.
struct ClassReader<'a> {
    bytes: &'a [u8],
    at: usize,
}

impl<'a> ClassReader<'a> {
    fn take(&mut self, len: usize) -> Option<&'a [u8]> {
        let end = self.at.checked_add(len)?;
        let bytes = self.bytes.get(self.at..end)?;
        self.at = end;
        Some(bytes)
    }

    fn u1(&mut self) -> Option<u8> {
        Some(*self.take(1)?.first()?)
    }

    fn u2(&mut self) -> Option<u16> {
        let bytes = self.take(2)?;
        Some(u16::from_be_bytes([bytes[0], bytes[1]]))
    }

    fn u4(&mut self) -> Option<u32> {
        let bytes = self.take(4)?;
        Some(u32::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
    }

    fn skip(&mut self, len: usize) -> Option<()> {
        self.take(len).map(|_| ())
    }
}

/// The `<init>` descriptors a class file declares, in declaration order.
/// Total by construction: a malformed or truncated file is `None`, and every
/// index is checked against the constant pool.
fn parse_constructors(bytes: &[u8]) -> Option<Vec<String>> {
    let mut reader = ClassReader { bytes, at: 0 };
    if reader.u4()? != 0xCAFE_BABE {
        return None;
    }
    reader.skip(4)?; // minor_version, major_version
    let pool = constant_pool(&mut reader)?;
    reader.skip(6)?; // access_flags, this_class, super_class
    let interfaces = reader.u2()? as usize;
    reader.skip(interfaces.checked_mul(2)?)?;
    let fields = reader.u2()? as usize;
    for _ in 0..fields {
        skip_member(&mut reader)?;
    }
    let methods = reader.u2()? as usize;
    let mut constructors = Vec::new();
    for _ in 0..methods {
        let (name, descriptor) = member_header(&mut reader)?;
        if pool.get(name as usize).copied().flatten() == Some("<init>") {
            let descriptor = pool.get(descriptor as usize).copied().flatten()?;
            constructors.push(descriptor.to_owned());
        }
        skip_attributes(&mut reader)?;
    }
    skip_attributes(&mut reader)?; // the class's own attributes
    Some(constructors)
}

/// The `Utf8` entries of a constant pool, indexed by constant-pool index.
/// Other entries are skipped by their fixed tag length; long and double take
/// two slots, as in the class-file format.
fn constant_pool<'a>(reader: &mut ClassReader<'a>) -> Option<Vec<Option<&'a str>>> {
    let count = reader.u2()? as usize;
    if count == 0 {
        return None;
    }
    let mut pool: Vec<Option<&'a str>> = vec![None; count];
    let mut index = 1;
    while index < count {
        match reader.u1()? {
            1 => {
                let len = reader.u2()? as usize;
                pool[index] = Some(std::str::from_utf8(reader.take(len)?).ok()?);
            }
            3 | 4 => reader.skip(4)?,
            // Long and double occupy two constant-pool slots.
            5 | 6 => {
                reader.skip(8)?;
                index += 1;
            }
            7 | 8 | 16 | 19 | 20 => reader.skip(2)?,
            9 | 10 | 11 | 12 | 17 | 18 => reader.skip(4)?,
            15 => reader.skip(3)?,
            _ => return None,
        }
        index += 1;
    }
    Some(pool)
}

/// A field or method's `(name_index, descriptor_index)` pair.
fn member_header(reader: &mut ClassReader) -> Option<(u16, u16)> {
    reader.skip(2)?; // access_flags
    let name = reader.u2()?;
    let descriptor = reader.u2()?;
    Some((name, descriptor))
}

/// One field, which the constructor scan does not need.
fn skip_member(reader: &mut ClassReader) -> Option<()> {
    reader.skip(6)?; // access_flags, name_index, descriptor_index
    skip_attributes(reader)
}

/// `attribute_count` followed by each `(name_index, length)` and its bytes.
fn skip_attributes(reader: &mut ClassReader) -> Option<()> {
    let count = reader.u2()? as usize;
    for _ in 0..count {
        reader.skip(2)?;
        let len = usize::try_from(reader.u4()?).ok()?;
        reader.skip(len)?;
    }
    Some(())
}

/// Splits a method descriptor into its parameter type descriptors. `None` for
/// anything that is not a well-formed `(...)R` descriptor.
fn descriptor_params(descriptor: &str) -> Option<Vec<&str>> {
    let (params, _) = descriptor.strip_prefix('(')?.split_once(')')?;
    let mut out = Vec::new();
    let mut rest = params;
    while !rest.is_empty() {
        let (param, remainder) = split_type(rest)?;
        out.push(param);
        rest = remainder;
    }
    Some(out)
}

/// One type descriptor at the start of `text`, with the rest of `text`.
fn split_type(text: &str) -> Option<(&str, &str)> {
    let bytes = text.as_bytes();
    let mut start = 0;
    while bytes.get(start) == Some(&b'[') {
        start += 1;
        if start > MAX_ARRAY_DIMENSIONS {
            return None;
        }
    }
    let element = text.get(start..)?;
    let len = match element.as_bytes().first()? {
        b'L' => element.find(';')? + 1,
        b'B' | b'C' | b'D' | b'F' | b'I' | b'J' | b'S' | b'Z' => 1,
        _ => return None,
    };
    let end = start.checked_add(len)?;
    Some((text.get(..end)?, text.get(end..)?))
}

/// The `Dist` field names a constructor receives. NeoForge names the dedicated
/// side `DEDICATED_SERVER`; the bare `SERVER` spelling is tried second so a
/// build using either name works.
fn neoforge_dist_fields(side: MixinSide) -> &'static [&'static str] {
    match side {
        MixinSide::Client => &["CLIENT"],
        MixinSide::Server => &["DEDICATED_SERVER", "SERVER"],
    }
}

/// The `Dist` constant for `side`, or `null` when the façade carries neither the
/// class nor the field: the constructor still runs instead of the probe failing.
fn dist_constant<'local>(env: &mut JNIEnv<'local>, side: MixinSide) -> JObject<'local> {
    let Ok(class) = env.find_class(NEOFORGE_DIST_CLASS) else {
        let _ = env.exception_clear();
        return JObject::null();
    };
    for field in neoforge_dist_fields(side) {
        if let Ok(value) = env.get_static_field(&class, *field, NEOFORGE_DIST_TYPE) {
            if let Ok(value) = value.l() {
                return value;
            }
        }
        // A field this build does not have must not leave a throwable behind
        // for the constructor call.
        let _ = env.exception_clear();
    }
    JObject::null()
}

/// The objects one NeoForge constructor call passes, in parameter order.
fn neoforge_ctor_objects<'local>(
    env: &mut JNIEnv<'local>,
    args: &[NeoforgeArg],
    side: MixinSide,
    mod_id: Option<&str>,
) -> Vec<JObject<'local>> {
    let mut objects = Vec::with_capacity(args.len());
    for arg in args {
        objects.push(match arg {
            NeoforgeArg::Dist => dist_constant(env, side),
            NeoforgeArg::ModId => match mod_id {
                Some(id) => match env.new_string(id) {
                    Ok(id) => JObject::from(id),
                    Err(_) => {
                        let _ = env.exception_clear();
                        JObject::null()
                    }
                },
                None => JObject::null(),
            },
            NeoforgeArg::Null => JObject::null(),
        });
    }
    objects
}

/// Run a NeoForge entrypoint's constructor, retried as the no-arg one when the
/// JVM cannot link it. The line naming a constructor is printed only once the
/// call was accepted, so a fallback reads as one failure line then the retry.
fn invoke_neoforge_constructor<'local>(
    env: &mut JNIEnv<'local>,
    class: &JClass<'local>,
    classpath: &[PathBuf],
    entry: &str,
    mod_id: Option<&str>,
    side: MixinSide,
) -> Result<JObject<'local>, String> {
    let descriptor = neoforge_constructor(classpath, entry);
    let args = neoforge_constructor_args(&descriptor).unwrap_or_default();
    let objects = neoforge_ctor_objects(env, &args, side, mod_id);
    let values: Vec<JValue> = objects.iter().map(JValue::Object).collect();
    match env.new_object(class, descriptor.as_str(), &values) {
        Ok(object) => {
            println!("{}", neoforge_ctor_line(&descriptor));
            Ok(object)
        }
        Err(error) => {
            let failure = pending_throwable_class(env);
            if !should_retry_no_arg(&descriptor, failure.as_deref()) {
                return Err(describe_error(env, "new", entry, error));
            }
            let _ = env.exception_clear();
            println!("{}", neoforge_ctor_fallback_line(&descriptor));
            match env.new_object(class, NO_ARG_CONSTRUCTOR, &[]) {
                Ok(object) => Ok(object),
                Err(error) => Err(describe_error(env, "new", entry, error)),
            }
        }
    }
}

fn call_mixin_on_load(
    env: &mut JNIEnv,
    class: &JClass,
    object: &JObject,
    entry: &str,
) -> Result<(), String> {
    if env
        .get_method_id(class, "onLoad", "(Ljava/lang/String;)V")
        .is_err()
    {
        let _ = env.exception_clear();
        return Ok(());
    }
    let package = entry.rsplit_once('.').map_or(entry, |(package, _)| package);
    let package = env
        .new_string(package)
        .map_err(|e| format!("Mixin onLoad package: {e}"))?;
    let package = JObject::from(package);
    env.call_method(
        object,
        "onLoad",
        "(Ljava/lang/String;)V",
        &[JValue::Object(&package)],
    )
    .map(|_| ())
    .map_err(|e| format!("Mixin onLoad {entry}: {e}"))
}

fn seed_fabric_metadata(env: &mut JNIEnv, classpath: &[PathBuf]) -> Result<(), String> {
    if env
        .find_class("net/fabricmc/loader/impl/FabricLoaderImpl")
        .is_err()
    {
        let _ = env.exception_clear();
        return Ok(());
    }
    let bridge = match env.find_class("HorizonLoaderBridge") {
        Ok(class) => class,
        Err(_) => {
            let _ = env.exception_clear();
            return Ok(());
        }
    };
    for path in classpath {
        let Some((id, version)) = fabric_metadata(path) else {
            continue;
        };
        let id = env
            .new_string(id)
            .map_err(|e| format!("Fabric metadata id: {e}"))?;
        let version = env
            .new_string(version)
            .map_err(|e| format!("Fabric metadata version: {e}"))?;
        env.call_static_method(
            &bridge,
            "seed",
            "(Ljava/lang/String;Ljava/lang/String;)V",
            &[JValue::Object(&id.into()), JValue::Object(&version.into())],
        )
        .map_err(|e| format!("Fabric metadata seed for {}: {e}", path.display()))?;
    }
    Ok(())
}

fn fabric_metadata(path: &Path) -> Option<(String, String)> {
    let file = File::open(path).ok()?;
    let mut archive = zip::ZipArchive::new(file).ok()?;
    let mut metadata = archive.by_name("fabric.mod.json").ok()?;
    let mut text = String::new();
    std::io::Read::read_to_string(&mut metadata, &mut text).ok()?;
    let value: serde_json::Value = serde_json::from_str(&text).ok()?;
    let id = value.get("id")?.as_str()?.to_owned();
    let version = match value.get("version") {
        Some(serde_json::Value::String(version)) => version.clone(),
        Some(serde_json::Value::Object(version)) => version
            .get("semver")
            .or_else(|| version.get("raw"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or("0")
            .to_owned(),
        _ => "0".to_owned(),
    };
    Some((id, version))
}

/// Upper bound on the ids a discovery report names, matching the bridge.
const MAX_DISCOVERED_MOD_IDS: usize = 64;

/// The mod ids the supplied jars declare in `fabric.mod.json`: the same set
/// the reflective seed registers, sorted, deduplicated and bounded so the
/// discovery line stays one line.
fn declared_mod_ids(jars: &[PathBuf]) -> Vec<String> {
    let mut ids: Vec<String> = jars
        .iter()
        .filter_map(|jar| fabric_metadata(jar).map(|(id, _)| id))
        .collect();
    ids.sort();
    ids.dedup();
    ids.truncate(MAX_DISCOVERED_MOD_IDS);
    ids
}

/// `discovery: N declared, M found, missing=<list>`: declared ids the loader
/// never reported are named, so the loader's own discovery is checkable.
fn discovery_line(declared: &[String], found: &[String]) -> String {
    let missing: Vec<&str> = declared
        .iter()
        .filter(|id| !found.contains(id))
        .map(String::as_str)
        .collect();
    format!(
        "discovery: {} declared, {} found, missing={}",
        declared.len(),
        found.len(),
        missing.join(",")
    )
}

/// Fabric's documented developer property for classpath mods, and the loader
/// flags this probe may forward. The loader reads them before any entrypoint
/// runs, so they have to be in the JVM options.
const FABRIC_ADD_MODS: &str = "fabric.addMods";
const FABRIC_DEVELOPMENT: &str = "fabric.development";
const FABRIC_SKIP_MC_PROVIDER: &str = "fabric.skipMcProvider";

/// Upper bounds for `-Dfabric.addMods`: the list is one JVM argument, so a
/// hostile or accidental thousand-jar command line must not grow without bound.
const MAX_FABRIC_ADD_MODS: usize = 256;
const MAX_FABRIC_ADD_MODS_BYTES: usize = 32 * 1024;

/// The platform path separator, what Java's `File.pathSeparator` reports and
/// the character Fabric splits `fabric.addMods` on.
fn classpath_separator() -> char {
    if cfg!(windows) { ';' } else { ':' }
}

/// The value of `-Dfabric.addMods`: the supplied jars joined with
/// [`classpath_separator`], sorted and deduplicated so the value never depends
/// on argument order. Only paths from `jars` can appear (nothing is scanned
/// from disk), a path carrying the separator is dropped because the property
/// cannot express it, and the list stops at [`MAX_FABRIC_ADD_MODS`] entries or
/// [`MAX_FABRIC_ADD_MODS_BYTES`] bytes.
fn fabric_add_mods(jars: &[PathBuf]) -> Option<String> {
    let separator = classpath_separator();
    let mut paths: Vec<String> = jars
        .iter()
        .map(|jar| jar.to_string_lossy().into_owned())
        .filter(|path| !path.is_empty() && !path.contains(separator))
        .collect();
    paths.sort();
    paths.dedup();
    paths.truncate(MAX_FABRIC_ADD_MODS);
    let mut value = String::new();
    for path in paths {
        let separator_len = usize::from(!value.is_empty());
        if value.len() + separator_len + path.len() > MAX_FABRIC_ADD_MODS_BYTES {
            break;
        }
        if separator_len == 1 {
            value.push(separator);
        }
        value.push_str(&path);
    }
    (!value.is_empty()).then_some(value)
}

/// How many jars the property carries, for the deterministic log line. A
/// missing or empty property has none.
fn fabric_add_mods_count(value: Option<&str>) -> usize {
    value.map_or(0, |value| {
        value
            .split(classpath_separator())
            .filter(|path| !path.is_empty())
            .count()
    })
}

/// `fabric addMods: N jar(s)`, the one-line diagnostic for the hand-off.
fn fabric_add_mods_line(count: usize) -> String {
    format!("fabric addMods: {count} jar(s)")
}

/// The JVM options Fabric's developer properties need, in a stable order. Kept
/// as an argument list so a test can inspect the exact properties without
/// starting a JVM. `fabric.development` is opt-in, and `fabric.skipMcProvider`
/// is only forwarded when the environment already set it.
fn fabric_jvm_options(
    add_mods: Option<&str>,
    development: bool,
    skip_mc_provider: bool,
) -> Vec<String> {
    let mut options = Vec::new();
    if let Some(add_mods) = add_mods {
        options.push(format!("-D{}={add_mods}", FABRIC_ADD_MODS));
    }
    if development {
        options.push(format!("-D{}=true", FABRIC_DEVELOPMENT));
    }
    if skip_mc_provider {
        options.push(format!("-D{}=true", FABRIC_SKIP_MC_PROVIDER));
    }
    options
}

/// The production provider's default game version: Horizon's pinned vanilla
/// version. `--game-version` overrides it for a differently built game jar.
const DEFAULT_GAME_VERSION: &str = "26.3";

/// The Fabric properties a real Minecraft game provider reads before
/// `locateGame`. `fabric.gameJarPath` is the common jar; the side property is
/// what `GameProviderHelper.getEnvGameJar` consults.
const FABRIC_GAME_JAR_PATH: &str = "fabric.gameJarPath";
const FABRIC_GAME_JAR_PATH_CLIENT: &str = "fabric.gameJarPath.client";
const FABRIC_GAME_JAR_PATH_SERVER: &str = "fabric.gameJarPath.server";
const FABRIC_GAME_VERSION: &str = "fabric.gameVersion";

/// Upper bound for `--provider-report`, matching the FML report's bound.
const MAX_PROVIDER_REPORT_BYTES: usize = 64 * 1024;
const MAX_PROVIDER_REASON_CHARS: usize = 400;

/// The production-provider flags, removed from the jar list before anything is
/// resolved.
#[derive(Debug, Clone, PartialEq, Eq)]
struct GameProviderArgs {
    jars: Vec<PathBuf>,
    version: String,
}

fn take_game_provider_args(args: &mut Vec<String>) -> Result<GameProviderArgs, String> {
    let jars = take_all(args, "--game-jar")
        .into_iter()
        .map(PathBuf::from)
        .collect();
    let version = take(args, "--game-version").unwrap_or_else(|| DEFAULT_GAME_VERSION.to_owned());
    if version.trim().is_empty() {
        return Err("--game-version must not be empty".to_owned());
    }
    Ok(GameProviderArgs { jars, version })
}

/// The environment a provider run models: `--entry-kind client` is Fabric's
/// client side, everything else (including `main`) is the dedicated side.
fn client_side(entry_kind: &str) -> bool {
    matches!(entry_kind, "client" | "client_init")
}

/// The provider a run uses: the real Minecraft provider when a game jar is
/// supplied, otherwise the bounded reflection provider.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ProviderKind {
    Minecraft,
    Test,
}

impl ProviderKind {
    fn label(self) -> &'static str {
        match self {
            Self::Minecraft => "minecraft",
            Self::Test => "test",
        }
    }

    fn for_jars(jars: &[PathBuf]) -> Self {
        Self::for_count(jars.len())
    }

    fn for_count(count: usize) -> Self {
        if count == 0 {
            Self::Test
        } else {
            Self::Minecraft
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ProviderStatus {
    Ok,
    Fallback,
    NotRun,
}

/// The loader side selected for a provider run. `main` and lifecycle-only
/// probes use the server side, matching [`client_side`] and the server-first
/// bridge's authoritative role.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ProviderSide {
    Client,
    Server,
}

impl ProviderSide {
    fn for_entry_kind(entry_kind: &str) -> Self {
        if client_side(entry_kind) {
            Self::Client
        } else {
            Self::Server
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Client => "client",
            Self::Server => "server",
        }
    }
}

impl ProviderStatus {
    fn label(self) -> &'static str {
        match self {
            Self::Ok => "ok",
            Self::Fallback => "fallback",
            Self::NotRun => "not-run",
        }
    }
}

/// What the bridge reported after a real-loader bootstrap.
#[derive(Debug, Clone, PartialEq, Eq)]
enum ProviderOutcome {
    Production {
        mods: usize,
        freeze_reason: Option<String>,
        development: bool,
        /// Mod ids the loader discovered, sorted and bounded by the bridge.
        /// Empty when discovery was not requested.
        discovered_ids: Vec<String>,
        /// The bridge's bounded `classpath-unlock` outcome, only when the run
        /// asked for it. `None` keeps an unflagged run byte-identical.
        classpath_unlock: Option<String>,
        /// The bounded result of KnotClassLoaderInterface.initializeTransformers.
        knot_init: Option<String>,
        /// The bounded `--knot-launch` result: the Knot loader handed to the
        /// launcher and the class the transformer chain rewrote.
        knot_launch: Option<String>,
        /// The bounded `--mixin-apply-probe` result: the class loaded through
        /// Knot and the method that proved its mixin applied.
        mixin_apply: Option<String>,
        /// The bounded `--launch-game` result: started, an exit code, or the
        /// reason the launch did not start.
        launch_game: Option<String>,
    },
    Fallback {
        mods: usize,
        reason: String,
    },
    Test {
        mods: usize,
    },
}

impl ProviderOutcome {
    fn mods(&self) -> usize {
        match self {
            Self::Production { mods, .. } | Self::Fallback { mods, .. } | Self::Test { mods } => {
                *mods
            }
        }
    }
}

/// The `--provider-report` view: provider kind, selected side, supplied game
/// jars, version, status and (only on a fallback) the bounded reason.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ProviderReport {
    kind: ProviderKind,
    side: ProviderSide,
    game_jars: usize,
    game_version: String,
    status: ProviderStatus,
    fallback_reason: Option<String>,
    development: Option<bool>,
    freeze_reason: Option<String>,
    classpath_unlock: Option<String>,
    knot_init: Option<String>,
    knot_launch: Option<String>,
    mixin_apply: Option<String>,
    launch_game: Option<String>,
    loader_libs: Option<String>,
    remap: Option<String>,
    client_launch: Option<String>,
}

impl ProviderReport {
    fn not_run(jars: &[PathBuf], game_version: &str, side: ProviderSide) -> Self {
        Self {
            kind: ProviderKind::for_jars(jars),
            side,
            game_jars: jars.len(),
            game_version: game_version.to_owned(),
            status: ProviderStatus::NotRun,
            fallback_reason: None,
            development: None,
            freeze_reason: None,
            classpath_unlock: None,
            knot_init: None,
            knot_launch: None,
            mixin_apply: None,
            launch_game: None,
            loader_libs: None,
            remap: None,
            client_launch: None,
        }
    }

    /// Attach the `--classpath-unlock` outcome; `None` leaves the report as it
    /// was before the flag existed.
    fn with_classpath_unlock(mut self, value: Option<String>) -> Self {
        self.classpath_unlock = value.map(|value| bounded_classpath_unlock(&value));
        self
    }

    fn with_knot_init(mut self, value: Option<String>) -> Self {
        self.knot_init = value.map(|value| bounded_classpath_unlock(&value));
        self
    }

    /// Attach the `--knot-launch` outcome; `None` leaves the report unchanged.
    fn with_knot_launch(mut self, value: Option<String>) -> Self {
        self.knot_launch = value.map(|value| bounded_classpath_unlock(&value));
        self
    }

    /// Attach the `--mixin-apply-probe` outcome.
    fn with_mixin_apply(mut self, value: Option<String>) -> Self {
        self.mixin_apply = value.map(|value| bounded_classpath_unlock(&value));
        self
    }

    /// Attach the `--launch-game` outcome.
    fn with_launch_game(mut self, value: Option<String>) -> Self {
        self.launch_game = value.map(|value| bounded_classpath_unlock(&value));
        self
    }

    fn with_loader_libs(mut self, value: Option<String>) -> Self {
        self.loader_libs = value.map(|value| bounded_classpath_unlock(&value));
        self
    }

    fn with_remap(mut self, value: Option<String>) -> Self {
        self.remap = value;
        self
    }

    fn with_client_launch(mut self, value: Option<String>) -> Self {
        self.client_launch = value;
        self
    }

    fn from_outcome(
        outcome: &ProviderOutcome,
        game_jars: usize,
        game_version: &str,
        side: ProviderSide,
    ) -> Self {
        match outcome {
            ProviderOutcome::Production {
                development,
                freeze_reason,
                knot_init,
                knot_launch,
                mixin_apply,
                launch_game,
                ..
            } => Self {
                kind: ProviderKind::Minecraft,
                side,
                game_jars,
                game_version: game_version.to_owned(),
                status: ProviderStatus::Ok,
                fallback_reason: None,
                development: Some(*development),
                freeze_reason: freeze_reason.clone(),
                classpath_unlock: None,
                knot_init: knot_init.clone(),
                knot_launch: knot_launch.clone(),
                mixin_apply: mixin_apply.clone(),
                launch_game: launch_game.clone(),
                loader_libs: None,
                remap: None,
                client_launch: None,
            },
            ProviderOutcome::Fallback { reason, .. } => Self {
                kind: ProviderKind::Test,
                side,
                game_jars,
                game_version: game_version.to_owned(),
                status: ProviderStatus::Fallback,
                fallback_reason: Some(reason.clone()),
                development: None,
                freeze_reason: None,
                classpath_unlock: None,
                knot_init: None,
                knot_launch: None,
                mixin_apply: None,
                launch_game: None,
                loader_libs: None,
                remap: None,
                client_launch: None,
            },
            ProviderOutcome::Test { .. } => Self {
                kind: ProviderKind::Test,
                side,
                game_jars,
                game_version: game_version.to_owned(),
                status: ProviderStatus::Ok,
                fallback_reason: None,
                development: None,
                freeze_reason: None,
                classpath_unlock: None,
                knot_init: None,
                knot_launch: None,
                mixin_apply: None,
                launch_game: None,
                loader_libs: None,
                remap: None,
                client_launch: None,
            },
        }
    }

    fn text(&self) -> String {
        let mut lines = vec![
            format!("provider: {}", self.kind.label()),
            format!("side: {}", self.side.label()),
            format!("game jars: {}", self.game_jars),
            format!("game version: {}", self.game_version),
            format!("status: {}", self.status.label()),
        ];
        if let Some(reason) = &self.fallback_reason {
            lines.push(format!("fallback: {reason}"));
        }
        if let Some(development) = self.development {
            lines.push(format!("isDevelopment: {development}"));
        }
        if let Some(reason) = &self.freeze_reason {
            lines.push(format!("freeze: {reason}"));
        }
        if let Some(unlock) = &self.classpath_unlock {
            lines.push(classpath_unlock_line(unlock));
        }
        if let Some(init) = &self.knot_init {
            lines.push(knot_init_line(init));
        }
        if let Some(launch) = &self.knot_launch {
            lines.push(knot_launch_line(launch));
        }
        if let Some(apply) = &self.mixin_apply {
            lines.push(mixin_apply_line(apply));
        }
        if let Some(launch) = &self.launch_game {
            lines.push(launch_game_line(launch));
        }
        if let Some(loader_libs) = &self.loader_libs {
            lines.push(loader_libs.clone());
        }
        if let Some(remap) = &self.remap {
            lines.push(remap.clone());
        }
        if let Some(client) = &self.client_launch {
            lines.push(client.clone());
        }
        bound_text(&(lines.join("\n") + "\n"), MAX_PROVIDER_REPORT_BYTES)
    }

    fn json(&self) -> String {
        let text = serde_json::json!({
            "provider": self.kind.label(),
            "side": self.side.label(),
            "gameJars": self.game_jars,
            "gameVersion": self.game_version,
            "status": self.status.label(),
            "fallback": self.fallback_reason,
            "isDevelopment": self.development,
            "freeze": self.freeze_reason,
            "classpathUnlock": self.classpath_unlock,
            "knotInit": self.knot_init,
            "knotLaunch": self.knot_launch,
            "mixinApply": self.mixin_apply,
            "launchGame": self.launch_game,
            "loaderLibs": self.loader_libs,
            "remap": self.remap,
            "clientLaunch": self.client_launch,
        })
        .to_string();
        if text.len() <= MAX_PROVIDER_REPORT_BYTES {
            return text;
        }
        serde_json::json!({
            "provider": self.kind.label(),
            "side": self.side.label(),
            "gameJars": self.game_jars,
            "gameVersion": "",
            "status": self.status.label(),
            "fallback": "report truncated",
            "isDevelopment": self.development,
            "freeze": self.freeze_reason,
            "classpathUnlock": self.classpath_unlock,
            "knotInit": self.knot_init,
            "knotLaunch": self.knot_launch,
            "mixinApply": self.mixin_apply,
            "launchGame": self.launch_game,
            "loaderLibs": self.loader_libs,
            "remap": self.remap,
            "clientLaunch": self.client_launch,
        })
        .to_string()
    }
}

fn print_provider_report(report: &ProviderReport, json: bool) {
    if json {
        println!("{}", report.json());
    } else {
        print!("{}", report.text());
    }
}

/// The properties a production provider reads, in a stable order. Only the
/// first supplied jar can be a game jar to Fabric; every supplied jar still
/// reaches the classpath and the URLClassLoader in the bridge.
fn game_provider_jvm_options(jars: &[PathBuf], version: &str, client: bool) -> Vec<String> {
    let Some(first) = jars.first() else {
        return Vec::new();
    };
    let env_property = if client {
        FABRIC_GAME_JAR_PATH_CLIENT
    } else {
        FABRIC_GAME_JAR_PATH_SERVER
    };
    vec![
        format!("-D{}={}", FABRIC_GAME_JAR_PATH, first.display()),
        format!("-D{}={}", env_property, first.display()),
        format!("-D{}={}", FABRIC_GAME_VERSION, version),
    ]
}

/// The `--classpath-unlock` line's bound: one short stdout/report line.
const MAX_CLASSPATH_UNLOCK_CHARS: usize = 400;

/// One line for a provider failure: whitespace collapsed, capped, and never
/// empty, so a report always names something.
fn bounded_provider_reason(reason: &str) -> String {
    let collapsed = reason.split_whitespace().collect::<Vec<_>>().join(" ");
    if collapsed.is_empty() {
        return "unknown production provider failure".to_owned();
    }
    collapsed.chars().take(MAX_PROVIDER_REASON_CHARS).collect()
}

/// The `--classpath-unlock` outcome as one bounded, single-line value. Empty is
/// impossible: a missing result still says the unlock failed.
fn bounded_classpath_unlock(text: &str) -> String {
    let collapsed = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if collapsed.is_empty() {
        return "failed unknown".to_owned();
    }
    collapsed.chars().take(MAX_CLASSPATH_UNLOCK_CHARS).collect()
}

/// The unlock value for a real-loader run, or `None` when the flag was not
/// passed. A run that never reached the production provider says so instead of
/// claiming an unlock that did not happen.
fn classpath_unlock_value(requested: bool, outcome: &ProviderOutcome) -> Option<String> {
    if !requested {
        return None;
    }
    match outcome {
        ProviderOutcome::Production {
            classpath_unlock, ..
        } => Some(match classpath_unlock {
            Some(value) => bounded_classpath_unlock(value),
            None => "failed no classpath-unlock result".to_owned(),
        }),
        ProviderOutcome::Fallback { .. } => {
            Some("skipped (production game provider unavailable)".to_owned())
        }
        ProviderOutcome::Test { .. } => Some("skipped (no --game-jar)".to_owned()),
    }
}

/// `classpath-unlock: <value>`, the one line stdout and the report carry.
