/// The bridge returns `minecraft<TAB><mods><TAB><freeze><TAB><development><TAB><ids><TAB><unlock><TAB><knot-init><TAB><knot-launch><TAB><launch-game><TAB><mixin-apply>`
/// on success and `test<TAB><mods><TAB><reason>` after falling back. Fields
/// after the fifth were added one wave at a time, so the parser accepts every
/// shorter legacy shape.
fn parse_provider_outcome(text: &str) -> Result<ProviderOutcome, String> {
    let mut parts = text.splitn(10, '\t');
    let kind = parts.next().unwrap_or_default();
    let mods = parts
        .next()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .unwrap_or(0);
    match kind {
        "minecraft" => {
            let freeze = parts.next().unwrap_or_default();
            let development = parts.next().unwrap_or("false") == "true";
            // The ids field is absent only in the legacy two-field shape.
            let discovered_ids = parts
                .next()
                .map(|ids| {
                    ids.split(',')
                        .filter(|id| !id.is_empty())
                        .map(str::to_owned)
                        .collect()
                })
                .unwrap_or_default();
            // A run without the flag carries no unlock field.
            let classpath_unlock = parts
                .next()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(bounded_classpath_unlock);
            let knot_init = parts
                .next()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(bounded_classpath_unlock);
            let knot_launch = parts
                .next()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(bounded_classpath_unlock);
            let launch_game = parts
                .next()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(bounded_classpath_unlock);
            let mixin_apply = parts
                .next()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(bounded_classpath_unlock);
            Ok(ProviderOutcome::Production {
                mods,
                freeze_reason: (!freeze.is_empty()).then(|| bounded_provider_reason(freeze)),
                development,
                discovered_ids,
                classpath_unlock,
                knot_init,
                knot_launch,
                launch_game,
                mixin_apply,
            })
        }
        "test" => Ok(ProviderOutcome::Fallback {
            mods,
            reason: bounded_provider_reason(parts.next().unwrap_or("")),
        }),
        other => Err(format!(
            "production game provider returned an unknown result: {other}"
        )),
    }
}

/// Upper bound for one `remap:` or `client-launch:` stdout line.
const MAX_READINESS_LINE_CHARS: usize = 400;

/// Names mapping files without a flag, so a harness can point the probe at an
/// installation it owns instead of guessing where one lives.
const MAPPINGS_ENV: &str = "HORIZON_MAPPINGS";
const MAPPING_PATH_PROPERTY: &str = "horizon.mapping.path";

/// The game directory a launcher sets for a client run: the folder that holds
/// `versions/`, `assets/` and `libraries/`.
const CLIENT_HOME_ENV: &str = "HORIZON_MINECRAFT_HOME";

/// The namespace Fabric's loader reads a mapping tree in. Mod class names are
/// remapped out of the game's runtime namespace, so a tree without it cannot
/// feed `MappingConfiguration`.
const INTERMEDIARY_NAMESPACE: &str = "intermediary";

/// Bound on a mapping file read into memory. A real intermediary tree is a few
/// megabytes; anything far beyond that is not a mappings file worth parsing.
const MAX_MAPPING_BYTES: u64 = 64 * 1024 * 1024;

/// How far below a search root a mapping file may sit. A project-local Loom
/// cache keeps its tree at `projects/versions/<v>/source_mappings/<hash>.tiny`,
/// five levels down; nothing deeper is a mapping file we look for.
const MAPPING_SCAN_DEPTH: usize = 5;

/// A mapping tree in the shape Fabric's `MappingConfiguration` takes: one
/// source namespace (`intermediary`), one target namespace, and the number of
/// class and member names that actually change. An identity tree is rejected
/// rather than reported as a remap.
#[derive(Debug, Clone, PartialEq, Eq)]
struct RemapTree {
    source: String,
    target: String,
    /// Class mappings whose two names differ.
    classes: usize,
    /// Field and method mappings whose two names differ.
    members: usize,
}

impl RemapTree {
    fn line(&self) -> String {
        format!(
            "remap: ok {} entries ({} -> {})",
            self.classes, self.source, self.target
        )
    }
}

/// One line, whitespace collapsed and capped, for either readiness probe.
fn bounded_readiness_line(text: &str) -> String {
    let collapsed = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if collapsed.is_empty() {
        return "failed unknown".to_owned();
    }
    collapsed.chars().take(MAX_READINESS_LINE_CHARS).collect()
}

/// The bounded `remap:` line: a built tree names its source and target, and a
/// failure names the file or the search roots that were checked. A failure is
/// never dressed up as a success.
fn remap_report_line(tree: &Result<RemapTree, String>) -> String {
    match tree {
        Ok(tree) => bounded_readiness_line(&tree.line()),
        Err(reason) => bounded_readiness_line(&format!("remap: failed {reason}")),
    }
}

/// Whether a namespace name can be a class, field or method name. This is what
/// separates a tiny v2 class line from a comment line when a tree has only one
/// namespace, where both have the same field count.
fn is_namespaced_name(value: &str) -> bool {
    !value.is_empty() && !value.chars().any(char::is_whitespace)
}

/// Parse a tiny v1 or v2 mapping tree and keep the class and member pairs whose
/// intermediary and target names differ. The source namespace is
/// [`INTERMEDIARY_NAMESPACE`]; a tree without it, or one whose names never
/// change (an identity tree), is an error instead of a fake remap.
fn parse_mappings(text: &str) -> Result<RemapTree, String> {
    let text = text.strip_prefix('\u{feff}').unwrap_or(text);
    let mut lines = text.lines();
    let header = lines
        .next()
        .ok_or_else(|| "empty mapping file".to_owned())?
        .trim_end_matches('\r');
    let (namespaces, tiny_v2) = if let Some(rest) = header.strip_prefix("tiny\t") {
        let fields: Vec<&str> = rest.split('\t').collect();
        if fields.first() != Some(&"2") {
            return Err(format!(
                "unsupported tiny version {}",
                fields.first().copied().unwrap_or("?")
            ));
        }
        // `tiny 2 <patch> <namespace>...`
        let namespaces = fields.get(2..).unwrap_or_default();
        (namespaces.to_vec(), true)
    } else if let Some(rest) = header.strip_prefix("v1\t") {
        (rest.split('\t').collect::<Vec<_>>(), false)
    } else {
        return Err("not a tiny v1 or v2 mapping file".to_owned());
    };
    let source_index = namespaces
        .iter()
        .position(|namespace| *namespace == INTERMEDIARY_NAMESPACE)
        .ok_or_else(|| format!("no intermediary namespace (has {})", namespaces.join(", ")))?;
    let target_index = namespaces
        .iter()
        .position(|namespace| *namespace == "official")
        .or_else(|| {
            namespaces
                .iter()
                .position(|namespace| *namespace != INTERMEDIARY_NAMESPACE)
        })
        .ok_or_else(|| "no target namespace".to_owned())?;
    let target = namespaces[target_index].to_owned();
    let mut classes = 0;
    let mut members = 0;
    let mut unchanged = 0;
    for raw in lines {
        let line = raw.trim_end_matches('\r');
        if line.is_empty() {
            continue;
        }
        let indent = line.len() - line.trim_start_matches('\t').len();
        let body = &line[indent..];
        let mut fields = body.split('\t');
        let Some(kind) = fields.next() else {
            continue;
        };
        let rest: Vec<&str> = fields.collect();
        if tiny_v2 {
            match kind {
                "c" if indent == 0 => {
                    if rest.len() != namespaces.len()
                        || !rest.iter().all(|name| is_namespaced_name(name))
                    {
                        continue;
                    }
                    let from = rest[source_index];
                    let to = rest[target_index];
                    if from == to {
                        unchanged += 1;
                    } else if !from.is_empty() && !to.is_empty() {
                        classes += 1;
                    }
                }
                "f" | "m" if indent > 0 => {
                    // `<kind> <descriptor> <namespace name>...`
                    if rest.len() != namespaces.len() + 1 {
                        continue;
                    }
                    let names = &rest[1..];
                    if !names.iter().all(|name| is_namespaced_name(name)) {
                        continue;
                    }
                    let from = names[source_index];
                    let to = names[target_index];
                    if from == to {
                        unchanged += 1;
                    } else if !from.is_empty() && !to.is_empty() {
                        members += 1;
                    }
                }
                _ => {}
            }
        } else {
            match kind {
                "CLASS" => {
                    if rest.len() != namespaces.len() {
                        continue;
                    }
                    let from = rest[source_index];
                    let to = rest[target_index];
                    if from == to {
                        unchanged += 1;
                    } else if !from.is_empty() && !to.is_empty() {
                        classes += 1;
                    }
                }
                "FIELD" | "METHOD" => {
                    // `<kind> <owner> <descriptor> <namespace name>...`
                    if rest.len() != namespaces.len() + 2 {
                        continue;
                    }
                    let names = &rest[2..];
                    let from = names[source_index];
                    let to = names[target_index];
                    if from == to {
                        unchanged += 1;
                    } else if !from.is_empty() && !to.is_empty() {
                        members += 1;
                    }
                }
                _ => {}
            }
        }
    }
    if classes == 0 {
        if unchanged > 0 {
            return Err(format!(
                "identity tree ({unchanged} names unchanged, 0 remapped)"
            ));
        }
        return Err("no class entries".to_owned());
    }
    Ok(RemapTree {
        source: INTERMEDIARY_NAMESPACE.to_owned(),
        target,
        classes,
        members,
    })
}

/// Read a mappings file, accepting a tiny text file or a jar whose entry is
/// `mappings.tiny`. The read is bounded, so a huge or hostile file cannot take
/// the probe's memory with it.
fn read_mapping_text(path: &Path) -> Result<String, String> {
    let metadata = fs::metadata(path).map_err(|error| format!("{}: {error}", path.display()))?;
    if metadata.len() > MAX_MAPPING_BYTES {
        return Err(format!(
            "{}: larger than {MAX_MAPPING_BYTES} bytes",
            path.display()
        ));
    }
    let archive = matches!(
        path.extension().and_then(|extension| extension.to_str()),
        Some("jar" | "zip")
    );
    if archive {
        let file = File::open(path).map_err(|error| format!("{}: {error}", path.display()))?;
        let mut archive =
            zip::ZipArchive::new(file).map_err(|error| format!("{}: {error}", path.display()))?;
        for index in 0..archive.len() {
            let Ok(entry) = archive.by_index(index) else {
                continue;
            };
            let name = entry.name().to_ascii_lowercase();
            if !name.ends_with(".tiny") {
                continue;
            }
            let mut reader = entry.take(MAX_MAPPING_BYTES + 1);
            let mut bytes = Vec::new();
            reader
                .read_to_end(&mut bytes)
                .map_err(|error| format!("{}!{name}: {error}", path.display()))?;
            if bytes.len() as u64 > MAX_MAPPING_BYTES {
                return Err(format!(
                    "{}!{name}: larger than {MAX_MAPPING_BYTES}",
                    path.display()
                ));
            }
            return String::from_utf8(bytes)
                .map_err(|_| format!("{}!{name}: not UTF-8", path.display()));
        }
        return Err(format!("{}: no .tiny mappings entry", path.display()));
    }
    let bytes = fs::read(path).map_err(|error| format!("{}: {error}", path.display()))?;
    String::from_utf8(bytes).map_err(|_| format!("{}: not UTF-8", path.display()))
}

/// Whether a name looks like a mappings file. A `.tiny` always is one; a jar
/// only when its name says it carries intermediary, yarn or mappings.
fn is_mapping_file_name(path: &Path) -> bool {
    match path.extension().and_then(|extension| extension.to_str()) {
        Some("tiny") => true,
        Some("jar" | "zip") => {
            let name = path
                .file_name()
                .unwrap_or_default()
                .to_string_lossy()
                .to_ascii_lowercase();
            name.contains("intermediary") || name.contains("mapping") || name.contains("yarn")
        }
        _ => false,
    }
}

/// Collect mapping files below `dir`, sorted so the first candidate is stable.
/// The bulk cargo directories (asset objects, remapped jars, extracted natives)
/// are skipped: they can hold millions of files and never hold a mapping tree.
fn mapping_files_under(dir: &Path, depth: usize, out: &mut Vec<PathBuf>) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    let mut entries: Vec<_> = entries.filter_map(Result::ok).collect();
    entries.sort_by_key(|entry| entry.file_name());
    for entry in entries {
        let path = entry.path();
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        if file_type.is_dir() {
            if depth == 0 {
                continue;
            }
            let name = entry.file_name().to_string_lossy().into_owned();
            if matches!(
                name.as_str(),
                "objects" | "remappedJars" | "remapped_mods" | "natives" | "minecraftMaven"
            ) {
                continue;
            }
            mapping_files_under(&path, depth - 1, out);
        } else if is_mapping_file_name(&path) {
            out.push(path);
        }
    }
}

/// The roots checked when no `--mappings` path is given, in a stable order.
/// Each carries the depth that still reaches a real file: a Loom project cache
/// nests its tree five levels down, the others never go that deep.
fn mapping_search_roots() -> Vec<(PathBuf, usize)> {
    let mut roots = vec![(PathBuf::from("/tmp/opencode"), 3)];
    if let Some(home) = std::env::var_os("HOME")
        .map(PathBuf::from)
        .filter(|home| !home.as_os_str().is_empty())
    {
        roots.push((home.join(".fabric"), 3));
        roots.push((home.join(".minecraft"), 3));
        roots.push((home.join(".gradle/caches"), 3));
        roots.push((home.join(".gradle/caches/fabric-loom"), 3));
        roots.push((
            home.join(".gradle/caches/modules-2/files-2.1/net.fabricmc"),
            4,
        ));
        roots.push((home.join(".gradle/loom-cache"), MAPPING_SCAN_DEPTH));
    }
    roots
}

/// Build a real remap tree from the files the caller named, then from
/// `HORIZON_MAPPINGS`, then from the standard roots. Every candidate is parsed;
/// if none yields an intermediary tree the first concrete failure is reported
/// with the roots that were checked, so a missing installation is visible
/// rather than silently treated as identity.
fn resolve_remap_tree(explicit: &[PathBuf]) -> Result<RemapTree, String> {
    let mut paths: Vec<PathBuf> = explicit.to_vec();
    if let Some(value) = std::env::var_os(MAPPINGS_ENV) {
        paths.extend(std::env::split_paths(&value));
    }
    let mut candidates = Vec::new();
    let mut checked = Vec::new();
    if paths.is_empty() {
        for (root, depth) in mapping_search_roots() {
            checked.push(root.display().to_string());
            if root.is_dir() {
                mapping_files_under(&root, depth, &mut candidates);
            }
        }
        if candidates.is_empty() {
            return Err(format!("no mappings file; checked {}", checked.join(", ")));
        }
    } else {
        for path in &paths {
            if path.is_dir() {
                let before = candidates.len();
                mapping_files_under(path, MAPPING_SCAN_DEPTH, &mut candidates);
                if candidates.len() == before {
                    return Err(format!("no mapping file under {}", path.display()));
                }
            } else if path.is_file() {
                candidates.push(path.clone());
            } else {
                return Err(format!("no such mappings path: {}", path.display()));
            }
        }
    }
    let mut first_error = None;
    for candidate in candidates {
        let parsed = read_mapping_text(&candidate).and_then(|text| parse_mappings(&text));
        match parsed {
            Ok(tree) => return Ok(tree),
            Err(error) => {
                first_error.get_or_insert_with(|| format!("{}: {error}", candidate.display()));
            }
        }
    }
    Err(first_error.unwrap_or_else(|| "no mappings file".to_owned()))
}

/// Select the concrete tiny file to hand to Fabric's MappingReader. Archives
/// are reportable but are not passed to the loader because MappingReader reads
/// a filesystem mapping stream; callers can point at their extracted `.tiny`.
fn mapping_loader_path(explicit: &[PathBuf]) -> Option<PathBuf> {
    let mut candidates = explicit.to_vec();
    if let Some(value) = std::env::var_os(MAPPINGS_ENV) {
        candidates.extend(std::env::split_paths(&value));
    }
    if candidates.is_empty() {
        for (root, depth) in mapping_search_roots() {
            let mut found = Vec::new();
            mapping_files_under(&root, depth, &mut found);
            candidates.extend(found);
        }
    }
    candidates.into_iter().find(|path| {
        path.is_file()
            && path.extension().and_then(|value| value.to_str()) == Some("tiny")
            && read_mapping_text(path)
                .and_then(|text| parse_mappings(&text))
                .is_ok()
    })
}

/// What a client launch still needs from the local install. A launcher extracts
/// natives from the `libraries` jars, so an extracted directory and the jars
/// themselves both count as present.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ClientReadiness {
    missing: Vec<String>,
}

impl ClientReadiness {
    fn detect(home: Option<&Path>, version: &str, game_jars: &[PathBuf]) -> Self {
        let mut missing = Vec::new();
        if let Some(game_jar) = game_jars.first() {
            if !game_jar.is_file() {
                missing.push(game_jar.display().to_string());
            }
        }
        let home = home
            .map(Path::to_path_buf)
            .or_else(|| std::env::var_os(CLIENT_HOME_ENV).map(PathBuf::from))
            .or_else(|| {
                game_jars
                    .first()
                    .and_then(|jar| client_home_from_jar(jar, version))
            });
        let Some(home) = home else {
            if game_jars.is_empty() {
                missing.push(format!(
                    "no client home (pass --client-home <dir> or set {CLIENT_HOME_ENV})"
                ));
            } else {
                missing.push(format!(
                    "no client home for --game-jar (pass --client-home <dir> or set {CLIENT_HOME_ENV})"
                ));
            }
            return Self { missing };
        };
        if game_jars.is_empty() {
            let game_jar = home
                .join("versions")
                .join(version)
                .join(format!("{version}.jar"));
            if !game_jar.is_file() {
                missing.push(game_jar.display().to_string());
            }
        }
        if let Err(label) = client_assets_index(&home, version) {
            missing.push(label);
        }
        if let Some(label) = client_natives_missing(&home, version) {
            missing.push(label);
        }
        Self { missing }
    }

    fn ready(&self) -> bool {
        self.missing.is_empty()
    }

    fn line(&self) -> String {
        if self.ready() {
            return "client-launch: ready".to_owned();
        }
        bounded_readiness_line(&format!(
            "client-launch: needs assets ({})",
            self.missing.join(", ")
        ))
    }
}

fn client_home_from_jar(jar: &Path, version: &str) -> Option<PathBuf> {
    let file = jar.file_name()?.to_str()?;
    if file != format!("{version}.jar") {
        return None;
    }
    let version_dir = jar.parent()?;
    if version_dir.file_name()?.to_str()? != version {
        return None;
    }
    let versions = version_dir.parent()?;
    if versions.file_name()?.to_str()? != "versions" {
        return None;
    }
    versions.parent().map(Path::to_path_buf)
}

/// The asset index the version json names, falling back to the version id. A
/// failure returns the exact path the client launch still needs.
fn client_assets_index(home: &Path, version: &str) -> Result<PathBuf, String> {
    let version_json = home
        .join("versions")
        .join(version)
        .join(format!("{version}.json"));
    let id = fs::read_to_string(&version_json)
        .ok()
        .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok())
        .and_then(|value| {
            value
                .get("assetIndex")?
                .get("id")?
                .as_str()
                .map(str::to_owned)
        })
        .unwrap_or_else(|| version.to_owned());
    let path = home
        .join("assets")
        .join("indexes")
        .join(format!("{id}.json"));
    if path.is_file() {
        Ok(path)
    } else {
        Err(path.display().to_string())
    }
}

/// The OS token LWJGL's native jars carry (`natives-linux` and friends).
fn native_os_token() -> &'static str {
    match std::env::consts::OS {
        "windows" => "windows",
        "macos" => "macos",
        _ => "linux",
    }
}

fn dir_non_empty(dir: &Path) -> bool {
    fs::read_dir(dir)
        .map(|mut entries| entries.next().is_some())
        .unwrap_or(false)
}

/// Whether some file below `dir` (to `depth`) has `token` in its name.
fn any_file_under(dir: &Path, depth: usize, token: &str) -> bool {
    let Ok(entries) = fs::read_dir(dir) else {
        return false;
    };
    for entry in entries.filter_map(Result::ok) {
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        if file_type.is_dir() {
            if depth > 0 && any_file_under(&entry.path(), depth - 1, token) {
                return true;
            }
        } else if entry
            .file_name()
            .to_string_lossy()
            .to_ascii_lowercase()
            .contains(token)
        {
            return true;
        }
    }
    false
}

/// Extracted natives (what a launcher makes at start) or the native jars in
/// `libraries` (what it extracts them from).
fn client_natives_missing(home: &Path, version: &str) -> Option<String> {
    if [
        home.join("versions").join(version).join("natives"),
        home.join("natives"),
    ]
    .iter()
    .any(|dir| dir_non_empty(dir))
    {
        return None;
    }
    let token = format!("natives-{}", native_os_token());
    if any_file_under(&home.join("libraries"), 6, &token) {
        None
    } else {
        Some(home.join("natives").display().to_string())
    }
}

/// A Java `String[]` from paths the user supplied.
fn java_string_array<'local>(
    env: &mut JNIEnv<'local>,
    values: &[String],
) -> Result<JObjectArray<'local>, String> {
    let length = i32::try_from(values.len()).map_err(|_| "too many game jars".to_owned())?;
    let array = env
        .new_object_array(length, "java/lang/String", JObject::null())
        .map_err(|error| format!("game jars: {error}"))?;
    for (index, value) in values.iter().enumerate() {
        let text = env
            .new_string(value)
            .map_err(|error| format!("game jar path: {error}"))?;
        env.set_object_array_element(&array, index as i32, JObject::from(text))
            .map_err(|error| format!("game jar path: {error}"))?;
    }
    Ok(array)
}

fn java_string_value(env: &mut JNIEnv, value: &JObject) -> Result<String, String> {
    if value.is_null() {
        return Err("production game provider returned null".to_owned());
    }
    let text = env
        .get_string((value).into())
        .map_err(|error| format!("production game provider result: {error}"))?;
    Ok(text.to_string_lossy().into_owned())
}

/// The launcher-side JVM option strings the environment already carries. Those
/// three variables are the only way a system property can be seeded before the
/// JVM starts, which is what "already set in the environment" means here.
fn fabric_environment_options() -> Vec<String> {
    ["JAVA_TOOL_OPTIONS", "_JAVA_OPTIONS", "JDK_JAVA_OPTIONS"]
        .iter()
        .filter_map(|name| std::env::var(name).ok())
        .collect()
}

/// Whether the environment already asks Fabric to skip its Minecraft provider.
/// The probe never invents it: a run only forwards what a launcher put there.
fn skip_mc_provider_requested(options: &[String]) -> bool {
    options
        .iter()
        .any(|option| option.contains(FABRIC_SKIP_MC_PROVIDER))
}

/// `System.getProperty(name)`, or `None` when the JVM does not have it. Read
/// after the JVM started, so this is diagnostics and never a failure.
fn jvm_property(env: &mut JNIEnv, name: &str) -> Option<String> {
    let value = system_property(env, name);
    // A failed lookup must not leave a throwable pending for the entrypoints.
    if value.is_none() {
        let _ = env.exception_clear();
    }
    value
}

/// The raw `System.getProperty` call behind [`jvm_property`].
fn system_property(env: &mut JNIEnv, name: &str) -> Option<String> {
    let system = env.find_class("java/lang/System").ok()?;
    let key = env.new_string(name).ok()?;
    let key = JObject::from(key);
    let value = env
        .call_static_method(
            &system,
            "getProperty",
            "(Ljava/lang/String;)Ljava/lang/String;",
            &[JValue::Object(&key)],
        )
        .ok()?
        .l()
        .ok()?;
    if value.is_null() {
        return None;
    }
    let text = env.get_string((&value).into()).ok()?;
    Some(text.to_string_lossy().into_owned())
}

/// The `fabric addMods` diagnostic, read back from the started JVM. A property
/// that did not survive reports 0 jars instead of failing the probe.
fn report_fabric_add_mods(env: &mut JNIEnv) -> String {
    let value = jvm_property(env, FABRIC_ADD_MODS);
    fabric_add_mods_line(fabric_add_mods_count(value.as_deref()))
}

/// Give Fabric Loader the two paths it normally receives from its launcher.
/// The embedded runner does not execute Fabric's full game provider, so the
/// singleton's private fields would otherwise remain null and any client mod
/// touching `FabricLoader#getConfigDir()` would panic. A missing loader jar is
/// fine: NeoForge and direct entrypoint probes do not have this class.
fn prepare_fabric_loader(env: &mut JNIEnv, root: &Path) -> Result<(), String> {
    let loader = match env.find_class("net/fabricmc/loader/impl/FabricLoaderImpl") {
        Ok(class) => class,
        Err(_) => {
            let _ = env.exception_clear();
            return Ok(());
        }
    };
    let game_dir = root.join("game");
    let config_dir = root.join("config");
    fs::create_dir_all(&game_dir).map_err(|e| format!("{}: {e}", game_dir.display()))?;
    fs::create_dir_all(&config_dir).map_err(|e| format!("{}: {e}", config_dir.display()))?;
    let instance = env
        .get_static_field(
            &loader,
            "INSTANCE",
            "Lnet/fabricmc/loader/impl/FabricLoaderImpl;",
        )
        .map_err(|e| format!("Fabric Loader INSTANCE: {e}"))?
        .l()
        .map_err(|e| format!("Fabric Loader INSTANCE value: {e}"))?;
    set_loader_path(env, &loader, &instance, "gameDir", &game_dir)?;
    set_loader_path(env, &loader, &instance, "configDir", &config_dir)?;
    Ok(())
}

fn set_loader_path(
    env: &mut JNIEnv,
    loader: &JObject,
    instance: &JObject,
    field_name: &str,
    path: &Path,
) -> Result<(), String> {
    let name = env
        .new_string(field_name)
        .map_err(|e| format!("Fabric Loader field name: {e}"))?;
    let name = JObject::from(name);
    let field = env
        .call_method(
            loader,
            "getDeclaredField",
            "(Ljava/lang/String;)Ljava/lang/reflect/Field;",
            &[JValue::Object(&name)],
        )
        .map_err(|e| format!("Fabric Loader field {field_name}: {e}"))?
        .l()
        .map_err(|e| format!("Fabric Loader field {field_name} value: {e}"))?;
    env.call_method(&field, "setAccessible", "(Z)V", &[JValue::Bool(1)])
        .map_err(|e| format!("Fabric Loader field {field_name} access: {e}"))?;
    let path_text = env
        .new_string(path.to_string_lossy())
        .map_err(|e| format!("Fabric Loader path {field_name}: {e}"))?;
    let path_text = JObject::from(path_text);
    let file_class = env
        .find_class("java/io/File")
        .map_err(|e| format!("java.io.File: {e}"))?;
    let file = env
        .new_object(
            &file_class,
            "(Ljava/lang/String;)V",
            &[JValue::Object(&path_text)],
        )
        .map_err(|e| format!("java.io.File {field_name}: {e}"))?;
    let value = env
        .call_method(&file, "toPath", "()Ljava/nio/file/Path;", &[])
        .map_err(|e| format!("Fabric Loader path {field_name}: {e}"))?
        .l()
        .map_err(|e| format!("Fabric Loader path {field_name} value: {e}"))?;
    env.call_method(
        &field,
        "set",
        "(Ljava/lang/Object;Ljava/lang/Object;)V",
        &[JValue::Object(instance), JValue::Object(&value)],
    )
    .map_err(|e| format!("Fabric Loader field {field_name} set: {e}"))?;
    Ok(())
}

fn initializer_for_kind(kind: &str) -> Result<(&'static str, &'static str), String> {
    match kind {
        "main" | "init" => Ok(("onInitialize", "onInitialize")),
        "client" | "client_init" => Ok(("onInitializeClient", "onInitializeClient")),
        "server" | "server_init" => Ok(("onInitializeServer", "onInitializeServer")),
        "preLaunch" | "prelaunch" => Ok(("onPreLaunch", "onPreLaunch")),
        other => Err(format!(
            "invalid --entry-kind {other}; expected main, client, server, preLaunch, neoforge, or datagen"
        )),
    }
}

/// Prints the Java exception (with its chain), and says where it happened.
fn describe(
    env: &mut JNIEnv,
    stage: &str,
    entry: &str,
    error: jni::errors::Error,
) -> Result<(), String> {
    Err(describe_error(env, stage, entry, error))
}

/// The message [`describe`] reports, for a caller that keeps running.
fn describe_error(env: &mut JNIEnv, stage: &str, entry: &str, error: jni::errors::Error) -> String {
    let fallback = (error.to_string() == "Java exception was thrown")
        .then(|| exception_fallback(env))
        .flatten();
    let _ = env.exception_describe();
    let _ = env.exception_clear();
    if let Some(message) = fallback {
        return format!("{stage} {entry}: {message}");
    }
    format!("{stage} {entry}: {error}")
}

/// The class name of the throwable the JVM left pending, without clearing it.
/// The caller decides whether it is a link failure or gets described.
fn pending_throwable_class(env: &mut JNIEnv) -> Option<String> {
    let throwable = env.exception_occurred().ok()?;
    let class = env.get_object_class(&throwable).ok()?;
    let name = env
        .call_method(&class, "getName", "()Ljava/lang/String;", &[])
        .ok()?
        .l()
        .ok()?;
    let name = env.get_string((&name).into()).ok()?;
    Some(name.to_string_lossy().into_owned())
}

/// Turn the exceptions that mean "the native façade cannot handle this" into
/// an explicit JVM fallback diagnostic. Dynamic classpath/resource lookups
/// stay on HotSpot, so a mod can tell this is a deliberate fallback rather
/// than an opaque entrypoint failure.
fn exception_fallback(env: &mut JNIEnv) -> Option<String> {
    let name = pending_throwable_class(env)?;
    let throwable = env.exception_occurred().ok()?;
    let message = env
        .call_method(&throwable, "getMessage", "()Ljava/lang/String;", &[])
        .ok()
        .and_then(|value| value.l().ok())
        .and_then(|value| {
            let text = env.get_string((&value).into()).ok()?;
            Some(text.to_string_lossy().into_owned())
        });
    let detail = message.filter(|value| !value.is_empty());
    fallback_label(&name, detail.as_deref())
}

fn fallback_label(class: &str, detail: Option<&str>) -> Option<String> {
    match class {
        "java.lang.UnsupportedOperationException" | "java.lang.SecurityException" => Some(format!(
            "JVM fallback selected for unsupported native call{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.ClassNotFoundException" | "java.lang.NoClassDefFoundError" => Some(format!(
            "JVM fallback selected for dynamic classpath lookup{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.NoSuchMethodError"
        | "java.lang.NoSuchFieldError"
        | "java.lang.NoSuchMethodException"
        | "java.lang.NoSuchFieldException"
        | "java.lang.AbstractMethodError"
        | "java.lang.IncompatibleClassChangeError" => Some(format!(
            "JVM fallback selected for missing façade member{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.ExceptionInInitializerError" | "java.lang.LinkageError" => Some(format!(
            "JVM fallback selected for static initialization failure{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.UnsatisfiedLinkError" => Some(format!(
            "JVM fallback selected for native linkage failure{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.VerifyError"
        | "java.lang.ClassFormatError"
        | "java.lang.BootstrapMethodError"
        | "java.lang.IllegalAccessError"
        | "java.lang.InstantiationError" => Some(format!(
            "JVM fallback selected for runtime linkage failure{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        _ => None,
    }
}

const FML_PROBE_SOURCE: &str = r#"
package horizon;

import java.nio.file.*;
import java.util.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.fml.ModLoader;
import net.neoforged.fml.loading.FMLLoader;
import net.neoforged.fml.loading.LoadingModList;
import net.neoforged.fml.startup.StartupArgs;

public final class FmlProbe {
  public static void main(String[] args) throws Exception {
    List<String> program = new ArrayList<>();
    for (String name : new String[]{"mcVersion", "neoForgeVersion", "neoFormVersion"}) {
      String value = System.getProperty("horizon.fml." + name);
      if (value != null) { program.add("--fml." + name); program.add(value); }
    }
    StartupArgs startup = new StartupArgs(Paths.get(System.getProperty("user.dir")), true,
        Dist.DEDICATED_SERVER, true, program.toArray(new String[0]), Set.of(), List.of(),
        ClassLoader.getSystemClassLoader());
    FMLLoader loader = FMLLoader.create(startup);
    LoadingModList list = loader.getLoadingModList();
    System.out.println("mods=" + list.getMods().size());
    for (var mod : list.getMods()) {
      String version = versionOf(mod);
      System.out.println("mod=" + mod.getModId() + (version.isEmpty() ? "" : "\t" + version));
    }
    // Discovery is the whole listing probe: no game bootstrap and no mod
    // entrypoint runs when the child is started with `--list`.
    if (args.length > 0 && args[0].equals("--list")) return;
    ClassLoader game = loader.getGameLayer().findLoader("minecraft");
    Class<?> constants = Class.forName("net.minecraft.SharedConstants", true, game);
    constants.getMethod("tryDetectVersion").invoke(null);
    Class<?> bootstrap = Class.forName("net.minecraft.server.Bootstrap", true, game);
    bootstrap.getMethod("bootStrap").invoke(null);
    ModLoader.gatherAndInitializeMods(Runnable::run, Runnable::run, () -> {});
    System.out.println("initialized");
  }

  private static String versionOf(Object mod) {
    for (String name : new String[]{"getVersionString", "getVersion"}) {
      try {
        Object value = mod.getClass().getMethod(name).invoke(mod);
        if (value != null) {
          String text = value.toString();
          if (!text.isEmpty()) return text;
        }
      } catch (ReflectiveOperationException ignored) {
        // Try the next accessor, then report no version.
      }
    }
    return "";
  }
}
"#;

const MAX_FML_MODS: usize = 512;
const MAX_FML_OUTPUT_BYTES: usize = 64 * 1024;
const MAX_FML_STDERR_BYTES: usize = 8 * 1024;

/// The full run, a discovery-only listing, or a report over the same output.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FmlMode {
    Run,
    List,
    Report,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FmlMod {
    id: String,
    version: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FmlReport {
    status: &'static str,
    server: String,
    jars: usize,
    mods: Vec<FmlMod>,
    initialized: bool,
    error: Option<String>,
}

impl FmlReport {
    fn text(&self) -> String {
        let mut lines = vec![
            format!("status: {}", self.status),
            format!("server: {}", self.server),
            format!("jars: {}", self.jars),
            format!("mods: {}", self.mods.len()),
            format!("initialized: {}", self.initialized),
        ];
        lines.extend(fml_list_lines(&self.mods));
        lines.extend(self.error.iter().map(|error| format!("error: {error}")));
        bound_text(&(lines.join("\n") + "\n"), MAX_FML_OUTPUT_BYTES)
    }

    fn json(&self) -> String {
        let mods: Vec<_> = self
            .mods
            .iter()
            .map(|m| serde_json::json!({"id": m.id, "version": m.version.as_deref()}))
            .collect();
        let text = serde_json::json!({
            "status": self.status, "server": self.server, "jars": self.jars,
            "mods": mods, "initialized": self.initialized, "error": self.error,
        })
        .to_string();
        if text.len() <= MAX_FML_OUTPUT_BYTES {
            return text;
        }
        // Keep a hostile path or id under the bound without corrupting JSON.
        serde_json::json!({
            "status": self.status, "server": "", "jars": self.jars,
            "mods": [], "initialized": self.initialized, "error": "report truncated",
        })
        .to_string()
    }
}

/// `id<TAB>version`, or the id when FML exposes no version.
fn fml_list_lines(mods: &[FmlMod]) -> Vec<String> {
    mods.iter()
        .map(|m| {
            m.version
                .as_ref()
                .map_or_else(|| m.id.clone(), |version| format!("{}\t{version}", m.id))
        })
        .collect()
}

/// The child probe's `mod=<id>` lines; `mods=N` and diagnostics are ignored.
fn parse_fml_mods(stdout: &str) -> Vec<FmlMod> {
    let mut mods: Vec<FmlMod> = stdout
        .lines()
        .filter_map(|line| {
            let entry = line.strip_prefix("mod=")?;
            let (id, version) = entry
                .split_once('\t')
                .map_or((entry, None), |(id, version)| (id, Some(version)));
            let id = id.trim();
            if id.is_empty() {
                return None;
            }
            let version = version
                .map(str::trim)
                .filter(|version| !version.is_empty())
                .map(str::to_owned);
            Some(FmlMod {
                id: id.to_owned(),
                version,
            })
        })
        .collect();
    mods.sort_by(|a, b| a.id.cmp(&b.id).then_with(|| a.version.cmp(&b.version)));
    mods.dedup();
    mods.truncate(MAX_FML_MODS);
    mods
}

fn first_fml_error_line(stderr: &str, stdout: &str) -> String {
    let mut fallback = None;
    for line in stderr.lines().chain(stdout.lines()).map(str::trim) {
        if line.is_empty() {
            continue;
        }
        fallback.get_or_insert(line);
        let lower = line.to_ascii_lowercase();
        if [
            "exception",
            "error",
            "failed",
            "could not",
            "caused by",
            "unable to",
        ]
        .iter()
        .any(|needle| lower.contains(needle))
        {
            return line.chars().take(400).collect();
        }
    }
    fallback.unwrap_or("no output").chars().take(400).collect()
}

/// Keep the first `limit` bytes, on a char boundary.
fn bound_text(text: &str, limit: usize) -> String {
    const MARKER: &str = "\n...(truncated)\n";
    if text.len() <= limit {
        return text.to_owned();
    }
    let mut end = limit.saturating_sub(MARKER.len());
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}{MARKER}", &text[..end])
}

// ---- Startup measurement (`--measure`) -----------------------------------
//
// The design page's performance budget (`docs/java-mod-compat.md`) sets a JVM
// start time and a base memory figure, and phase 1 replaces them with numbers.
// This is how a number is taken: the probe runs one representative fixture as
// a *child* process (the embedded JVM in this process cannot be timed from
// outside), and reports wall time to JVM-up and to the end, the child's CPU
// time, and its peak RSS where the OS keeps one. The same run is what proves a
// fixture is bounded: every sample is one child under one deadline, and a
// sample that fails or is killed fails the command instead of reporting a
// number for something that did not finish.

/// The measurement's own defaults. A fixture is expected to finish far inside
/// the timeout; one that does not is killed with its whole process group.
const DEFAULT_MEASURE_TIMEOUT: f64 = 120.0;
const DEFAULT_MEASURE_SAMPLE_MS: u64 = 5;
const DEFAULT_MEASURE_REPEAT: usize = 1;
const MAX_MEASURE_REPEAT: usize = 20;
const MAX_MEASURE_TIMEOUT_SECS: f64 = 86_400.0;
/// The sampler keeps `VmHWM`/`VmRSS` in KiB; a JVM larger than this is not a
/// measurement, it is a runaway.
const MAX_MEASURE_RSS_KIB: u64 = 1 << 26;

/// What a measured child receives instead of `--measure`: it strips the flag
/// and runs normally, so measuring twice in one process cannot happen.
const RECURSIVE_MEASURE_FLAG: &str = "--measure-recursive";
/// How deep in a measurement chain this process is; the spawn path refuses to
/// go past [`MAX_MEASURE_DEPTH`].
const MEASURE_RECURSION_ENV: &str = "HORIZON_JVM_MEASURE_DEPTH";
const MAX_MEASURE_DEPTH: u32 = 3;

/// The probe's own line once the JVM exists, which is where "startup" ends. A
/// measurement without this line has no startup figure to report.
const JVM_UP_MARKER: &str = "jvm up:";

/// The `--measure*` flags, removed from the jar list before anything is resolved.
#[derive(Debug, Clone, Copy, PartialEq)]
struct MeasureArgs {
    timeout_secs: f64,
    sample_ms: u64,
    repeat: usize,
}

/// Parse and remove `--measure [--measure-timeout <secs>] [--measure-sample-ms
/// <ms>] [--measure-repeat <n>]`. Without `--measure`, the tuning flags are an
/// error: silently ignoring them would measure nothing and say so.
fn take_measure_args(args: &mut Vec<String>) -> Result<Option<MeasureArgs>, String> {
    let enabled = take_flag(args, &["--measure"]);
    // `--flag=value` is the other spelling this tool's neighbours accept.
    let mut timeout = None;
    let mut sample_ms = None;
    let mut repeat = None;
    let mut plain = Vec::with_capacity(args.len());
    {
        let mut iter = std::mem::take(args).into_iter();
        while let Some(arg) = iter.next() {
            let (name, inline) = arg.split_once('=').unwrap_or((&arg, ""));
            let slot = match name {
                "--measure-timeout" => &mut timeout,
                "--measure-sample-ms" => &mut sample_ms,
                "--measure-repeat" => &mut repeat,
                _ => {
                    plain.push(arg);
                    continue;
                }
            };
            let value = if inline.is_empty() {
                iter.next().ok_or_else(|| format!("{name} needs a value"))?
            } else {
                inline.to_owned()
            };
            *slot = Some(value);
        }
    }
    *args = plain;
    if !enabled {
        if timeout.is_some() || sample_ms.is_some() || repeat.is_some() {
            return Err(
                "--measure-timeout/--measure-sample-ms/--measure-repeat need --measure".into(),
            );
        }
        return Ok(None);
    }
    let timeout_secs = match timeout {
        Some(value) => value
            .parse::<f64>()
            .ok()
            .filter(|value| value.is_finite() && *value > 0.0 && *value <= MAX_MEASURE_TIMEOUT_SECS)
            .ok_or_else(|| {
                format!("--measure-timeout: {value} is not a positive number of seconds")
            })?,
        None => DEFAULT_MEASURE_TIMEOUT,
    };
    let sample_ms = match sample_ms {
        Some(value) => value
            .parse::<u64>()
            .ok()
            .filter(|value| *value > 0)
            .ok_or_else(|| {
                format!("--measure-sample-ms: {value} is not a positive whole number")
            })?,
        None => DEFAULT_MEASURE_SAMPLE_MS,
    };
    let repeat = match repeat {
        Some(value) => value
            .parse::<usize>()
            .ok()
            .filter(|value| (1..=MAX_MEASURE_REPEAT).contains(value))
            .ok_or_else(|| {
                format!("--measure-repeat: {value} is not between 1 and {MAX_MEASURE_REPEAT}")
            })?,
        None => DEFAULT_MEASURE_REPEAT,
    };
    Ok(Some(MeasureArgs {
        timeout_secs,
        sample_ms,
        repeat,
    }))
}

/// The argv a measured child receives: this probe's own invocation with the
/// measurement flag replaced by its recursive spelling and the tuning flags
/// removed *with their values*, so the child runs this probe normally.
fn measure_child_args(argv: &[OsString]) -> Vec<OsString> {
    let mut child = Vec::with_capacity(argv.len());
    let mut iter = argv.iter();
    while let Some(arg) = iter.next() {
        match arg.to_str() {
            Some("--measure") => child.push(OsString::from(RECURSIVE_MEASURE_FLAG)),
            Some(flag)
                if matches!(
                    flag.split_once('=').map_or(flag, |(name, _)| name),
                    "--measure-timeout" | "--measure-sample-ms" | "--measure-repeat"
                ) && !flag.contains('=') =>
            {
                // The value is the next argument (the parser above required it).
                let _ = iter.next();
            }
            Some(flag)
                if matches!(
                    flag.split_once('=').map_or(flag, |(name, _)| name),
                    "--measure-timeout" | "--measure-sample-ms" | "--measure-repeat"
                ) => {}
            _ => child.push(arg.clone()),
        }
    }
    child
}

/// The environment marker for the child, refusing to recurse past the bound.
/// A finite plan's child must itself be bounded: the child's own default
/// measurement could not be entered, so the run would be unbounded again.
/// How many measurement processes deep this one already is, and the refusal to
/// go deeper. The child is a copy of this probe, so an unbounded chain would
/// fork forever if a child ever kept the flag; the marker makes that a named
/// error instead.
fn measurement_depth() -> Result<u32, String> {
    let depth = std::env::var(MEASURE_RECURSION_ENV)
        .ok()
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(0);
    if depth >= MAX_MEASURE_DEPTH {
        return Err(format!(
            "measurement chain stopped at depth {MAX_MEASURE_DEPTH}: {RECURSIVE_MEASURE_FLAG} reached a probe that was already measuring"
        ));
    }
    Ok(depth + 1)
}

/// Remove the recursive flag from the child's argv, so the child runs normally.
fn take_recursive_flag(args: &mut Vec<String>) -> bool {
    take_flag(args, &[RECURSIVE_MEASURE_FLAG])
}

/// One measurement invocation: how many times, how long a bound, how often to
/// sample, and the argv the child runs.
#[derive(Debug, Clone, PartialEq)]
struct MeasurePlan {
    label: String,
    argv: Vec<OsString>,
    timeout: std::time::Duration,
    sample: std::time::Duration,
    repeat: usize,
}

fn measure_plan(args: MeasureArgs, argv: Vec<OsString>, label: &str) -> MeasurePlan {
    MeasurePlan {
        label: label.to_owned(),
        argv: measure_child_args(&argv),
        timeout: std::time::Duration::from_secs_f64(args.timeout_secs),
        sample: std::time::Duration::from_millis(args.sample_ms),
        repeat: args.repeat,
    }
}

/// The program the measured child is: this binary, which the OS already told us.
fn current_program() -> Result<PathBuf, String> {
    std::env::current_exe().map_err(|e| format!("this probe's own path: {e}"))
}

/// Run every sample, print the report, and fail the probe when any sample did
/// not finish cleanly (a killed fixture is not a measurement).
fn report_measure(plan: &MeasurePlan) -> Result<(), String> {
    let program = current_program()?;
    let mut runs = Vec::with_capacity(plan.repeat);
    for _ in 0..plan.repeat {
        let run = run_measured_child(&program, &plan.argv, plan.timeout, plan.sample)?;
        // A run that printed no `jvm up:` never had a JVM to measure; naming
        // that here is clearer than a blank startup figure downstream.
        if run.startup_ms.is_none() && !run.timed_out {
            eprintln!(
                "horizon-jvm: the measured probe printed no `{JVM_UP_MARKER}` line; startup time is n/a"
            );
        }
        runs.push(run);
    }
    let report = MeasureReport {
        label: plan.label.clone(),
        runs,
    };
    if std::env::args_os().any(|arg| arg == "--json") {
        println!("{}", report.json());
    } else {
        print!("{}", report.text());
    }
    if report.succeeded() {
        return Ok(());
    }
    let killed = report.runs.iter().filter(|run| run.timed_out).count();
    if killed > 0 {
        return Err(format!(
            "measurement bound ({:.3}s) reached; the probe was killed {} time(s)",
            plan.timeout.as_secs_f64(),
            killed
        ));
    }
    // A failed sample is not a measurement, and the child's own error is the
    // only useful thing to say about it.
    let reason = report
        .runs
        .iter()
        .find(|run| !run.measured())
        .map(|run| first_fml_error_line(&run.stderr, ""))
        .unwrap_or_else(|| "no output".to_owned());
    Err(format!(
        "the measured probe exited unsuccessfully: {reason}"
    ))
}

/// A label for what was measured: the entrypoints, or the kind when the run
/// discovers its own (a `neoforge` constructor run, `--real-loader`).
fn entry_label(entries: &[String], kind: &str) -> String {
    match entries {
        [] => format!("{kind} (discovered at runtime)"),
        [one] => one.clone(),
        _ => format!("{} {kind} entrypoint(s)", entries.len()),
    }
}

/// One `VmHWM`/`VmRSS` read of a process, in KiB.
fn read_vm(status: &str, key: &str) -> Option<u64> {
    let line = status.lines().find(|line| line.starts_with(key))?;
    line.split_whitespace().nth(1)?.parse().ok()
}

/// The high-water mark of a process's resident set in KiB. Linux records it in
/// `VmHWM` and it survives the process, so it is the figure to compare; macOS
/// and Windows have no equivalent kept after exit, and report `None`.
fn peak_rss_kib(status: &str) -> Option<u64> {
    read_vm(status, "VmHWM:").filter(|kib| *kib <= MAX_MEASURE_RSS_KIB)
}

/// The current resident set in KiB, for a sampler that runs while the child lives.
fn current_rss_kib(status: &str) -> Option<u64> {
    read_vm(status, "VmRSS:").filter(|kib| *kib <= MAX_MEASURE_RSS_KIB)
}

/// Everything one measured child produced.
#[derive(Debug, Clone, PartialEq)]
struct MeasureRun {
    /// Wall time to the `jvm up:` line, in milliseconds; `None` when the child
    /// never printed one (it failed before the JVM was up).
    startup_ms: Option<f64>,
    /// Wall time to the child's exit, in milliseconds.
    total_ms: f64,
    /// The child's own user+system CPU time, in milliseconds, where the OS
    /// reports it for a waited child.
    cpu_ms: Option<f64>,
    peak_rss_kib: Option<u64>,
    success: bool,
    timed_out: bool,
    truncated: bool,
    /// The child's stderr, kept only to explain a failed run.
    stderr: String,
}

impl MeasureRun {
    /// The child ran to a clean exit: the only case that is a measurement.
    fn measured(&self) -> bool {
        self.success && !self.timed_out
    }
}

const MAX_MEASURE_REPORT_BYTES: usize = 64 * 1024;

/// Number of runs plus the summary the report carries.
#[derive(Debug, Clone, PartialEq)]
struct MeasureReport {
    label: String,
    runs: Vec<MeasureRun>,
}

impl MeasureReport {
    fn median(&self, figure: impl Fn(&MeasureRun) -> Option<f64>) -> Option<f64> {
        let mut values: Vec<f64> = self.runs.iter().filter_map(figure).collect();
        if values.is_empty() {
            return None;
        }
        values.sort_by(f64::total_cmp);
        let middle = values.len() / 2;
        Some(if values.len() % 2 == 0 {
            (values[middle - 1] + values[middle]) / 2.0
        } else {
            values[middle]
        })
    }

    fn succeeded(&self) -> bool {
        !self.runs.is_empty() && self.runs.iter().all(MeasureRun::measured)
    }

    fn text(&self) -> String {
        let figure = |value: Option<f64>| {
            value.map_or_else(|| "n/a".to_owned(), |value| format!("{value:.3}"))
        };
        let mut lines = vec![
            format!("measure: entry {}", self.label),
            format!("measure: {} run(s)", self.runs.len()),
        ];
        for (index, run) in self.runs.iter().enumerate() {
            lines.push(format!(
                "measure: run{index} startup_ms={} total_ms={:.3} cpu_ms={} peak_rss_kib={} status={}{}{}",
                figure(run.startup_ms),
                run.total_ms,
                figure(run.cpu_ms),
                run.peak_rss_kib
                    .map_or_else(|| "n/a".to_owned(), |kib| kib.to_string()),
                if run.measured() { "ok" } else { "failed" },
                if run.timed_out { " (killed at the bound)" } else { "" },
                // The figures above stay valid: only the child's own output was
                // capped, after the marker that fixes the startup time.
                if run.truncated { " (output truncated)" } else { "" },
            ));
        }
        for (name, median) in [
            ("startup_ms", self.median(|run| run.startup_ms)),
            ("total_ms", self.median(|run| Some(run.total_ms))),
            ("cpu_ms", self.median(|run| run.cpu_ms)),
            (
                "peak_rss_kib",
                self.median(|run| run.peak_rss_kib.map(|kib| kib as f64))
                    .map(|value| value.round()),
            ),
        ] {
            lines.push(format!("measure: median_{name}={}", figure(median)));
        }
        // Bounded like every other report this probe prints.
        bound_text(&(lines.join("\n") + "\n"), MAX_MEASURE_REPORT_BYTES)
    }

    fn json(&self) -> String {
        serde_json::json!({
            "entry": self.label,
            "runs": self.runs.len(),
            "status": if self.succeeded() { "ok" } else { "failed" },
            "medianStartupMs": self.median(|run| run.startup_ms),
            "medianTotalMs": self.median(|run| Some(run.total_ms)),
            "medianCpuMs": self.median(|run| run.cpu_ms),
            "medianPeakRssKiB": self.median(|run| run.peak_rss_kib.map(|kib| kib as f64)),
            "samples": self.runs.iter().map(|run| {
                serde_json::json!({
                    "startupMs": run.startup_ms,
                    "totalMs": run.total_ms,
                    "cpuMs": run.cpu_ms,
                    "peakRssKiB": run.peak_rss_kib,
                    "status": if run.success { "ok" } else { "failed" },
                    "timedOut": run.timed_out,
                    "truncated": run.truncated,
                })
            }).collect::<Vec<_>>(),
        })
        .to_string()
    }
}

/// Time one child to exit, sampling its RSS until it does. A child past
/// `timeout` is killed with its whole process tree and reported as timed out.
fn run_measured_child(
    program: &Path,
    argv: &[OsString],
    timeout: std::time::Duration,
    sample: std::time::Duration,
) -> Result<MeasureRun, String> {
    use std::{
        io::BufRead,
        sync::{
            Arc, Mutex,
            atomic::{AtomicBool, Ordering},
        },
        time::Instant,
    };

    let mut command = Command::new(program);
    command
        .args(argv)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        // Replace, not append: a probe launched from a measuring probe (a
        // future nested run) must not inherit two copies of the marker.
        .env_remove(MEASURE_RECURSION_ENV)
        .env(MEASURE_RECURSION_ENV, measurement_depth()?.to_string());
    // A killed JVM leaves children behind on Linux; a fresh process group lets
    // the kill reach all of them and keeps this process's signals out of it.
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        command.process_group(0);
    }
    let start = Instant::now();
    let mut child = command
        .spawn()
        .map_err(|e| format!("could not start {}: {e}", program.display()))?;

    // `jvm up:` is the probe's own first line after the JVM exists, and its
    // time is taken when that line arrives, not when the stream ends. The
    // reader keeps at most `MAX_FML_OUTPUT_BYTES` and drains the rest, so a
    // chatty fixture cannot block on a full pipe or grow this process.
    let startup = Arc::new(Mutex::new(None::<f64>));
    let truncated = Arc::new(AtomicBool::new(false));
    let watcher = Arc::clone(&startup);
    let over = Arc::clone(&truncated);
    let stdout = child.stdout.take().map(|reader| {
        std::thread::spawn(move || {
            let mut kept = 0usize;
            for line in std::io::BufReader::new(reader).lines() {
                let Ok(line) = line else { break };
                if line.contains(JVM_UP_MARKER)
                    && let Ok(mut slot) = watcher.lock()
                {
                    slot.get_or_insert(start.elapsed().as_secs_f64() * 1000.0);
                }
                if kept <= MAX_FML_OUTPUT_BYTES {
                    kept += line.len() + 1;
                } else {
                    over.store(true, Ordering::Relaxed);
                }
                // The line itself is dropped on the next iteration; only its
                // length was ever counted, so nothing accumulates here.
            }
        })
    });
    let stderr_over = Arc::clone(&truncated);
    let stderr_text = Arc::new(Mutex::new(String::new()));
    let sink = Arc::clone(&stderr_text);
    let stderr = child.stderr.take().map(|reader| {
        std::thread::spawn(move || match read_bounded(reader, MAX_FML_STDERR_BYTES) {
            Ok((text, was_truncated)) => {
                if was_truncated {
                    stderr_over.store(true, Ordering::Relaxed);
                }
                if let Ok(mut sink) = sink.lock() {
                    *sink = text;
                }
            }
            Err(_) => stderr_over.store(true, Ordering::Relaxed),
        })
    });

    let outcome = supervise(&mut child, start, timeout, sample);
    for reader in [stdout, stderr].into_iter().flatten() {
        let _ = reader.join();
    }
    let (status, sampled_peak, cpu_ms) = outcome?;
    let startup_ms = *startup
        .lock()
        .map_err(|_| "measure start time".to_owned())?;
    let stderr_text = stderr_text
        .lock()
        .map(|text| text.clone())
        .unwrap_or_default();
    Ok(MeasureRun {
        startup_ms,
        total_ms: start.elapsed().as_secs_f64() * 1000.0,
        cpu_ms,
        peak_rss_kib: sampled_peak,
        success: status.is_some_and(|status| status.success()),
        timed_out: status.is_none(),
        truncated: truncated.load(Ordering::Relaxed),
        stderr: stderr_text,
    })
}

/// Wait for `child` with a bound while sampling its RSS; returns the exit
/// status (`None` when the bound was hit and the child was killed), the peak
/// RSS in KiB, and the child's own CPU time in milliseconds.
fn supervise(
    child: &mut std::process::Child,
    start: std::time::Instant,
    timeout: std::time::Duration,
    sample: std::time::Duration,
) -> Result<(Option<std::process::ExitStatus>, Option<u64>, Option<f64>), String> {
    let pid = child.id();
    // `RUSAGE_CHILDREN` is cumulative over every child this process reaped, so
    // each run's own CPU time is the difference around this one.
    let cpu_before = children_cpu_ms();
    let mut peak = None;
    let mut status = None;
    loop {
        match child
            .try_wait()
            .map_err(|e| format!("waiting for the probe: {e}"))?
        {
            Some(waited) => {
                status = Some(waited);
                break;
            }
            None => {
                let now = start.elapsed();
                if now >= timeout {
                    kill_tree(child);
                    // A killed child is reaped here, so no zombie outlives it.
                    let _ = child.wait();
                    break;
                }
                if let Some(kib) = process_status(pid).as_deref().and_then(current_rss_kib) {
                    peak = Some(peak.map_or(kib, |seen: u64| seen.max(kib)));
                }
                // Never sleep past the deadline: a short timeout must fire on
                // time even when the sample interval is longer.
                let nap = sample.min(timeout - now);
                std::thread::sleep(nap.max(std::time::Duration::from_millis(1)));
            }
        }
    }
    // The OS keeps the high-water mark even after the child is gone, and it is
    // exact where sampling can miss a spike; it wins whenever it is readable.
    let peak = process_status(pid)
        .as_deref()
        .and_then(peak_rss_kib)
        .or(peak);
    let cpu_ms = match (cpu_before, children_cpu_ms()) {
        (Some(before), Some(after)) => Some((after - before).max(0.0)),
        _ => None,
    };
    Ok((status, peak, cpu_ms))
}

/// A process's `/proc/<pid>/status`, on Linux; `None` elsewhere.
fn process_status(pid: u32) -> Option<String> {
    std::fs::read_to_string(format!("/proc/{pid}/status")).ok()
}

/// Kill a child and everything that shares its process group.
fn kill_tree(child: &mut std::process::Child) {
    #[cfg(unix)]
    {
        // The child leads its own group (`process_group(0)` above), so its
        // group id is its pid, and the negative form names the group rather
        // than the process: a mod's own `java`/helper children go with it.
        let group = child.id() as libc::pid_t;
        // SAFETY: `kill` takes a plain integer id and a signal number; a
        // vanished group returns ESRCH, which is the "already gone" answer.
        let _ = unsafe { libc::kill(-group, libc::SIGKILL) };
    }
    let _ = child.kill();
}

/// The CPU time of children this process has reaped, in milliseconds.
///
/// `getrusage(RUSAGE_CHILDREN)` is cumulative, so a caller takes it before and
/// after the run and subtracts; that is why one `--measure` run times exactly
/// one child probe process: every sample, and every repeat, gets its own.
#[cfg(unix)]
fn children_cpu_ms() -> Option<f64> {
    // SAFETY: `getrusage` writes only into the `rusage` it is given, which is
    // a live local; `RUSAGE_CHILDREN` needs no other setup.
    let usage = unsafe {
        let mut usage = std::mem::MaybeUninit::<libc::rusage>::uninit();
        if libc::getrusage(libc::RUSAGE_CHILDREN, usage.as_mut_ptr()) != 0 {
            return None;
        }
        usage.assume_init()
    };
    let seconds = usage.ru_utime.tv_sec as f64
        + usage.ru_utime.tv_usec as f64 / 1e6
        + usage.ru_stime.tv_sec as f64
        + usage.ru_stime.tv_usec as f64 / 1e6;
    Some(seconds * 1000.0)
}

#[cfg(not(unix))]
fn children_cpu_ms() -> Option<f64> {
    None
}

struct FmlCapture {
    stdout: String,
    stderr: String,
    success: bool,
    truncated: bool,
}

/// Read at most `limit` bytes, draining the rest so a chatty child cannot
/// block on a full pipe or grow memory.
fn read_bounded(mut reader: impl Read, limit: usize) -> std::io::Result<(String, bool)> {
    let mut text = Vec::new();
    let mut chunk = [0u8; 8192];
    let mut truncated = false;
    loop {
        let read = reader.read(&mut chunk)?;
        if read == 0 {
            break;
        }
        if text.len() < limit {
            let take = (limit - text.len()).min(read);
            text.extend_from_slice(&chunk[..take]);
            truncated |= take < read;
        } else {
            truncated = true;
        }
    }
    Ok((String::from_utf8_lossy(&text).into_owned(), truncated))
}

fn run_fml_probe(mut command: Command) -> Result<FmlCapture, String> {
    command.stdout(Stdio::piped()).stderr(Stdio::piped());
    let mut child = command
        .spawn()
        .map_err(|e| format!("could not start Java: {e}"))?;
    let stderr = child
        .stderr
        .take()
        .map(|reader| std::thread::spawn(move || read_bounded(reader, MAX_FML_STDERR_BYTES)));
    let stdout = match child.stdout.take() {
        Some(reader) => read_bounded(reader, MAX_FML_OUTPUT_BYTES),
        None => Ok((String::new(), false)),
    };
    let status = child.wait().map_err(|e| format!("waiting for Java: {e}"))?;
    let (stdout, stdout_truncated) = stdout.map_err(|e| format!("FML stdout: {e}"))?;
    let (stderr, stderr_truncated) = match stderr {
        Some(handle) => handle
            .join()
            .map_err(|_| "FML stderr reader panicked".to_owned())?
            .map_err(|e| format!("FML stderr: {e}"))?,
        None => (String::new(), false),
    };
    Ok(FmlCapture {
        stdout,
        stderr,
        success: status.success(),
        truncated: stdout_truncated || stderr_truncated,
    })
}

/// The child JVM arguments. Kept separate from [`Command`] so a test can check
/// the exact listing/run hand-off without starting Java.
fn fml_probe_args(
    libs: &Path,
    classpath: &Path,
    versions: &[(String, String)],
    mode: FmlMode,
) -> Vec<OsString> {
    let mut args: Vec<OsString> = vec![
        "--add-opens".into(),
        "java.base/java.lang.invoke=ALL-UNNAMED".into(),
        "-Djdk.attach.allowAttachSelf=true".into(),
        format!("-DlibraryDirectory={}", libs.display()).into(),
        "-cp".into(),
        classpath.as_os_str().to_owned(),
    ];
    for (name, value) in versions {
        args.push(format!("-Dhorizon.fml.{name}={value}").into());
    }
    args.push("horizon.FmlProbe".into());
    if mode == FmlMode::List {
        args.push("--list".into());
    }
    args
}

fn fml_probe_command(
    java: &Path,
    game: &Path,
    libs: &Path,
    classpath: &Path,
    versions: &[(String, String)],
    mode: FmlMode,
) -> Command {
    let mut command = Command::new(java);
    command
        .current_dir(game)
        .args(fml_probe_args(libs, classpath, versions, mode));
    command
}

/// Run the FML probe in a child JVM: FML's game locator assumes an ordinary
/// `java -cp` launch, which an embedded JNI VM does not reproduce.
fn run_real_neoforge(
    libs: &Path,
    mods: &[PathBuf],
    mode: FmlMode,
    json: bool,
) -> Result<(), String> {
    let classpath = fml_classpath(libs);
    if classpath.is_empty() {
        return Err(format!(
            "{}: no NeoForge unix_args.txt classpath found",
            libs.display()
        ));
    }
    let root = std::env::temp_dir().join(format!(
        "horizon-fml-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.as_nanos())
    ));
    let game = root.join("game");
    let mods_dir = game.join("mods");
    fs::create_dir_all(&mods_dir).map_err(|e| format!("{}: {e}", mods_dir.display()))?;
    for mod_jar in mods {
        let name = mod_jar
            .file_name()
            .ok_or_else(|| format!("{}: no file name", mod_jar.display()))?;
        fs::copy(mod_jar, mods_dir.join(name))
            .map_err(|e| format!("{}: {e}", mod_jar.display()))?;
    }
    let source = root.join("FmlProbe.java");
    let classes = root.join("classes");
    fs::create_dir_all(&classes).map_err(|e| format!("{}: {e}", classes.display()))?;
    fs::write(&source, FML_PROBE_SOURCE).map_err(|e| format!("{}: {e}", source.display()))?;
    let javac = std::env::var_os("JAVA_HOME")
        .map(PathBuf::from)
        .map(|home| home.join("bin").join("javac"))
        .unwrap_or_else(|| PathBuf::from("javac"));
    let runtime = std::env::join_paths(&classpath).map_err(|e| e.to_string())?;
    let compiled = Command::new(javac)
        .arg("-cp")
        .arg(&runtime)
        .arg("-d")
        .arg(&classes)
        .arg(&source)
        .output()
        .map_err(|e| format!("javac: {e}"))?;
    if !compiled.status.success() {
        let stderr = String::from_utf8_lossy(&compiled.stderr);
        let stdout = String::from_utf8_lossy(&compiled.stdout);
        return Err(format!(
            "FML probe did not compile: {}",
            first_fml_error_line(&stderr, &stdout)
        ));
    }
    let mut classpath = classpath;
    classpath.push(classes);
    let classpath = std::env::join_paths(&classpath).map_err(|e| e.to_string())?;
    let java = std::env::var_os("JAVA_HOME")
        .map(PathBuf::from)
        .map(|home| home.join("bin").join("java"))
        .unwrap_or_else(|| PathBuf::from("java"));
    let command = fml_probe_command(
        &java,
        &game,
        libs,
        Path::new(&classpath),
        &fml_versions(Some(libs)),
        mode,
    );
    let capture = run_fml_probe(command)?;
    let _ = fs::remove_dir_all(&root);
    match mode {
        FmlMode::List => {
            for line in fml_list_lines(&parse_fml_mods(&capture.stdout)) {
                println!("{line}");
            }
            if capture.success {
                Ok(())
            } else {
                Err(format!(
                    "FML probe failed: {}",
                    first_fml_error_line(&capture.stderr, &capture.stdout)
                ))
            }
        }
        FmlMode::Report => {
            let report = FmlReport {
                status: if capture.success { "ok" } else { "failed" },
                server: libs.display().to_string(),
                jars: mods.len(),
                mods: parse_fml_mods(&capture.stdout),
                initialized: capture
                    .stdout
                    .lines()
                    .any(|line| line.trim() == "initialized"),
                error: (!capture.success)
                    .then(|| first_fml_error_line(&capture.stderr, &capture.stdout)),
            };
            if json {
                println!("{}", report.json());
            } else {
                print!("{}", report.text());
            }
            Ok(())
        }
        FmlMode::Run => {
            if !capture.success {
                return Err(format!(
                    "FML probe failed: {}",
                    first_fml_error_line(&capture.stderr, &capture.stdout)
                ));
            }
            print!("{}", capture.stdout);
            if !capture.stderr.is_empty() {
                eprint!("{}", capture.stderr);
            }
            if capture.truncated {
                eprintln!(
                    "horizon-jvm: FML probe output truncated (stdout {MAX_FML_OUTPUT_BYTES} bytes, stderr {MAX_FML_STDERR_BYTES} bytes)"
                );
            }
            println!("real loader: FML probe completed");
            Ok(())
        }
    }
}

/// The exact runtime classpath an installed NeoForge server's `unix_args.txt`
/// records, resolved against the server directory.
fn fml_classpath(libs: &Path) -> Vec<PathBuf> {
    let mut args = Vec::new();
    let Ok(entries) = fs::read_dir(libs.join("net/neoforged/neoforge")) else {
        return Vec::new();
    };
    for entry in entries.flatten() {
        let path = entry.path().join("unix_args.txt");
        if path.is_file() {
            args.push(path);
        }
    }
    args.sort();
    let Some(path) = args.pop() else {
        return Vec::new();
    };
    let Ok(text) = fs::read_to_string(path) else {
        return Vec::new();
    };
    let Some(index) = text.lines().position(|line| line == "-classpath") else {
        return Vec::new();
    };
    let Some(entries) = text.lines().nth(index + 1) else {
        return Vec::new();
    };
    let server = libs.parent().unwrap_or(libs);
    entries
        .split(if cfg!(windows) { ';' } else { ':' })
        .map(|entry| {
            if Path::new(entry).is_absolute() {
                PathBuf::from(entry)
            } else {
                server.join(entry)
            }
        })
        .filter(|path| path.is_file())
        .collect()
}

/// The `--fml.*` version arguments the installed server records.
fn fml_versions(libs: Option<&Path>) -> Vec<(String, String)> {
    let Some(libs) = libs else {
        return Vec::new();
    };
    let mut args = Vec::new();
    let Ok(entries) = fs::read_dir(libs.join("net/neoforged/neoforge")) else {
        return Vec::new();
    };
    for entry in entries.flatten() {
        let path = entry.path().join("unix_args.txt");
        if path.is_file() {
            args.push(path);
        }
    }
    args.sort();
    let Some(path) = args.pop() else {
        return Vec::new();
    };
    let Ok(text) = fs::read_to_string(path) else {
        return Vec::new();
    };
    text.lines()
        .filter_map(|line| {
            let (key, value) = line.split_once(' ')?;
            key.strip_prefix("--fml.")
                .filter(|name| !name.is_empty() && !value.is_empty())
                .map(|name| (name.to_owned(), value.trim().to_owned()))
        })
        .collect()
}

fn take(args: &mut Vec<String>, name: &str) -> Option<String> {
    let at = args.iter().position(|a| a == name)?;
    if at + 1 >= args.len() {
        return None;
    }
    let value = args.remove(at + 1);
    args.remove(at);
    Some(value)
}

/// Every value of a repeatable flag, in command-line order. A dangling flag is
/// dropped instead of becoming a classpath entry.
fn take_all(args: &mut Vec<String>, name: &str) -> Vec<String> {
    let mut values = Vec::new();
    while let Some(at) = args.iter().position(|a| a == name) {
        if at + 1 >= args.len() {
            args.remove(at);
            break;
        }
        values.push(args.remove(at + 1));
        args.remove(at);
    }
    values
}

/// Finds a Fabric `entrypoints.<kind>` declaration, or NeoForge classes that
/// carry `@Mod`. The runner executes the returned entries in metadata order;
/// callers that need a different environment select it with `--entry-kind`.
fn discover_entries(jar: &Path, kind: &str) -> Result<Vec<String>, String> {
    if let Some((metadata_name, text)) = fabric_metadata_text(jar)? {
        // Datagen has its own group and never falls back to `main`/`client`:
        // only the datagen keys are read, so another group's adapter is never
        // validated for this run.
        if is_datagen_kind(kind) {
            let mut out = Vec::new();
            for key in DATAGEN_ENTRYPOINT_KINDS {
                out.extend(
                    entrypoints_from_metadata(metadata_name, &text, Some(key))?
                        .into_iter()
                        .map(|entry| entry.value),
                );
            }
            return Ok(out);
        }
        let metadata_kind = quilt_entrypoint_kind(metadata_name, kind);
        return entrypoints_from_metadata(metadata_name, &text, Some(metadata_kind))
            .map(|entries| entries.into_iter().map(|entry| entry.value).collect());
    }
    // NeoForge has no Fabric datagen callback, so its `@Mod` classes must not
    // masquerade as datagen entrypoints.
    if is_datagen_kind(kind) {
        return Ok(Vec::new());
    }
    neoforge_mod_classes(jar)
}

/// The Fabric/Quilt metadata file a jar carries, if any. Quilt is checked
/// second because a jar built for both uses the Fabric keys.
fn fabric_metadata_text(jar: &Path) -> Result<Option<(&'static str, String)>, String> {
    let file = File::open(jar).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| format!("{}: {e}", jar.display()))?;
    let Some(metadata_name) = metadata_file_name(&mut archive) else {
        return Ok(None);
    };
    let mut metadata = archive
        .by_name(metadata_name)
        .map_err(|e| format!("{}: {metadata_name}: {e}", jar.display()))?;
    let mut text = String::new();
    std::io::Read::read_to_string(&mut metadata, &mut text)
        .map_err(|e| format!("{}: {metadata_name}: {e}", jar.display()))?;
    Ok(Some((metadata_name, text)))
}

fn metadata_file_name(archive: &mut zip::ZipArchive<File>) -> Option<&'static str> {
    ["fabric.mod.json", "quilt.mod.json"]
        .into_iter()
        .find(|name| archive.by_name(name).is_ok())
}

/// The metadata path `discover_entries` reads, for wrong-side diagnostics.
fn metadata_path(jar: &Path) -> Result<Option<&'static str>, String> {
    Ok(fabric_metadata_text(jar)?.map(|(metadata_name, _)| metadata_name))
}

/// `@Mod`-annotated top-level classes, in sorted order. NeoForge's
/// `neoforge.mods.toml` does not name its mod class, so this stays a scan.
fn neoforge_mod_classes(jar: &Path) -> Result<Vec<String>, String> {
    let file = File::open(jar).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut out = Vec::new();
    for index in 0..archive.len() {
        let mut entry = archive
            .by_index(index)
            .map_err(|e| format!("{}: reading zip entry: {e}", jar.display()))?;
        let name = entry.name().to_owned();
        if !name.ends_with(".class") || name.contains('$') {
            continue;
        }
        let mut bytes = Vec::new();
        std::io::Read::read_to_end(&mut entry, &mut bytes)
            .map_err(|e| format!("{}: {name}: {e}", jar.display()))?;
        if bytes
            .windows(b"Lnet/neoforged/fml/common/Mod;".len())
            .any(|window| window == b"Lnet/neoforged/fml/common/Mod;")
            || bytes
                .windows(b"Lnet/minecraftforge/fml/common/Mod;".len())
                .any(|window| window == b"Lnet/minecraftforge/fml/common/Mod;")
        {
            out.push(name.trim_end_matches(".class").replace('/', "."));
        }
    }
    out.sort();
    Ok(out)
}

fn quilt_entrypoint_kind<'a>(metadata_name: &str, kind: &'a str) -> &'a str {
    if metadata_name != "quilt.mod.json" {
        return kind;
    }
    match kind {
        "main" => "init",
        "client" => "client_init",
        "server" => "server_init",
        other => other,
    }
}

/// Lists the entrypoint keys declared by a jar for a useful wrong-side error.
/// NeoForge has no metadata list, so an annotated class is represented by the
/// single `neoforge` kind after the bounded class scan.
fn declared_entrypoint_kinds(jar: &Path) -> Result<Vec<String>, String> {
    let file = File::open(jar).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| format!("{}: {e}", jar.display()))?;
    for metadata_name in ["fabric.mod.json", "quilt.mod.json"] {
        let Ok(mut metadata) = archive.by_name(metadata_name) else {
            continue;
        };
        let mut text = String::new();
        std::io::Read::read_to_string(&mut metadata, &mut text)
            .map_err(|e| format!("{}: {metadata_name}: {e}", jar.display()))?;
        let value: serde_json::Value = serde_json::from_str(&text)
            .map_err(|e| format!("{}: {metadata_name}: {e}", jar.display()))?;
        let mut kinds = value
            .get("entrypoints")
            .and_then(serde_json::Value::as_object)
            .map(|groups| groups.keys().cloned().collect::<Vec<_>>())
            .unwrap_or_default();
        kinds.sort();
        return Ok(kinds);
    }
    let has_neoforge = (0..archive.len()).any(|index| {
        let Ok(mut entry) = archive.by_index(index) else {
            return false;
        };
        let name = entry.name().to_owned();
        if !name.ends_with(".class") || name.contains('$') {
            return false;
        }
        let mut bytes = Vec::new();
        std::io::Read::read_to_end(&mut entry, &mut bytes).is_ok()
            && (bytes
                .windows(b"Lnet/neoforged/fml/common/Mod;".len())
                .any(|window| window == b"Lnet/neoforged/fml/common/Mod;")
                || bytes
                    .windows(b"Lnet/minecraftforge/fml/common/Mod;".len())
                    .any(|window| window == b"Lnet/minecraftforge/fml/common/Mod;"))
    });
    Ok(if has_neoforge {
        vec!["neoforge".to_owned()]
    } else {
        Vec::new()
    })
}

/// One `entrypoints.<kind>` declaration with the adapter Fabric would use.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Entrypoint {
    kind: String,
    value: String,
    adapter: String,
}

/// Adapters whose declarations the static/constructor dispatch can reach.
/// Anything else needs a language adapter this runner does not ship, so
/// discovery rejects it before a JVM starts instead of failing in clinit.
const KNOWN_ENTRYPOINT_ADAPTERS: [&str; 2] = ["default", "kotlin"];

/// Class names for one lifecycle kind, in metadata order. Runtime discovery
/// reads [`entrypoints_from_metadata`] so adapters are validated first; this
/// class-only view stays as the shape the existing tests assert.
#[cfg(test)]
fn fabric_entries(text: &str, kind: &str) -> Result<Vec<String>, String> {
    entrypoints_from_metadata("fabric.mod.json", text, Some(kind))
        .map(|entries| entries.into_iter().map(|entry| entry.value).collect())
}

/// Fabric and Quilt entry containers may nest strings, `{value, adapter}`
/// objects and arrays in any combination; flattening keeps declaration order.
/// A `None` kind collects every lifecycle key for `--list-entrypoints`.
fn entrypoints_from_metadata(
    metadata_name: &str,
    text: &str,
    kind: Option<&str>,
) -> Result<Vec<Entrypoint>, String> {
    let value: serde_json::Value =
        serde_json::from_str(text).map_err(|e| format!("{metadata_name}: {e}"))?;
    let Some(groups) = value
        .get("entrypoints")
        .and_then(serde_json::Value::as_object)
    else {
        return Ok(Vec::new());
    };
    let mut out = Vec::new();
    for (group_kind, group) in groups {
        if kind.is_none_or(|kind| kind == group_kind) {
            flatten_entrypoint(metadata_name, group_kind, group, &mut out)?;
        }
    }
    Ok(out)
}

fn flatten_entrypoint(
    metadata_name: &str,
    kind: &str,
    value: &serde_json::Value,
    out: &mut Vec<Entrypoint>,
) -> Result<(), String> {
    match value {
        serde_json::Value::Array(values) => {
            for value in values {
                flatten_entrypoint(metadata_name, kind, value, out)?;
            }
        }
        serde_json::Value::String(class) => push_entrypoint(kind, class, "default", out),
        serde_json::Value::Object(object) => {
            let adapter = object
                .get("adapter")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("default");
            let class = object
                .get("value")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("");
            if !KNOWN_ENTRYPOINT_ADAPTERS.contains(&adapter) {
                return Err(format!(
                    "{metadata_name}: entrypoint {} declares unsupported adapter {adapter:?}; expected one of {}",
                    if class.is_empty() {
                        "(missing value)"
                    } else {
                        class
                    },
                    KNOWN_ENTRYPOINT_ADAPTERS.join(", ")
                ));
            }
            push_entrypoint(kind, class, adapter, out);
        }
        _ => {}
    }
    Ok(())
}

fn push_entrypoint(kind: &str, value: &str, adapter: &str, out: &mut Vec<Entrypoint>) {
    if value.is_empty() {
        return;
    }
    out.push(Entrypoint {
        kind: kind.to_owned(),
        value: value.to_owned(),
        adapter: adapter.to_owned(),
    });
}

/// Every declaration in one jar, for `--list-entrypoints`.
fn all_entrypoints(jar: &Path) -> Result<Vec<Entrypoint>, String> {
    let Some((metadata_name, text)) = fabric_metadata_text(jar)? else {
        return Ok(neoforge_mod_classes(jar)?
            .into_iter()
            .map(|value| Entrypoint {
                kind: "neoforge".to_owned(),
                value,
                adapter: "default".to_owned(),
            })
            .collect());
    };
    entrypoints_from_metadata(metadata_name, &text, None)
}

/// One `kind<TAB>entrypoint` line per declaration. The sort is stable, so
/// declarations of one kind keep metadata order (including across jars).
fn format_entrypoints(entries: &[Entrypoint]) -> String {
    let mut sorted: Vec<&Entrypoint> = entries.iter().collect();
    sorted.sort_by(|a, b| a.kind.cmp(&b.kind));
    sorted
        .iter()
        .map(|entry| format!("{}\t{}\n", entry.kind, entry.value))
        .collect()
}

fn list_entrypoints(jars: &[String]) -> Result<(), String> {
    let mut entries = Vec::new();
    for jar in jars {
        let path = Path::new(jar);
        entries.extend(all_entrypoints(path)?);
        if metadata_path(path)?.is_none() {
            report_neoforge_metadata(path);
        }
    }
    print!("{}", format_entrypoints(&entries));
    Ok(())
}

/// The wrong-side error is most useful when it names the metadata it read and
/// the side the jar was actually built for.
fn missing_entry_message(
    jar: &str,
    kind: &str,
    metadata: Option<&str>,
    declared: &[String],
) -> String {
    let metadata = metadata.map_or_else(String::new, |name| format!(" ({name})"));
    let declared_note = if declared.is_empty() {
        String::new()
    } else {
        format!("; declared kinds: {}", declared.join(", "))
    };
    let client_only = kind != "client"
        && !declared.is_empty()
        && declared
            .iter()
            .all(|declared_kind| matches!(declared_kind.as_str(), "client" | "client_init"));
    let hint = if client_only {
        "; this jar declares client entrypoints only, so select --entry-kind client (or pass --entry <class>)"
    } else {
        "; pass --entry <class>"
    };
    format!("no {kind} entrypoint found in {jar}{metadata}{declared_note}{hint}")
}

/// NeoForge's `mods.toml` carries loader, mod id and mixin markers but no mod
/// class. These fields are diagnostics only: the `@Mod` class scan decides
/// what runs, keeping NeoForge constructor-only semantics.
#[derive(Debug, Default, PartialEq, Eq)]
struct NeoForgeMetadata {
    path: Option<String>,
    mod_loader: Option<String>,
    mod_ids: Vec<String>,
    jar_jars: usize,
    /// `[[mixins]] config` with the `environment` its block declares, if any.
    mixin_configs: Vec<(String, MixinEnvironment)>,
}

impl NeoForgeMetadata {
    fn diagnostic(&self) -> Option<String> {
        let mut parts = Vec::new();
        if let Some(loader) = &self.mod_loader {
            parts.push(format!("modLoader {loader}"));
        }
        if !self.mod_ids.is_empty() {
            parts.push(format!("mod ids {}", self.mod_ids.join(", ")));
        }
        if self.jar_jars > 0 {
            parts.push(format!("{} nested jarJar jar(s)", self.jar_jars));
        }
        if !self.mixin_configs.is_empty() {
            parts.push(format!("{} mixin config(s)", self.mixin_configs.len()));
        }
        (!parts.is_empty()).then(|| {
            format!(
                "{} (diagnostics only): {}",
                self.path.as_deref().unwrap_or("NeoForge metadata"),
                parts.join("; ")
            )
        })
    }
}

/// Hand parser: only the top-level `modLoader`, `[[mods]] modId` and
/// `[[mixins]] config`/`environment` keys matter, and no TOML dependency is
/// worth adding.
fn parse_neoforge_toml(text: &str) -> NeoForgeMetadata {
    let mut metadata = NeoForgeMetadata::default();
    let mut section = String::new();
    // The `[[mixins]]` block in progress. `environment` may come before or
    // after its `config`, so the pair is flushed when the block ends.
    let mut mixin_config: Option<String> = None;
    let mut mixin_environment = MixinEnvironment::Both;
    for raw in text.lines() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.starts_with('[') {
            flush_mixin_block(&mut metadata, &mut mixin_config, &mut mixin_environment);
            section = line.to_owned();
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        let value = value.trim().trim_matches(|c| c == '"' || c == '\'');
        if value.is_empty() {
            continue;
        }
        match (section.as_str(), key.trim()) {
            ("", "modLoader") => metadata.mod_loader = Some(value.to_owned()),
            ("[[mods]]", "modId") => push_unique(&mut metadata.mod_ids, value),
            ("[[mixins]]", "config") => mixin_config = Some(value.to_owned()),
            ("[[mixins]]", "environment") => mixin_environment = MixinEnvironment::parse(value),
            _ => {}
        }
    }
    flush_mixin_block(&mut metadata, &mut mixin_config, &mut mixin_environment);
    metadata
}

/// Commit one parsed `[[mixins]]` block and reset the next block's state.
fn flush_mixin_block(
    metadata: &mut NeoForgeMetadata,
    mixin_config: &mut Option<String>,
    mixin_environment: &mut MixinEnvironment,
) {
    if let Some(config) = mixin_config.take() {
        push_mixin_config(&mut metadata.mixin_configs, &config, *mixin_environment);
    }
    *mixin_environment = MixinEnvironment::Both;
}

fn neoforge_metadata(jar: &Path) -> Result<NeoForgeMetadata, String> {
    let file = File::open(jar).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut metadata = NeoForgeMetadata::default();
    for name in ["META-INF/neoforge.mods.toml", "META-INF/mods.toml"] {
        let Ok(mut entry) = archive.by_name(name) else {
            continue;
        };
        let mut text = String::new();
        std::io::Read::read_to_string(&mut entry, &mut text)
            .map_err(|e| format!("{}: {name}: {e}", jar.display()))?;
        metadata = parse_neoforge_toml(&text);
        metadata.path = Some(name.to_owned());
        break;
    }
    for index in 0..archive.len() {
        let Ok(entry) = archive.by_index(index) else {
            continue;
        };
        let name = entry.name().to_owned();
        if let Some(nested) = name.strip_prefix("META-INF/jarjar/") {
            if nested.ends_with(".jar") {
                metadata.jar_jars += 1;
            }
        } else if is_mixin_config_name(&name) {
            push_root_mixin_config(&mut metadata.mixin_configs, &name);
        }
    }
    Ok(metadata)
}

fn is_mixin_config_name(name: &str) -> bool {
    name.ends_with(".mixins.json") || (!name.contains('/') && name.contains("mixins"))
}

fn push_unique(values: &mut Vec<String>, value: &str) {
    if !values.iter().any(|existing| existing == value) {
        values.push(value.to_owned());
    }
}

/// The side a mixin config was declared for. Fabric and Quilt spell `*` for
/// "both", and a declaration with no environment at all means the same thing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MixinEnvironment {
    Client,
    Server,
    /// `*`, an unknown value, or no environment declared: both sides.
    Both,
}

impl MixinEnvironment {
    /// A declared environment. Unknown values stay on both sides instead of
    /// dropping a config the loader would still load.
    fn parse(declared: &str) -> Self {
        match declared.trim().to_ascii_lowercase().as_str() {
            "client" => Self::Client,
            "server" => Self::Server,
            _ => Self::Both,
        }
    }

    /// The environment `--entry-kind` selects. Loader-lifecycle kinds
    /// (`main`, `preLaunch`, `neoforge`, `init`) can run on either side.
    fn selected(entry_kind: &str) -> Self {
        match entry_kind {
            "client" | "client_init" => Self::Client,
            "server" | "server_init" => Self::Server,
            _ => Self::Both,
        }
    }

    /// Whether a config declared for `self` is registered on `selected`. A
    /// `*` selection takes everything, and an undeclared config loads
    /// everywhere.
    fn matches(self, selected: Self) -> bool {
        selected == Self::Both || self == Self::Both || self == selected
    }

    /// The `--list-mixin-configs` column and skipped-line spelling.
    fn label(self) -> &'static str {
        match self {
            Self::Client => "client",
            Self::Server => "server",
            Self::Both => "*",
        }
    }

    /// Two declarations of one file merge permissively: `*` wins, and a
    /// client+server pair is both sides.
    fn broadest(self, other: Self) -> Self {
        if self == other { self } else { Self::Both }
    }
}

/// Adds a declared config, folding a second declaration of the same file into
/// the broader environment. Declaration order is kept; callers sort.
fn push_mixin_config(
    configs: &mut Vec<(String, MixinEnvironment)>,
    config: &str,
    environment: MixinEnvironment,
) {
    if config.is_empty() {
        return;
    }
    match configs.iter_mut().find(|(declared, _)| declared == config) {
        Some((_, existing)) => *existing = existing.broadest(environment),
        None => configs.push((config.to_owned(), environment)),
    }
}

/// A config the root `*.mixins.json` scan found. It declares no environment,
/// and being on the jar root must not widen one a metadata declaration already
/// gave this file.
fn push_root_mixin_config(configs: &mut Vec<(String, MixinEnvironment)>, config: &str) {
    if config.is_empty() || configs.iter().any(|(declared, _)| declared == config) {
        return;
    }
    configs.push((config.to_owned(), MixinEnvironment::Both));
}

/// One mixin config a jar declares, or one passed with `--mixin-config`.
#[derive(Debug, Clone, PartialEq, Eq)]
struct MixinConfigRef {
    /// The archive the config lives in. For `--mixin-config`, the file itself.
    source: PathBuf,
    /// The zip entry name, or the path as typed for `--mixin-config`.
    config: String,
    /// The side the declaration named; `*` when it named none.
    environment: MixinEnvironment,
    explicit: bool,
}

impl MixinConfigRef {
    /// The first column of `--list-mixin-configs`: `-` for a config passed on
    /// the command line, which no jar owns.
    fn jar_label(&self) -> String {
        if self.explicit {
            "-".to_owned()
        } else {
            self.source.display().to_string()
        }
    }

    /// The config text, capped so a hostile archive cannot make the probe read
    /// without bound. Failure labels are stable so diagnostics do not vary by
    /// host.
    fn read(&self) -> Result<String, &'static str> {
        const MAX_MIXIN_CONFIG_BYTES: u64 = 1 << 20;
        if self.explicit {
            let size = fs::metadata(&self.source).map_err(|_| "not found")?.len();
            if size > MAX_MIXIN_CONFIG_BYTES {
                return Err("too large");
            }
            return fs::read_to_string(&self.source).map_err(|_| "unreadable");
        }
        let file = File::open(&self.source).map_err(|_| "jar unreadable")?;
        let mut archive = zip::ZipArchive::new(file).map_err(|_| "jar unreadable")?;
        let mut entry = archive
            .by_name(&self.config)
            .map_err(|_| "missing from the jar")?;
        if entry.size() > MAX_MIXIN_CONFIG_BYTES {
            return Err("too large");
        }
        let mut text = String::new();
        std::io::Read::read_to_string(&mut entry, &mut text).map_err(|_| "unreadable")?;
        Ok(text)
    }

    /// Whether the archive (or the explicit file) really carries the config.
    /// Chosen over [`Self::read`] so a config above the probe's read bound is
    /// still handed to Mixin, which has its own limits.
    fn exists(&self) -> bool {
        if self.explicit {
            return fs::metadata(&self.source).is_ok_and(|meta| meta.is_file());
        }
        let Ok(file) = File::open(&self.source) else {
            return false;
        };
        let Ok(mut archive) = zip::ZipArchive::new(file) else {
            return false;
        };
        archive.by_name(&self.config).is_ok()
    }
}

/// Mixin configs for every jar on the classpath plus the explicit
/// `--mixin-config` files, deduplicated and sorted. Only archive entries are
/// read, so discovery never follows a path out of a supplied jar.
fn discover_mixin_configs(classpath: &[PathBuf], explicit: &[String]) -> Vec<MixinConfigRef> {
    const MAX_CONFIGS: usize = 256;
    let mut out: Vec<MixinConfigRef> = explicit
        .iter()
        .map(|path| MixinConfigRef {
            source: PathBuf::from(path),
            config: path.clone(),
            // An explicit config names no side, so it loads on both.
            environment: MixinEnvironment::Both,
            explicit: true,
        })
        .collect();
    for path in classpath {
        let Some(configs) = jar_mixin_configs(path) else {
            continue;
        };
        out.extend(
            configs
                .into_iter()
                .map(|(config, environment)| MixinConfigRef {
                    source: path.clone(),
                    config,
                    environment,
                    explicit: false,
                }),
        );
    }
    out.sort_by(|a, b| (a.jar_label(), &a.config).cmp(&(b.jar_label(), &b.config)));
    out.dedup();
    if out.len() > MAX_CONFIGS {
        out.truncate(MAX_CONFIGS);
        eprintln!("horizon-jvm: mixin config discovery capped at {MAX_CONFIGS} configs");
    }
    out
}

/// The mixin configs a jar declares or carries at its root: Fabric/Quilt
/// metadata entries, NeoForge `[[mixins]] config`, and root `*.mixins.json`
/// (the last two with no environment, so `*`).
fn jar_mixin_configs(jar: &Path) -> Option<Vec<(String, MixinEnvironment)>> {
    let file = File::open(jar).ok()?;
    let mut archive = zip::ZipArchive::new(file).ok()?;
    let mut configs = Vec::new();
    if let Some(value) = archive_json(&mut archive, "fabric.mod.json") {
        extend_mixin_configs(&mut configs, fabric_mixin_configs(&value));
    }
    if let Some(value) = archive_json(&mut archive, "quilt.mod.json") {
        extend_mixin_configs(&mut configs, quilt_mixin_configs(&value));
    }
    for name in ["META-INF/neoforge.mods.toml", "META-INF/mods.toml"] {
        let Ok(mut entry) = archive.by_name(name) else {
            continue;
        };
        let mut text = String::new();
        if std::io::Read::read_to_string(&mut entry, &mut text).is_ok() {
            extend_mixin_configs(&mut configs, parse_neoforge_toml(&text).mixin_configs);
        }
        break;
    }
    for index in 0..archive.len() {
        let Ok(entry) = archive.by_index(index) else {
            continue;
        };
        let name = entry.name().to_owned();
        if !name.contains('/') && name.ends_with(".mixins.json") {
            push_root_mixin_config(&mut configs, &name);
        }
    }
    configs.retain(|(config, _)| !config.is_empty());
    configs.sort_by(|a, b| a.0.cmp(&b.0));
    Some(configs)
}

/// One metadata file parsed as JSON. Discovery is best-effort: a jar without
/// the file, or with unreadable JSON in it, contributes no declarations.
fn archive_json(archive: &mut zip::ZipArchive<File>, name: &str) -> Option<serde_json::Value> {
    let mut entry = archive.by_name(name).ok()?;
    let mut text = String::new();
    std::io::Read::read_to_string(&mut entry, &mut text).ok()?;
    serde_json::from_str(&text).ok()
}

fn extend_mixin_configs(
    out: &mut Vec<(String, MixinEnvironment)>,
    configs: Vec<(String, MixinEnvironment)>,
) {
    for (config, environment) in configs {
        push_mixin_config(out, &config, environment);
    }
}

/// Fabric's `mixins` list: classpath strings, or `{config, environment}`
/// objects. A bare string is accepted for hand-written metadata and has no
/// environment, so it loads on either side.
fn fabric_mixin_configs(value: &serde_json::Value) -> Vec<(String, MixinEnvironment)> {
    value
        .get("mixins")
        .map_or_else(Vec::new, mixin_declarations)
}

/// Quilt's `mixin` key: one config path or a list of them, plus the same
/// `{mixin, environment}` object form Fabric uses.
fn quilt_mixin_configs(value: &serde_json::Value) -> Vec<(String, MixinEnvironment)> {
    value.get("mixin").map_or_else(Vec::new, mixin_declarations)
}

/// A declaration list whose elements are strings or `{config|mixin,
/// environment}` objects, in declaration order.
fn mixin_declarations(value: &serde_json::Value) -> Vec<(String, MixinEnvironment)> {
    let mut out = Vec::new();
    for value in json_values(value) {
        match value {
            serde_json::Value::String(config) => {
                push_mixin_config(&mut out, config, MixinEnvironment::Both);
            }
            serde_json::Value::Object(object) => {
                let config = object
                    .get("config")
                    .or_else(|| object.get("mixin"))
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("");
                let environment = object
                    .get("environment")
                    .and_then(serde_json::Value::as_str)
                    .map_or(MixinEnvironment::Both, MixinEnvironment::parse);
                push_mixin_config(&mut out, config, environment);
            }
            _ => {}
        }
    }
    out
}

/// A JSON list, or a single value where a list was expected.
fn json_values(value: &serde_json::Value) -> Vec<&serde_json::Value> {
    match value {
        serde_json::Value::Array(items) => items.iter().collect(),
        other => vec![other],
    }
}

/// The bounded view of a mixin config the fallback reports: `package`,
/// `mixins`, `client`, `server`, `required` and `priority`.
#[derive(Debug, Default, PartialEq, Eq)]
struct MixinConfig {
    /// Fully-qualified mixin classes, in config order.
    entries: Vec<String>,
    /// Entries Mixin would treat as required.
    required: usize,
    priority: Option<i64>,
}

/// Tolerant reader: a config whose lists hold something other than class names
/// still reports what it can instead of failing the run. `required` defaults to
/// true, as in Mixin.
fn parse_mixin_config(text: &str) -> Result<MixinConfig, String> {
    let value: serde_json::Value = serde_json::from_str(text).map_err(|e| e.to_string())?;
    let object = value
        .as_object()
        .ok_or_else(|| "not a JSON object".to_owned())?;
    let package = object
        .get("package")
        .and_then(serde_json::Value::as_str)
        .filter(|package| !package.is_empty());
    let required = object
        .get("required")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let mut config = MixinConfig {
        entries: Vec::new(),
        required: 0,
        priority: object.get("priority").and_then(serde_json::Value::as_i64),
    };
    for key in ["mixins", "client", "server"] {
        for (name, entry_required) in mixin_entries(object.get(key)) {
            config.entries.push(match package {
                Some(package) if !name.contains('.') => format!("{package}.{name}"),
                _ => name,
            });
            if entry_required.unwrap_or(required) {
                config.required += 1;
            }
        }
    }
    Ok(config)
}

/// `mixins`/`client`/`server` members as `(class, per-entry required)` pairs.
/// Elements may be strings or `{mixin, target, required}` objects.
fn mixin_entries(value: Option<&serde_json::Value>) -> Vec<(String, Option<bool>)> {
    let Some(value) = value else {
        return Vec::new();
    };
    json_values(value)
        .into_iter()
        .filter_map(|value| match value {
            serde_json::Value::String(name) => Some((name.clone(), None)),
            serde_json::Value::Object(object) => {
                let name = object
                    .get("mixin")
                    .or_else(|| object.get("target"))
                    .and_then(serde_json::Value::as_str)?;
                let required = object.get("required").and_then(serde_json::Value::as_bool);
                Some((name.to_owned(), required))
            }
            _ => None,
        })
        .filter(|(name, _)| !name.is_empty())
        .collect()
}

/// `mixin config:` and `mixin targets:` for one config, plus the priority that
/// orders it. The targets list names the classes the config registers for
/// weaving, package-qualified; what they target lives in their `@Mixin`
/// annotations, which this probe does not read.
fn mixin_config_report(reference: &MixinConfigRef) -> (Option<i64>, Vec<String>) {
    let text = match reference.read() {
        Ok(text) => text,
        Err(reason) => {
            let line = format!("mixin config: {} ({reason})", reference.config);
            return (None, vec![line]);
        }
    };
    match parse_mixin_config(&text) {
        Ok(config) => {
            let mut lines = vec![format!(
                "mixin config: {} ({} mixins, {} required)",
                reference.config,
                config.entries.len(),
                config.required
            )];
            if !config.entries.is_empty() {
                lines.push(format!("mixin targets: {}", config.entries.join(", ")));
            }
            (config.priority, lines)
        }
        Err(reason) => (
            None,
            vec![format!(
                "mixin config: {} (invalid JSON: {reason})",
                reference.config
            )],
        ),
    }
}

/// Every report line, ordered by Mixin's priority and then the diagnostic text
/// so the output does not depend on classpath enumeration. Identical lines are
/// folded: a config two jars both declare as missing (or both carry) is named
/// once.
fn report_mixin_configs(configs: &[MixinConfigRef]) -> Vec<String> {
    let mut reports: Vec<(Option<i64>, Vec<String>)> =
        configs.iter().map(mixin_config_report).collect();
    reports.sort_by(|a, b| {
        a.0.unwrap_or(i64::MIN)
            .cmp(&b.0.unwrap_or(i64::MIN))
            .then_with(|| a.1.cmp(&b.1))
    });
    let mut lines: Vec<String> = reports.into_iter().flat_map(|(_, lines)| lines).collect();
    lines.dedup();
    lines
}

/// Upper bound for one `-Dmixin.configs` value. Mixin reads a single property,
/// so a hostile archive must not be able to grow the JVM argument without
/// bound.
const MAX_MIXIN_CONFIG_PROPERTY_BYTES: usize = 8192;

/// The value of `-Dmixin.configs`: Mixin's comma-separated classpath resource
/// list. Names are sorted and deduplicated so the value never depends on
/// classpath enumeration, and the list stops at
/// [`MAX_MIXIN_CONFIG_PROPERTY_BYTES`]. Empty names and names containing a
/// comma are dropped because the property has no way to express them.
fn format_mixin_config_property(names: impl IntoIterator<Item = String>) -> Option<String> {
    let mut names: Vec<String> = names
        .into_iter()
        .filter(|name| !name.is_empty() && !name.contains(','))
        .collect();
    names.sort();
    names.dedup();
    let mut value = String::new();
    for name in names {
        let separator = usize::from(!value.is_empty());
        if value.len() + separator + name.len() > MAX_MIXIN_CONFIG_PROPERTY_BYTES {
            break;
        }
        if separator == 1 {
            value.push(',');
        }
        value.push_str(&name);
    }
    (!value.is_empty()).then_some(value)
}

/// The property for the discovered configs, or `None` when no supplied jar
/// carries one. Config names come from archive entries or `--mixin-config`
/// values only, so the list cannot name a path outside them.
///
/// Fabric Loader's own hand-off is different: `FabricMixinBootstrap` reads each
/// mod's *parsed* metadata and calls `Mixins.addConfiguration`. The embedded
/// bridge seeds container proxies rather than parsed metadata, so the probe
/// registers this same list itself after the static bootstrap
/// ([`register_mixin_configs`]); the legacy property stays set for Mixin builds
/// that read it at launch. A real weaving run still needs the loader to agree on
/// the list.
fn mixin_config_property(configs: &[MixinConfigRef]) -> Option<String> {
    format_mixin_config_property(
        configs
            .iter()
            .filter(|config| config.exists())
            .map(|config| config.config.clone()),
    )
}

/// The configs the selected environment registers: everything for `*`, and
/// the `*`-plus-own-side declarations for one side. The property and the
/// `addConfiguration` calls both walk this list, so filtering happens once.
fn select_mixin_configs(
    configs: Vec<MixinConfigRef>,
    selected: MixinEnvironment,
) -> Vec<MixinConfigRef> {
    configs
        .into_iter()
        .filter(|config| config.environment.matches(selected))
        .collect()
}

/// One `mixin configs: skipped <environment> <config>` line per config the
/// selected environment leaves out. Sorted and folded, so a config two jars
/// declare is named once and the order never depends on the classpath.
fn skipped_mixin_configs(configs: &[MixinConfigRef], selected: MixinEnvironment) -> Vec<String> {
    let mut lines: Vec<String> = configs
        .iter()
        .filter(|config| !config.environment.matches(selected))
        .map(|config| {
            format!(
                "mixin configs: skipped {} {}",
                config.environment.label(),
                config.config
            )
        })
        .collect();
    lines.sort();
    lines.dedup();
    lines
}

/// The configs the property carries, in the property's own order. Registration
/// walks this list, so the JVM property and the `addConfiguration` calls cannot
/// drift apart.
fn mixin_config_names(property: Option<&str>) -> Vec<&str> {
    property
        .map(|value| value.split(',').filter(|name| !name.is_empty()).collect())
        .unwrap_or_default()
}

/// How many configs the property carries, for the deterministic log line.
fn mixin_registered_count(property: Option<&str>) -> usize {
    mixin_config_names(property).len()
}

/// `mixin configs: N registered`, or `mixin configs: none` when discovery found
/// nothing a jar actually carries.
fn mixin_configs_line(registered: usize) -> String {
    if registered == 0 {
        "mixin configs: none".to_owned()
    } else {
        format!("mixin configs: {registered} registered")
    }
}

/// The JVM options that hand the config list to Mixin. Kept as an argument list
/// so a test can inspect the exact property without starting a JVM.
fn mixin_jvm_options(property: Option<&str>) -> Vec<String> {
    property
        .map(|value| vec![format!("-Dmixin.configs={value}")])
        .unwrap_or_default()
}

/// `--list-mixin-configs`: one `jar<TAB>config<TAB>environment` line per
/// declaration, sorted. Everything is listed regardless of `--entry-kind`, so
/// the column is how a filtered run's decision can be checked. No JVM starts,
/// and only the jars named on the command line are scanned (nested jars are a
/// classpath-time expansion).
fn list_mixin_configs(jars: &[String], explicit: &[String]) -> Result<(), String> {
    let classpath: Vec<PathBuf> = jars.iter().map(PathBuf::from).collect();
    let configs = discover_mixin_configs(&classpath, explicit);
    print!("{}", format_mixin_configs(&configs));
    Ok(())
}

fn format_mixin_configs(configs: &[MixinConfigRef]) -> String {
    let mut lines: Vec<String> = configs
        .iter()
        .map(|config| {
            format!(
                "{}\t{}\t{}",
                config.jar_label(),
                config.config,
                config.environment.label()
            )
        })
        .collect();
    lines.sort();
    lines.dedup();
    lines.into_iter().map(|line| line + "\n").collect()
}

/// The static bootstrap's outcome: `Ok(())` means Mixin came up far enough to
/// accept `addConfiguration`; `Err` is the fallback label for the reported
/// failure. A failure leaves the property hand-off in place and skips
/// registration, which is only meaningful after a successful bootstrap.
type MixinBootstrap = Result<(), String>;

/// One step of the Mixin hand-off between the config report and the first
/// entrypoint, in Fabric's order. The plan is data, so a test can assert the
/// sequence without starting a JVM.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MixinStage {
    /// `MixinBootstrap.init()`, reported as `mixin bootstrap: <label>`.
    Bootstrap,
    /// `Mixins.addConfiguration(name)` per config, reported per failure plus a
    /// final summary.
    Registration,
}

/// The stages a run with `registered` configs performs, in order. A run with
/// none has no stage: it reports `mixin bootstrap: no configs` and loads no
/// Mixin class for nothing. Registration always follows the bootstrap that
/// makes it meaningful.
fn mixin_stages(registered: usize) -> &'static [MixinStage] {
    if registered == 0 {
        &[]
    } else {
        &[MixinStage::Bootstrap, MixinStage::Registration]
    }
}

/// The text after `mixin bootstrap:`: `ok`, or the failure's fallback label.
fn mixin_bootstrap_line(outcome: &MixinBootstrap) -> &str {
    outcome.as_ref().err().map_or("ok", String::as_str)
}

/// The two JVM effects registration needs, so the unavailable and
/// partial-failure paths run in a unit test instead of a started JVM.
trait MixinRegistrar {
    /// Whether `org.spongepowered.asm.mixin.Mixins` and its
    /// `addConfiguration(Ljava/lang/String;)V` exist.
    fn available(&mut self) -> bool;

    /// One `addConfiguration` call. Anything thrown is cleared either way;
    /// `Err` carries the label the failure line reports.
    fn add_configuration(&mut self, config: &str) -> Result<(), String>;
}

/// Mixin's public registration API, the same call Fabric's
/// `FabricMixinBootstrap` makes for each mod's parsed metadata.
const MIXINS_CLASS: &str = "org/spongepowered/asm/mixin/Mixins";
const ADD_CONFIGURATION: &str = "addConfiguration";
const ADD_CONFIGURATION_SIG: &str = "(Ljava/lang/String;)V";

/// [`MixinRegistrar`] over JNI. The `Mixins` class is resolved once, when
/// availability is checked, so N configs cost one class lookup and N calls.
struct JniMixinRegistrar<'env, 'local> {
    env: &'env mut JNIEnv<'local>,
    class: Option<JClass<'local>>,
}

impl<'env, 'local> JniMixinRegistrar<'env, 'local> {
    fn new(env: &'env mut JNIEnv<'local>) -> Self {
        Self { env, class: None }
    }
}

impl MixinRegistrar for JniMixinRegistrar<'_, '_> {
    fn available(&mut self) -> bool {
        let Ok(class) = self.env.find_class(MIXINS_CLASS) else {
            let _ = self.env.exception_clear();
            return false;
        };
        // A class without the method is as unavailable as a missing class:
        // keep the property hand-off and let the probe continue.
        if self
            .env
            .get_static_method_id(&class, ADD_CONFIGURATION, ADD_CONFIGURATION_SIG)
            .is_err()
        {
            let _ = self.env.exception_clear();
            return false;
        }
        self.class = Some(class);
        true
    }

    fn add_configuration(&mut self, config: &str) -> Result<(), String> {
        let Some(class) = self.class.as_ref() else {
            return Err("Mixins is not available".to_owned());
        };
        let name = self
            .env
            .new_string(config)
            .map_err(|error| format!("config name: {error}"))?;
        let name = JObject::from(name);
        match self.env.call_static_method(
            class,
            ADD_CONFIGURATION,
            ADD_CONFIGURATION_SIG,
            &[JValue::Object(&name)],
        ) {
            Ok(_) => Ok(()),
            Err(error) => {
                let fallback = (error.to_string() == "Java exception was thrown")
                    .then(|| exception_fallback(self.env))
                    .flatten();
                // One bad config must not poison the next call, and its
                // exception trace would repeat the config list per failure.
                let _ = self.env.exception_clear();
                Err(fallback.unwrap_or_else(|| error.to_string()))
            }
        }
    }
}

/// The registration stage: one `Mixins.addConfiguration` per config the
/// property carries, in the property's order. Pure apart from
/// [`MixinRegistrar`], so the skip, unavailable and partial-failure paths are
/// unit tested without a JVM.
///
/// Diagnostics stay bounded: a failing config gets one `failed` line (its
/// fallback label, never the whole config list), and one summary closes the
/// stage.
fn register_mixin_configs(
    bootstrap: Option<&MixinBootstrap>,
    configs: &[&str],
    registrar: &mut impl MixinRegistrar,
) -> Vec<String> {
    if !bootstrap.is_some_and(|bootstrap| bootstrap.is_ok()) || configs.is_empty() {
        return Vec::new();
    }
    if !registrar.available() {
        return vec!["mixin registration: unavailable".to_owned()];
    }
    let mut lines = Vec::new();
    let mut registered = 0usize;
    for config in configs {
        match registrar.add_configuration(config) {
            Ok(()) => registered += 1,
            Err(label) => lines.push(format!("mixin registration: failed ({label})")),
        }
    }
    lines.push(format!(
        "mixin registration: {registered}/{} registered",
        configs.len()
    ));
    lines
}

/// Mixin's static bootstrap (`MixinBootstrap.init`), the way Fabric's launch
/// handler runs it. Bounded to the classes the classpath already has: a missing
/// runtime or a thrown exception becomes a reported fallback label, never a
/// failed probe.
fn mixin_bootstrap_label(env: &mut JNIEnv) -> MixinBootstrap {
    let class = match env.find_class("org/spongepowered/asm/launch/MixinBootstrap") {
        Ok(class) => class,
        Err(_) => {
            let _ = env.exception_clear();
            return Err(fallback_label(
                "java.lang.ClassNotFoundException",
                Some("org.spongepowered.asm.launch.MixinBootstrap"),
            )
            .unwrap_or_default());
        }
    };
    match env.call_static_method(&class, "init", "()V", &[]) {
        Ok(_) => Ok(()),
        Err(error) => {
            let fallback = (error.to_string() == "Java exception was thrown")
                .then(|| exception_fallback(env))
                .flatten();
            let _ = env.exception_describe();
            let _ = env.exception_clear();
            Err(fallback.unwrap_or_else(|| error.to_string()))
        }
    }
}

/// The `MixinEnvironment$Side` constant a run sets. `None` is Mixin's default,
/// for a loader-lifecycle probe (`main`, `preLaunch`, `neoforge`) that has no game
/// environment to pick a side from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MixinSide {
    Client,
    Server,
}

impl MixinSide {
    fn selected(entry_kind: &str) -> Option<Self> {
        match entry_kind {
            "client" | "client_init" => Some(Self::Client),
            "server" | "server_init" => Some(Self::Server),
            _ => None,
        }
    }

    /// The enum's static field, read with `get_static_field`.
    fn field(self) -> &'static str {
        match self {
            Self::Client => "CLIENT",
            Self::Server => "SERVER",
        }
    }

    /// The `mixin phase:` value.
    fn label(self) -> &'static str {
        match self {
            Self::Client => "client",
            Self::Server => "server",
        }
    }
}

/// One step of the hand-off between registration and the first entrypoint.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MixinPhaseStep {
    /// `MixinBootstrap.onLoadingDone()V`.
    LoadingDone,
    /// `MixinEnvironment.getDefaultEnvironment()`, then its `setSide`.
    Environment,
}

/// The steps a run that reached Mixin performs, in order: `onLoadingDone`, which
/// Fabric calls once the loader registered the configs, then the side, which
/// `setSide` only assigns while it is still `UNKNOWN`.
const MIXIN_PHASE_STEPS: [MixinPhaseStep; 2] =
    [MixinPhaseStep::LoadingDone, MixinPhaseStep::Environment];

/// A step's result. Anything but `Ok` is reported, never fatal.
#[derive(Debug, Clone, PartialEq, Eq)]
enum PhaseOutcome {
    Ok,
    /// The class, method or field is not on the classpath.
    Unavailable,
    /// The call threw; the label is already bounded and exception-free.
    Failed(String),
}

/// The JVM effects the plan needs, so every outcome runs in a unit test instead
/// of a started JVM.
trait MixinPhaseDriver {
    /// `MixinBootstrap.onLoadingDone()V`; Mixin 0.8.7 ships no such method.
    fn loading_done(&mut self) -> PhaseOutcome;

    /// `MixinEnvironment.getDefaultEnvironment()`, then its `setSide` for a sided
    /// run. Resolution stops at the first unavailable step.
    fn set_side(&mut self, side: Option<MixinSide>) -> PhaseOutcome;
}

/// `mixin phase: <step>` with the outcome: `ok`, `unavailable`, or
/// `failed (<label>)`. The environment line carries no `ok`: the side it names is
/// the state a reader wants.
fn mixin_phase_line(
    step: MixinPhaseStep,
    side: Option<MixinSide>,
    outcome: &PhaseOutcome,
) -> String {
    let label = match step {
        MixinPhaseStep::LoadingDone => "loading-done",
        MixinPhaseStep::Environment => side.map_or("default", MixinSide::label),
    };
    match outcome {
        PhaseOutcome::Ok => match step {
            MixinPhaseStep::LoadingDone => format!("mixin phase: {label} ok"),
            MixinPhaseStep::Environment => format!("mixin phase: {label}"),
        },
        PhaseOutcome::Unavailable => format!("mixin phase: {label} unavailable"),
        PhaseOutcome::Failed(reason) => format!("mixin phase: {label} failed ({reason})"),
    }
}

/// The lifecycle stage after registration: one line per step, in
/// [`MIXIN_PHASE_STEPS`] order. Pure apart from [`MixinPhaseDriver`].
fn run_mixin_phase(
    bootstrap: Option<&MixinBootstrap>,
    side: Option<MixinSide>,
    driver: &mut impl MixinPhaseDriver,
) -> Vec<String> {
    if !bootstrap.is_some_and(|bootstrap| bootstrap.is_ok()) {
        return Vec::new();
    }
    MIXIN_PHASE_STEPS
        .iter()
        .map(|step| {
            let outcome = match step {
                MixinPhaseStep::LoadingDone => driver.loading_done(),
                MixinPhaseStep::Environment => driver.set_side(side),
            };
            mixin_phase_line(*step, side, &outcome)
        })
        .collect()
}

const MIXIN_BOOTSTRAP_CLASS: &str = "org/spongepowered/asm/launch/MixinBootstrap";
const MIXIN_ON_LOADING_DONE: &str = "onLoadingDone";
const MIXIN_ENVIRONMENT_CLASS: &str = "org/spongepowered/asm/mixin/MixinEnvironment";
const MIXIN_SIDE_CLASS: &str = "org/spongepowered/asm/mixin/MixinEnvironment$Side";
const MIXIN_SIDE_SIG: &str = "Lorg/spongepowered/asm/mixin/MixinEnvironment$Side;";
const MIXIN_GET_DEFAULT_ENVIRONMENT: &str = "getDefaultEnvironment";
const MIXIN_GET_DEFAULT_ENVIRONMENT_SIG: &str = "()Lorg/spongepowered/asm/mixin/MixinEnvironment;";
const MIXIN_SET_ACTIVE_ENVIRONMENT: &str = "setActiveEnvironment";
const MIXIN_SET_ACTIVE_ENVIRONMENT_SIG: &str = "(Lorg/spongepowered/asm/mixin/MixinEnvironment;)V";
const MIXIN_SET_SIDE: &str = "setSide";
const MIXIN_SET_SIDE_SIG: &str = "(Lorg/spongepowered/asm/mixin/MixinEnvironment$Side;)Lorg/spongepowered/asm/mixin/MixinEnvironment;";

/// [`MixinPhaseDriver`] over JNI. Every member is reflective, so a Mixin build
/// without one of them reports `unavailable` instead of failing.
struct JniMixinPhase<'env, 'local> {
    env: &'env mut JNIEnv<'local>,
}

impl<'env, 'local> JniMixinPhase<'env, 'local> {
    /// `find_class` with the pending `NoClassDefFoundError` cleared.
    fn find(&mut self, name: &str) -> Option<JClass<'local>> {
        let class = self.env.find_class(name).ok();
        if class.is_none() {
            let _ = self.env.exception_clear();
        }
        class
    }

    /// [`PhaseOutcome::Failed`] for a thrown call: the same fallback label the
    /// rest of the probe reports, with the exception cleared.
    fn failed(&mut self, error: jni::errors::Error) -> PhaseOutcome {
        let fallback = (error.to_string() == "Java exception was thrown")
            .then(|| exception_fallback(self.env))
            .flatten();
        let _ = self.env.exception_describe();
        let _ = self.env.exception_clear();
        PhaseOutcome::Failed(fallback.unwrap_or_else(|| error.to_string()))
    }

    /// `class.method(sig)`: `Unavailable` when either is missing, `Failed` when
    /// the call throws.
    fn static_call(
        &mut self,
        class: &str,
        method: &str,
        sig: &str,
        args: &[JValue],
    ) -> Result<JValueOwned<'local>, PhaseOutcome> {
        let Some(class) = self.find(class) else {
            return Err(PhaseOutcome::Unavailable);
        };
        if self.env.get_static_method_id(&class, method, sig).is_err() {
            let _ = self.env.exception_clear();
            return Err(PhaseOutcome::Unavailable);
        }
        match self.env.call_static_method(&class, method, sig, args) {
            Ok(value) => Ok(value),
            Err(error) => Err(self.failed(error)),
        }
    }

    /// `MixinEnvironment$Side.CLIENT` / `.SERVER`.
    fn side_constant(&mut self, side: MixinSide) -> Result<JObject<'local>, PhaseOutcome> {
        let Some(class) = self.find(MIXIN_SIDE_CLASS) else {
            return Err(PhaseOutcome::Unavailable);
        };
        if self
            .env
            .get_static_field_id(&class, side.field(), MIXIN_SIDE_SIG)
            .is_err()
        {
            let _ = self.env.exception_clear();
            return Err(PhaseOutcome::Unavailable);
        }
        match self
            .env
            .get_static_field(&class, side.field(), MIXIN_SIDE_SIG)
        {
            Ok(value) => value.l().map_err(|error| self.failed(error)),
            Err(error) => Err(self.failed(error)),
        }
    }
}

impl MixinPhaseDriver for JniMixinPhase<'_, '_> {
    fn loading_done(&mut self) -> PhaseOutcome {
        self.static_call(MIXIN_BOOTSTRAP_CLASS, MIXIN_ON_LOADING_DONE, "()V", &[])
            .map_or_else(|outcome| outcome, |_| PhaseOutcome::Ok)
    }

    fn set_side(&mut self, side: Option<MixinSide>) -> PhaseOutcome {
        // 1. `MixinEnvironment.getDefaultEnvironment()`.
        let default = match self.static_call(
            MIXIN_ENVIRONMENT_CLASS,
            MIXIN_GET_DEFAULT_ENVIRONMENT,
            MIXIN_GET_DEFAULT_ENVIRONMENT_SIG,
            &[],
        ) {
            Ok(value) => match value.l() {
                Ok(object) => object,
                Err(error) => return self.failed(error),
            },
            Err(outcome) => return outcome,
        };
        // 2. `getDefaultEnvironment().setSide(Side.CLIENT|SERVER)`. `setSide`
        // only assigns while the side is still `UNKNOWN`.
        if let Some(side) = side {
            let constant = match self.side_constant(side) {
                Ok(constant) => constant,
                Err(outcome) => return outcome,
            };
            let Ok(default_class) = self.env.get_object_class(&default) else {
                return PhaseOutcome::Unavailable;
            };
            if self
                .env
                .get_method_id(&default_class, MIXIN_SET_SIDE, MIXIN_SET_SIDE_SIG)
                .is_err()
            {
                let _ = self.env.exception_clear();
                return PhaseOutcome::Unavailable;
            }
            if let Err(error) = self.env.call_method(
                &default,
                MIXIN_SET_SIDE,
                MIXIN_SET_SIDE_SIG,
                &[JValue::Object(&constant)],
            ) {
                return self.failed(error);
            }
        }
        // 3. `MixinEnvironment.setActiveEnvironment(MixinEnvironment)` where the
        // runtime has it. Best effort: the side above is what the game reads.
        let _ = self.static_call(
            MIXIN_ENVIRONMENT_CLASS,
            MIXIN_SET_ACTIVE_ENVIRONMENT,
            MIXIN_SET_ACTIVE_ENVIRONMENT_SIG,
            &[JValue::Object(&default)],
        );
        PhaseOutcome::Ok
    }
}

/// Fabric runs `preLaunch` before the selected environment. NeoForge has no
/// such list, so its `@Mod` scan must not masquerade as one; an explicit
/// `--entry` bypasses discovery and preLaunch with it.
fn pre_launch_entries(
    jar: &Path,
    kind: &str,
    metadata: Option<&str>,
) -> Result<Vec<String>, String> {
    if metadata.is_none() || kind == "neoforge" {
        return Ok(Vec::new());
    }
    discover_entries(jar, "preLaunch")
}

/// NeoForge markers for a jar without Fabric metadata; diagnostics only.
fn neoforge_diagnostic(jar: &Path) -> Option<String> {
    neoforge_metadata(jar).ok()?.diagnostic()
}

fn report_neoforge_metadata(jar: &Path) {
    if let Some(line) = neoforge_diagnostic(jar) {
        eprintln!("horizon-jvm: {line}");
    }
}

/// Every jar under a folder, for `--libs`.
fn jars(dir: &Path) -> Result<(Vec<PathBuf>, usize), String> {
    let mut out = Vec::new();
    let mut skipped_game_jars = 0;
    let mut stack = vec![dir.to_path_buf()];
    while let Some(dir) = stack.pop() {
        let entries = fs::read_dir(&dir).map_err(|e| format!("{}: {e}", dir.display()))?;
        for entry in entries {
            let entry = entry.map_err(|e| format!("{}: {e}", dir.display()))?;
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
            } else if path.extension().is_some_and(|e| e == "jar") {
                if is_minecraft_runtime_jar(&path) {
                    skipped_game_jars += 1;
                } else {
                    out.push(path);
                }
            }
        }
    }
    out.sort();
    Ok((out, skipped_game_jars))
}

/// A full Minecraft client/server jar must not share `net.minecraft` packages
/// with the unsigned façade: HotSpot rejects that mix with a signer mismatch.
/// Libraries and mods can mention the package in a few descriptors, so use a
/// generous class-count threshold instead of filtering on one class name.
fn is_minecraft_runtime_jar(path: &Path) -> bool {
    let Ok(file) = File::open(path) else {
        return false;
    };
    let Ok(mut archive) = zip::ZipArchive::new(file) else {
        return false;
    };
    let mut game_classes = 0usize;
    for index in 0..archive.len() {
        let Ok(entry) = archive.by_index(index) else {
            continue;
        };
        if is_minecraft_class(entry.name()) {
            game_classes += 1;
            if game_classes >= 32 {
                return true;
            }
        }
    }
    false
}

fn is_minecraft_class(name: &str) -> bool {
    name.starts_with("net/minecraft/") && name.ends_with(".class")
}

/// Extract Fabric's `META-INF/jars/*.jar` entries and add them to the classpath.
/// A bundled Minecraft jar carries the same Log4j jars as the resolved loader
/// libraries. During a real Knot launch, registering both copies gives Log4j
/// classes two class loaders and its `UpperLookup` cast fails while building
/// the configuration. Keep the already-resolved loader copy for that opt-in
/// launch path; ordinary probes retain their previous nested-jar behavior.
fn expand_nested_jars(
    classpath: &mut Vec<PathBuf>,
    dedupe_log4j: bool,
) -> Result<NestedJars, String> {
    const MAX_NESTED_JARS: usize = 4096;
    let extracted = NestedJars::new()?;
    let mut index = 0;
    let mut serial = 0usize;
    while index < classpath.len() {
        let path = classpath[index].clone();
        index += 1;
        let Ok(file) = File::open(&path) else {
            continue;
        };
        let Ok(mut archive) = zip::ZipArchive::new(file) else {
            continue;
        };
        for entry_index in 0..archive.len() {
            let mut entry = archive
                .by_index(entry_index)
                .map_err(|e| format!("{}: reading zip entry: {e}", path.display()))?;
            let Some(name) = nested_jar_name(entry.name()) else {
                continue;
            };
            if dedupe_log4j && is_duplicate_log4j_jar(name, classpath) {
                continue;
            }
            if serial >= MAX_NESTED_JARS {
                return Err(format!(
                    "nested jar limit exceeded ({MAX_NESTED_JARS}); refusing an unbounded JiJ classpath"
                ));
            }
            let output = extracted.root.join(format!("{serial}-{name}"));
            serial += 1;
            let mut out =
                File::create(&output).map_err(|e| format!("{}: {e}", output.display()))?;
            std::io::copy(&mut entry, &mut out)
                .map_err(|e| format!("{}: {e}", output.display()))?;
            classpath.push(output);
        }
    }
    Ok(extracted)
}

fn is_duplicate_log4j_jar(name: &str, classpath: &[PathBuf]) -> bool {
    let lower = name.to_ascii_lowercase();
    if !lower.starts_with("log4j-") && !lower.starts_with("slf4j-") {
        return false;
    }
    classpath.iter().any(|path| {
        path.file_name()
            .and_then(|value| value.to_str())
            .is_some_and(|value| value.eq_ignore_ascii_case(name))
    })
}

fn nested_jar_name(entry: &str) -> Option<&str> {
    let name = entry.strip_prefix("META-INF/jars/")?;
    if name.is_empty() || name.contains('/') || !name.ends_with(".jar") {
        return None;
    }
    Some(name)
}

