    #[test]
    fn formats_fabric_add_mods_sorted_deduped_and_bounded() {
        let separator = classpath_separator();
        // No supplied jar, no property: the loader stays the only source.
        assert_eq!(fabric_add_mods(&[]), None);
        assert_eq!(fabric_add_mods(&[PathBuf::from("")]), None);
        assert_eq!(
            fabric_add_mods(&[
                PathBuf::from("mods/b.jar"),
                PathBuf::from("mods/a.jar"),
                PathBuf::from("mods/b.jar"),
            ])
            .as_deref(),
            Some(format!("mods/a.jar{separator}mods/b.jar").as_str())
        );
        // A path carrying the property's separator cannot be expressed, so it
        // is dropped rather than splitting into two mods.
        assert_eq!(
            fabric_add_mods(&[PathBuf::from(format!("mods/bad{separator}name.jar"))]),
            None
        );

        // The entry cap binds first for short paths...
        let many: Vec<PathBuf> = (0..600)
            .map(|index| PathBuf::from(format!("/mods/mod-{index:04}.jar")))
            .collect();
        let bounded = fabric_add_mods(&many).unwrap();
        assert_eq!(bounded.split(separator).count(), MAX_FABRIC_ADD_MODS);
        assert!(bounded.len() <= MAX_FABRIC_ADD_MODS_BYTES);
        assert!(bounded.starts_with("/mods/mod-0000.jar"));
        // ...and the byte cap stops a list of long paths before the entry cap.
        let long: Vec<PathBuf> = (0..600)
            .map(|index| PathBuf::from(format!("/mods/{index:04}-{}.jar", "x".repeat(180))))
            .collect();
        let bounded = fabric_add_mods(&long).unwrap();
        assert!(bounded.len() <= MAX_FABRIC_ADD_MODS_BYTES);
        assert!(bounded.split(separator).count() < MAX_FABRIC_ADD_MODS);
        assert!(bounded.starts_with("/mods/0000-"));
    }

    #[test]
    fn reports_declarations_against_what_the_loader_discovered() {
        // The report names declared ids the loader never reported, and stays
        // one line even when the lists are long.
        assert_eq!(
            discovery_line(&[], &[]),
            "discovery: 0 declared, 0 found, missing="
        );
        let declared = vec!["alpha".to_owned(), "beta".to_owned()];
        let found = vec!["alpha".to_owned(), "beta".to_owned()];
        assert_eq!(
            discovery_line(&declared, &found),
            "discovery: 2 declared, 2 found, missing="
        );
        assert_eq!(
            discovery_line(&declared, &found[..1]),
            "discovery: 2 declared, 1 found, missing=beta"
        );
        let many: Vec<String> = (0..200).map(|index| format!("mod-{index:03}")).collect();
        assert_eq!(
            discovery_line(&many, &many),
            "discovery: 200 declared, 200 found, missing="
        );
        // A jar without metadata declares nothing.
        assert!(declared_mod_ids(&[]).is_empty());
        assert!(declared_mod_ids(&[PathBuf::from("missing.jar")]).is_empty());
    }

    #[test]
    fn builds_the_fabric_developer_options_before_the_jvm_starts() {
        let separator = classpath_separator();
        let mods = format!("mods/a.jar{separator}mods/b.jar");
        // The supplied jars reach the loader through the documented property.
        assert_eq!(
            fabric_jvm_options(Some(&mods), false, false),
            vec![format!("-Dfabric.addMods={mods}")]
        );
        // A probe that asks for none of this adds no Fabric option, so existing
        // runs keep today's JVM arguments.
        assert!(fabric_jvm_options(None, false, false).is_empty());
        // Development mode is opt-in, and skipMcProvider only forwarded.
        assert_eq!(
            fabric_jvm_options(None, true, false),
            vec!["-Dfabric.development=true"]
        );
        assert_eq!(
            fabric_jvm_options(None, false, true),
            vec!["-Dfabric.skipMcProvider=true"]
        );
        assert_eq!(
            fabric_jvm_options(
                fabric_add_mods(&[PathBuf::from("mods/a.jar")]).as_deref(),
                true,
                true
            ),
            vec![
                "-Dfabric.addMods=mods/a.jar".to_owned(),
                "-Dfabric.development=true".to_owned(),
                "-Dfabric.skipMcProvider=true".to_owned(),
            ]
        );
        // `fabric.skipMcProvider` is forwarded, never invented: only a JVM
        // option the environment already carries turns it on.
        assert!(!skip_mc_provider_requested(&[]));
        assert!(!skip_mc_provider_requested(&[
            "-Dfabric.development=true".to_owned()
        ]));
        assert!(skip_mc_provider_requested(&[
            "-Xmx1g -Dfabric.skipMcProvider=true".to_owned()
        ]));
    }

    #[test]
    fn parses_game_provider_arguments() {
        let mut args = vec![
            "--game-jar".to_owned(),
            "mc/server.jar".to_owned(),
            "mods/mod.jar".to_owned(),
            "--game-version".to_owned(),
            "26.2".to_owned(),
            "--game-jar".to_owned(),
            "mc/extra.jar".to_owned(),
        ];
        let parsed = take_game_provider_args(&mut args).unwrap();
        assert_eq!(
            parsed.jars,
            [
                PathBuf::from("mc/server.jar"),
                PathBuf::from("mc/extra.jar")
            ]
        );
        assert_eq!(parsed.version, "26.2");
        assert_eq!(args, ["mods/mod.jar"]);

        // No flag keeps the default version and no production jars.
        let mut args = vec!["mods/mod.jar".to_owned()];
        let parsed = take_game_provider_args(&mut args).unwrap();
        assert!(parsed.jars.is_empty());
        assert_eq!(parsed.version, DEFAULT_GAME_VERSION);

        // An empty version is rejected before a JVM starts.
        let mut args = vec![
            "--game-version".to_owned(),
            "  ".to_owned(),
            "mods/mod.jar".to_owned(),
        ];
        assert!(take_game_provider_args(&mut args).is_err());
    }

    #[test]
    fn assembles_the_production_provider_properties() {
        assert!(game_provider_jvm_options(&[], "26.3", false).is_empty());
        let jars = [
            PathBuf::from("mc/server.jar"),
            PathBuf::from("mc/extra.jar"),
        ];
        // Only the first jar is Fabric's game jar; all of them reach the
        // classpath, but the property can name one.
        assert_eq!(
            game_provider_jvm_options(&jars, "26.3", false),
            vec![
                "-Dfabric.gameJarPath=mc/server.jar".to_owned(),
                "-Dfabric.gameJarPath.server=mc/server.jar".to_owned(),
                "-Dfabric.gameVersion=26.3".to_owned(),
            ]
        );
        assert_eq!(
            game_provider_jvm_options(&jars[..1], "26.2", true),
            vec![
                "-Dfabric.gameJarPath=mc/server.jar".to_owned(),
                "-Dfabric.gameJarPath.client=mc/server.jar".to_owned(),
                "-Dfabric.gameVersion=26.2".to_owned(),
            ]
        );
        // The entry kind chooses the side Fabric sees.
        assert!(client_side("client"));
        assert!(client_side("client_init"));
        assert!(!client_side("main"));
        assert!(!client_side("server"));
    }

